window.__D("text/maamarim-melukatim/c005",{"p":[[1500370004,"<h3>בס\"ד. מוצאי ש\"פ ויצא, ט' כסלו, אור ליו\"ד כסלו – בחדרו – ה'תשל\"ח<sup data-n=\"111\">*</sup></h3>\n<b>ושבתי</b> בשלום אל בית אבי גו'<sup data-n=\"112\">1</sup> [שפסוק זה הוא התחלת דרוש הראשון דפרשתנו בתורה אור מאדמו\"ר הזקן ובתורת חיים מאדמו\"ר האמצעי בעל הגאולה (דיו\"ד כסלו)<sup data-n=\"113\">2</sup> וההילולא (דט' כסלו). אלא שבתורת חיים מקדים (בתחילת הדרוש) הפסוק<sup data-n=\"114\">3</sup> וידר יעקב נדר גו' שלפני הפסוק ושבתי בשלום גו'], וידועים הדיוקים בזה, מהו אומרו ושבתי בשלום אל בית אבי, בשלום דוקא<sup data-n=\"115\">4</sup>. ובפרט שלפנ\"ז<sup data-n=\"114\">3</sup> אומר אם יהי' אלקים עמדי גו' ונתן לי לחם לאכול ובגד ללבוש, שהכוונה בזה היא גם ללחם ובגד ברוחניות<sup data-n=\"116\">5</sup>, בכל הפירושים שבזה, ואעפ\"כ אינו מסתפק בזה ומדגיש שחזרתו אל בית אביו תהי' בשלום דוקא. וגם צריך להבין מה שלאחרי ושבתי בשלום אל בית אבי מוסיף והי' הוי' לי לאלקים, הרי ענין זה דהוי' הוא האלקים הוא ענין אמיתי ותמידי (כמבואר בכ\"מ<sup data-n=\"117\">6</sup>), ומהו החידוש בהנ\"ל (והעילוי) בוהי' הוי' לי לאלקים<sup data-n=\"118\">7</sup>, ובפרט לאחרי ושבתי בשלום אל בית אבי. וגם צריך להבין מ\"ש לאח\"ז<sup data-n=\"119\">8</sup> והאבן הזאת אשר שמתי מצבה יהי' בית אלקים, איך שייך שאבן שהיא דומם [דגם לאחרי כל העילויים שבה (ע\"י אשר שמתי מצבה) נקראת היא בשם אבן, בחי' דומם] תהי' במדריגה נעלית כ\"כ שתהי' בית אלקים<sup data-n=\"120\">9</sup>. והנה מבואר בהדרושים<sup data-n=\"121\">10</sup> דפירוש והי' הוי' לי לאלקים הוא שיומשך אור נעלה יותר, שלגבי אור זה, הוי' (דעכשיו) יהי' (רק) בחי' אלקים. ופירוש והאבן הזאת גו' יהי' בית אלקים (שבא לאחרי ובהמשך לוהי' הוי' לי לאלקים) הוא שהאבן יהי' בית לאלקים שיהי' אז, להוי' שיהי' לאלקים. ועפ\"ז צריך ביאור יותר איך שייך שהאבן, דומם, יהי' בית לאלקים זה.ב) <b>והנה</b> מכיון שהתורה היא נצחית<sup data-n=\"122\">11</sup>, הרי מובן, שענין וידר יעקב נדר גו' הוא הוראה לכאו\"א מישראל בכל המקומות ובכל הזמנים. ויתירה מזו, מכיון שמעשה אבות סימן לבנים<sup data-n=\"123\">12</sup>, הרי ההוראה מענין וידר יעקב נדר גו' היא (ככל הענינים דמעשה אבות) ביתר שאת וביתר עוז. [ומזה מובן, שגם הנתינת כח שבהוראה זו היא לא רק נתינת כח סתם, ככל הוראות התורה (שהן גם נתינת כח<sup data-n=\"124\">13</sup>), אלא נתינת כח מיוחדת, מכיון שהוראה זו היא ממעשה אבות, ומעשה אבות הוא (לא רק סימן, אלא גם) נתינת כח<sup data-n=\"125\">14</sup> לבנים]. ומכיון שוידר יעקב נדר גו' בא בהמשך לויצא<sup data-n=\"126\">15</sup> יעקב מבאר שבע גו' [כמובן גם בפשטות, שהבקשה ושבתי בשלום אל בית אבי שייכת לויצא גו'. דלהיות שיצא מבאר שבע (ובית אביו) לכן ביקש שישוב ויחזור לשם, ושחזרתו תהי' בשלום], מובן מזה, שכ\"ה גם בנוגע לההוראה לכאו\"א מישראל מוידר יעקב נדר גו' [ומהבקשה ושבתי בשלום אל בית אבי גו'], שזה שייך לענין ויצא גו' מבאר שבע כמו שהוא בכאו\"א מישראל.\nג) <b>ויובן</b> זה בהקדים מ\"ש בדרושי רבותינו נשיאינו<sup data-n=\"127\">16</sup> (מיוסד על מ\"ש בזהר<sup data-n=\"128\">17</sup>) עה\"פ ויצא יעקב מבאר שבע גו', שיש בזה ב' פירושים, פירוש א', שבאר שבע הוא באר שבע דאברהם (שקרא למקום ההוא באר שבע כי שם נשבעו שניהם<sup data-n=\"129\">18</sup>), ופירוש ב', שבאר שבע הוא באר שבע דיצחק (שקרא אותה שבעה, ע\"ש הבאר השביעית<sup data-n=\"130\">19</sup>). וכ\"ה גם בפשטות, שהרי ויצא יעקב מבאר שבע הי' בזמנו של יצחק (כו\"כ שנים לאחרי הסתלקות אברהם). וההפרש בין ב' הענינים הוא, דבאר שבע דאברהם הוא בינה (יסוד אימא). שהרי אברהם הוא חכמה [אלא שמתחילה נקרא אברם, אב <i>רם</i>, שהחכמה (אב) שבו היתה בבחי' שכל הנעלם מכל רעיון<sup data-n=\"131\">20</sup>, ואח\"כ נקרא אברהם שנעשה אב המון גוים<sup data-n=\"132\">21</sup>, שהחכמה (אב) שבו נמשכה בגילוי גם למטה עד לבחי' המון גוים<sup data-n=\"133\">22</sup>], ובאר שבע דאברהם [המקום דאברהם, המקבל שלו, בחי' שרה<sup data-n=\"134\">23</sup>] הוא בינה, ונקראת באר שבע לפי שהיא המקור המשפיעלשבע מדות. ולפי זה, פירוש ויצא יעקב מבאר שבע וילך חרנה הוא שיצא ונמשך מבחי' בינה למלכות. ובאר שבע דיצחק הוא מלכות. כי יצחק הוא בינה<sup data-n=\"135\">24</sup>, והמקבל דבינה היא מלכות<sup data-n=\"136\">25</sup>, ונקראת באר שבע על שם שהיא מקבלת משבע מדות [וכידוע שהמלכות נקראת כנסת ישראל, לפי שהיא כונסת לתוכה בחי' המדות<sup data-n=\"137\">26</sup>]. ולפי זה, פירוש ויצא יעקב מבאר שבע וילך חרנה קאי על היציאה וההמשכה לעולמות בי\"ע, ומשם יפרד<sup data-n=\"138\">27</sup>. וכ\"ה גם בפשטות ענין היציאה, שהרי ויצא יעקב הי' בכדי לברר הניצוצות שהיו אצל לבן (כמסופר בפרשת ויצא) [ולאח\"ז גם הניצוצות שהיו אצל עשו (כמסופר בפרשת וישלח)], ובירור הניצוצות הוא בעולמות בי\"ע.\nד) <b>וזהו</b> גם ששם הסדרה [המורה על ענינה ותוכנה<sup data-n=\"139\">28</sup>] הוא ויצא, כי כל ענין הבירורים שבירר יעקב אצל לבן המבואר בהסדרה [וגם מה שבירר אצל עשו המבואר בפרשת וישלח, שבא לאחרי ובהמשך להבירורים שבירר אצל לבן<sup data-n=\"140\">29</sup>] הותחל מיציאתו מבאר שבע – ענין ויצא. וזה שיציאתו היתה באופן כזה שיברר הניצוצות שבחרן, ותהי' מטתו שלימה, לא כאברהם שיצא ממנו ישמעאל ולא כיצחק שיצא ממנו עשו<sup data-n=\"141\">30</sup>, הענין הוא, דהנה כתיב<sup data-n=\"142\">31</sup> וידו אוחזת בעקב עשו (ולכן) ויקרא שמו יעקב. שבשם יעקב יש ב' חלקים. יו\"ד (ידו אותיות יו\"ד<sup data-n=\"143\">32</sup>) ועקב. וכמבואר בתו\"א ריש פרשתנו, שיעקב הוא בחי' יו\"ד עקב<sup data-n=\"144\">33</sup>, היינו המשכת בחי' חכמה עילאה [היו\"ד דשם הוי'<sup data-n=\"145\">34</sup>] בבחי' עקביים. וע\"י המשכת היו\"ד בהעקב דיעקב [ועד אשר היו\"ד היא ההתחלה והראש דתיבת יעקב, היינו שהיו\"ד היא מנהיגה את העקב<sup data-n=\"146\">35</sup>], הנה עי\"ז הי' אפ\"ל ויצא יעקב גו' וילך חרנה, להמשיך היו\"ד גם בבחי' העקב דעולמות, עד בעוה\"ז התחתון שאין תחתון למטה ממנו, שיהי' דירה לו ית'. [כי מכיון שהיו\"ד דיעקב היא (כנ\"ל) היו\"ד דשם הוי' שהוא הי' הוה ויהי' כאחד<sup data-n=\"147\">36</sup> (היינו שהכל הוא בשוה לגבי'), לכן גם כמו שהיו\"ד נמשכת בבחי'העקב דעולמות, היא בתקפה. ונוסף לזה, מכיון שהוי' הוא מלשון מהווה<sup data-n=\"148\">37</sup>, והיו\"ד שבו מורה על תמידות ההתהוות<sup data-n=\"149\">38</sup>, הרי היו\"ד היא המושלת ושולטת בכל העולמות עד בהעקב שבהם, מכיון שכל מציאותם הוא הדבר הוי' המהווה אותם תמיד מאין ליש]. וזהו ויצא יעקב מבאר שבע וילך חרנה, שיעקב ממשיך היו\"ד דשם הוי' גם בבחי' חרן, שקאי [כנ\"ל (סעיף ג) בפירוש הב'] על עולמות בי\"ע, ובבי\"ע גופא חרון אף של עולם<sup data-n=\"150\">39</sup>, עוה\"ז התחתון שאין תחתון למטה ממנו, שיהי' דירה לו ית' בתחתונים.\nה) <b>והנה</b> ירידה זו (ויצא יעקב מבאר שבע וילך חרנה) היא צורך עלי'. ונוסף להעלי' שנעשה בו לאחרי וע\"י עבודתו בחרן [שע\"י שבירר הניצוצות דלבן ועשו הגיע למדריגה נעלית יותר מכמו שהי' לפנ\"ז, ושבתי בשלום אל בית אבי וגו', כמשי\"ת לקמן], הנה גם לפנ\"ז, בכדי שיוכל להמשיך (היו\"ד) בבחי' חרן ולברר הניצוצות, נמשך בו כח נעלה יותר, שלא הי' לו תחילה (בגילוי). [וע\"ד הידוע<sup data-n=\"151\">40</sup> (גבי אברהם שהי' גדול בענקים<sup data-n=\"152\">41</sup> וראש לאבות<sup data-n=\"153\">42</sup>), שבכדי שיהי' אב המון גוים להעלות הניצוצות שבגוים (הגרים), נתוסף לו ה' שלא הי' לו תחילה].\n<b>ויש</b> לומר שזהו מה שמובא בתו\"א ותו\"ח תיכף ובהמשך לויצא יעקב מבאר שבע מש\"נ<sup data-n=\"154\">43</sup> צוה ישועות יעקב, שהוא המשכת בחי' שע\"ה נהורין דאריך<sup data-n=\"155\">44</sup>, כי כמו שענין הישועה בפשטות הוא סיוע ונתינת כח מיוחד שלא ע\"ד הרגיל, ונתינת כח זה הוא דוקא בשביל האדם שמושיעים אותו שהוא במעמד ומצב שפל ביותר שצריך לישועה, עד\"ז הוא גם בפירוש הפנימי דישועות, שענינם הוא שע\"ה נהורין דאריך, שהמשכתן (ליעקב) היא דוקא בשביל המצב דיציאתו מבאר שבע והליכתו חרנה. שבכדי שיוכל להמשיך היו\"ד גם בחרן, צריך להיות צוה ישועות יעקב, להמשיך ליעקב שע\"ה נהורין דאריך שלמעלה מהשתלשלות, למעלה גם מהיו\"ד דשם הוי', היו\"ד דיעקב.\n<b>ויש</b> להוסיף בדיוק לשון הכתוב צוה ישועות יעקב (צוה דוקא), שהמשכת הישועות (שע\"ה נהורין) ליעקב תהי' באופן דצוה, לשון צותא וחיבור<sup data-n=\"156\">45</sup>. דהגם שהשע\"הנהורין הם למעלה מיעקב, למעלה גם מהיו\"ד שבו, מ\"מ, יהיו מחוברים ומיוחדים עמו, אַז זיי ווערן אָפּגעגעבן צו אים בפנימיות. וע\"י שנמשך ליעקב בחי' ישועות הנ\"ל (לצורך הליכתו לחרן), הי' בטוח (עוד לפני הליכתו לחרן<sup data-n=\"157\">46</sup>) שתתקיים תפלתו, שיהי' ונתן לי לחם לאכול ובגד ללבוש, ויתירה מזו – ושבתי בשלום אל בית אבי, ויתירה מזו – והי' הוי' לי לאלקים, ויתירה מזו – והאבן הזאת אשר שמתי מצבה יהי' בית אלקים.\nו) <b>והנה</b> תפלתו של יעקב (באופן דנדר<sup data-n=\"158\">47</sup>) אם יהי' אלקים עמדי גו' והאבן הזאת גו' יהי' בית אלקים היתה לאחרי העבודה דויקח<sup data-n=\"159\">48</sup> מאבני המקום וישם מראשותיו. והענין הוא, מקום הוא הגדר דעולם, כדאיתא בתניא<sup data-n=\"160\">49</sup> שגדר העולם הוא מקום (וזמן). [והגם שמקום הוא שמו של הקב\"ה שנקרא מקום, לפי שהוא מקומו של עולם<sup data-n=\"161\">50</sup>, הרי ענין זה הוא בהעלם, ומה שנרגש בגילוי בהמקום הוא העולם. דזהו מה שהוי' ברבוע בגימטריא מקום<sup data-n=\"162\">51</sup>, היינו שענין הוי' שנמשך במקום הוא רק באופן דגימטריא שהוא חשבון האותיות, שהחשבון מורה<sup data-n=\"163\">52</sup> על מיעוט האור כו' מיעוט אחר מיעוט]. ואבני המקום (בחי' דומם) הם סוג היותר תחתון שבעולם. ובזה גופא אבני לשון רבים, כמו שהם בבחי' ריבוי ההתחלקות. וזהו ויקח מאבני המקום וישם מראשותיו, שיעקב עשה<sup data-n=\"164\">53</sup> מאבני המקום (אבני לשון רבים) אבן אחת [שלכן כתיב וישם ולא וישימם<sup data-n=\"165\">54</sup>], ולא עוד, אלא שוישם מראשותיו, שהגבי' והעלה את האבן עד שיגבי' את ראשו, וי\"ל עוד יתירה מזה שהאבן למעלה מראשו<sup data-n=\"166\">55</sup> של יעקב, היינו למעלה מבחי' היו\"ד דיעקב<sup data-n=\"167\">56</sup> (שהוא הראש שלו, כנ\"ל). ועל זה התפלל והאבן הזאת גו' יהי' בית אלקים, שהאבן הזאת (אבן אחת, שעשה מריבוי אבנים) תהי' לא רק למעלה מבחי' הראש (היו\"ד) דיעקב, אלא שתהי' למעלה יותר – בית אלקים, בית (ודירה) לעצמותו ית'.ז) <b>והנה</b> ג' ענינים הנ\"ל שהיו ביעקב – (א) יציאתו מבאר שבע לחרן, (ב) עבודתו (לאחרי היציאה מבאר שבע) ויקח מאבני המקום גו', (ג) (שע\"י התפלה שלו) נעשתה האבן הזאת (שלקח מאבני המקום) בית אלקים – ישנם גם בכאו\"א מישראל. דמעשה אבות סימן ונתינת כח לבנים (כנ\"ל סעיף ב), ובפרט הענינים דיעקב. דמכיון ששופרי' דיעקב מעין שופרי' דאדה\"ר<sup data-n=\"168\">57</sup>, ונשמתו כלולה מכל הנשמות שבישראל (כנשמת אדה\"ר<sup data-n=\"169\">58</sup>)<sup data-n=\"170\">59</sup>, הרי עבודתו של יעקב (ויקח מאבני המקום גו') היא נתינת כח לבנים ביתר שאת וביתר עוז.\n<b>והענין</b> הוא, דויצא יעקב מבאר שבע וילך חרנה קאי<sup data-n=\"171\">60</sup> על ירידת הנשמה בגוף, שירדה מאיגרא<sup data-n=\"172\">61</sup> רמה (באר שבע) לבירא עמיקתא (חרנה). וכמו שיעקב, בכדי שיוכל ללכת לחרן נמשך לו כח נעלה יותר – ענין צוה ישועות יעקב (כנ\"ל סעיף ה), עד\"ז הוא גם בוילך חרנה שבכאו\"א מישראל, שלפני ירידת הנשמה למטה לבירא עמיקתא, שזהו\"ע וילך חרנה, נותנים לה כח במיוחד שתוכל לעבוד עבודתה בבירור הגוף ונפש הבהמית וחלקה בעולם. וכידוע<sup data-n=\"173\">62</sup> בענין משביעין אותו תהי צדיק ואל תהי רשע<sup data-n=\"174\">63</sup>. וזהו מ\"ש ויצא יעקב מבאר שבע גו', שפירוש מבאר שבע הוא<sup data-n=\"175\">64</sup> מה שמשביעין אותו תהי צדיק כו' [שיש בזה ג' פירושים, שבועה, שובע ושבע, כמבואר בכ\"מ<sup data-n=\"176\">65</sup>] שהוא נתינת כח במיוחד על עבודת הנשמה בירידתה למטה.\nח) <b>והנה</b> עבודת הנשמה בירידתה למטה היא (בכללות) בשני ענינים. א', לימוד התורה וקיום המצוות, דע\"י לימוד התורה וקיום המצוות למטה דוקא מתעלית הנשמה למעלה יותר מכמו שהיתה קודם ירידתה. וכידוע<sup data-n=\"177\">66</sup> דהתורה והמצוות שלמטה דוקא נעשים לבוש להנשמה בג\"ע שעל ידם היא משגת ונהנית מאוא\"ס. וב', הבירור דגוף ודנפש הבהמית וחלקו בעולם. שזה נעשה ע\"י קיום המצוות<sup data-n=\"178\">67</sup>, וי\"ל עוד יותר – ע\"י העבודה דכל מעשיך יהיו לשם שמים<sup data-n=\"179\">68</sup>, ובפרט ע\"י בכלדרכיך דעהו<sup data-n=\"180\">69</sup>, דלא רק שעשייתו דברי הרשות תהי' <i>לשם</i> שמים, אלא שגם בהם גופא (<i>ב</i>כל דרכיך) יהי' דעהו<sup data-n=\"181\">70</sup> [דעת באלקות, שדעת הוא למעלה גם מחכמה, כמבואר בארוכה בהמשך עת\"ר<sup data-n=\"182\">71</sup> ובכ\"מ]. וזהו ונתן לי לחם לאכול ובגד ללבוש ושבתי בשלום אל בית אבי, לחם לאכול ובגד ללבוש הוא לימוד התורה וקיום המצוות<sup data-n=\"183\">72</sup> כידוע<sup data-n=\"184\">73</sup> שתורה היא לחם ומזון הנשמה והמצוות הם לבושים דהנשמה, ושבתי בשלום הו\"ע עבודת הבירורים.\nט) <b>וזהו</b> שהעבודה שלאחרי ויצא יעקב מבאר שבע וילך חרנה (ירידת הנשמה בגוף) היא ויקח מאבני המקום גו'. דהנה ידוע<sup data-n=\"185\">74</sup> שהכוונה בירידת הנשמה למטה היא לא בשביל הנשמה אלא בכדי לברר ולזכך הגוף ונה\"ב וחלקו בעולם, שעי\"ז דוקא נתגלה הכוונה דנתאוה<sup data-n=\"186\">75</sup> הקב\"ה להיות לו ית' דירה בתחתונים, בתחתון שאין תחתון למטה ממנו<sup data-n=\"187\">76</sup>. וזהו שעיקר עבודת הנשמה בירידתה למטה (ויצא יעקב גו' חרנה) הוא ויקח מאבני המקום גו', \"מקום\" הוא מציאות כזו שהאור האלקי שבו הוא בהעלם והסתר [וכנ\"ל (סעיף ו) דזה ששם הוי' (ברבוע) בגימטריא מקום – הכוונה בזה היא, ששם הוי' הוא בהעלם והסתר בהמקום (באופן דגימטריא). דהגם שכל מציאות המקום (עולם) הוא ששם הוי' מהווה אותו תמיד מאין ליש, מ\"מ אופן מציאותו של שם הוי' בהעולם הוא רק באופן של גימטריא, בחי' העלם והסתר], ובזה גופא – אבני המקום, אבני לשון רבים (כנ\"ל), והתכלית דירידת הנשמה למטה (ויצא יעקב גו' חרנה) הוא (לא בשביל האור שנמשך לה ע\"י תורה ומצוות, כי אם) בשביל העבודה דויקח מאבני המקום, לקחת את הדברים התחתונים (הגוף ונה\"ב וחלקו בעולם), ובאופן דויקח שנעשה בעה\"ב ומושל ושולט עליהם, ולעשות מהם דירה לו ית'.\n<b>ויש</b> להוסיף, דבענין הבירורים גופא יש יתרון בהבירור דדברי הרשות ע\"י שעושה אותם לשם שמים על הבירור דדברים הגשמיים שע\"י קיום המצוות, כי ע\"י הבירור דדברי הרשות (שגם כשעושה אותם לשם שמים הם נשארים דברי הרשות, מעשי<i>ך)</i> נשלמת יותר הכוונה דדירה בתחתונים, תחתון שאין תחתון למטה ממנו. ועפ\"ז יובן יותר זה שהעבודה (שבשבילה ירדה הנשמה למטה) היא \"ויקח מאבני המקום\", ד\"מקום\" הוא מציאות כזו שהאור האלקי שבו הוא בהעלם והסתר כנ\"ל, דיש לומר, שקאי (בעיקר) על דברי הרשות, שגם לאחרי העבודה הם \"מעשי<i>ך</i>\" דהאדם.יו\"ד) <b>ועפ\"ז</b> יובן גם גודל העלי' דאבני המקום [לאחרי שנעשים אבן אחת, ע\"י עבודת הבירורים], שהם מתעלים למעלה מבחי' הראש דיעקב (וישם מראשותיו), ועד אשר (לאחרי גמר הבירורים) והאבן הזאת גו' יהי' בית אלקים, שהכוונה בזה היא (כנ\"ל סעיף א) לא לאלקים סתם כ\"א לבחי' והי' הוי' לי לאלקים. דהנה ידוע<sup data-n=\"188\">77</sup> שתכלית הכוונה האמיתית בבריאת והתהוות העולמות הוא מה שנתאוה הקב\"ה להיות לו ית' דירה בתחתונים, בעוה\"ז הגשמי שאין תחתון למטה ממנו. דהגם שיש כמה טעמים לברה\"ע<sup data-n=\"189\">78</sup> [בגין דישתמודעון לי'<sup data-n=\"190\">79</sup> ובכדי שיתגלו שלימות כוחותיו כו'<sup data-n=\"191\">80</sup>], הנה טעמים אלו הם בנשמות דאצילות (הטעם בגין דישתמודעון) ובבחי' האצילות (הטעם בכדי שיתגלו), ומקום ושרש טעמים אלו הוא בבחי' הגילויים. משא\"כ ענין נתאוה הקב\"ה להיות לו ית' דירה בתחתונים [שמצד זה הוצרך להיות התהוות עוה\"ז התחתון דוקא שאין תחתון למטה ממנו] הוא בעצמותו ית'. וכמאמר רבינו הזקן<sup data-n=\"192\">81</sup> (בענין נתאוה כו' דירה בתחתונים) \"אויף אַ תאוה איז קיין קשיא\", שהענין דנתאוה הוא בעצמותו ית' שאין שייך שם ענין הקושיות. וזהו והאבן הזאת גו' יהי' בית אלקים, שהכוונה באלקים כאן היא לבחי' העלם העצמי, שהדברים הגשמיים דוקא (בחינת אבן, דומם) יהיו בית ודירה לעצמותו ית'.\nיא) <b>והנה</b> ענין ויקח מאבני המקום גו' ישנו גם בהאדם עצמו. והענין הוא, דהנה ידוע<sup data-n=\"193\">82</sup> שאבנים הן אותיות<sup data-n=\"194\">83</sup>, כי כמו שאבנים הן דומם כן האותיות הם בחי' הדומם שבכחות האדם. אבל אעפ\"כ, ומטעם זה גופא, ממשיכים הם (אותיות מלשון אתא<sup data-n=\"195\">84</sup> בוקר<sup data-n=\"196\">85</sup>, ענין המשכה) בחינת אור נעלה ביותר. וע\"ד הידוע<sup data-n=\"197\">86</sup> בפירוש הכתוב<sup data-n=\"198\">87</sup> כי לא על הלחם לבדו יחי' האדם כי על כל מוצא פי הוי' יחי' האדם, דזה שהלחם מחי' את האדם הוא לפי שהמוצא פי הוי' שבלחם (צומח) הוא נעלה יותר (בשרשו) מהמוצא פי הוי' שבאדם, דזה גופא שירד למטה יותר מורה שבשרשו הואנעלה יותר, דכל הגבוה יותר יורד למטה יותר, עד\"ז הוא גם בענין האותיות, דומם (שבאדם), ששרשם הוא למעלה יותר גם מבחי' צומח<sup data-n=\"199\">88</sup>, דכל הגבוה גבוה<sup data-n=\"200\">89</sup> יותר יורד למטה מטה יותר. וזהו\"ע ויקח מאבני המקום וישם מראשותיו (כמו שהוא בעבודת כאו\"א מישראל), שהעבודה דבחי' אותיות, דומם שבאדם, מגעת למעלה יותר מהעבודה דבחי' השכל (מראשותיו).\nיב) <b>ושני</b> פירושים הנ\"ל בויקח מאבני המקום גו' [העבודה בבחי' הדומם שבאדם (דלעיל סעיף יא) והעבודה דבירור דברים הגשמיים שבעולם (דלעיל סעיף ט)] שייכים זה לזה. כי הבירור דעניני עוה\"ז הגשמי (אבני המקום דעולם) הוא ע\"י הדומם שבאדם, כח הדיבור, ובעיקר – כח המעשה<sup data-n=\"201\">90</sup>, שהמעשה הוא העיקר<sup data-n=\"202\">91</sup>. ויש להוסיף, שהשייכות דשני ענינים אלו היא לא רק מצד ענין ה\"תחתון\" (אבן, דומם) שבהם [שהפעולה בגשמיות העולם היא ע\"י כחות התחתונים שבאדם], כי אם, גם בנוגע לענין העילוי שבהם (וישם מראשותיו). והיינו, דזה שבכחו של כאו\"א מישראל לעשות מחלקו בעולם דירה לו ית', לו לעצמותו<sup data-n=\"203\">92</sup>, הוא לפי שע\"י עבודתו בכחות התחתונים שלו מתגלה עצם הנשמה המיוחד בעצמותו ית'<sup data-n=\"204\">93</sup>.\n<b>ויובן</b> זה בהקדים המבואר בכ\"מ<sup data-n=\"205\">94</sup> בענין היו\"ד דשם הוי' שבנפש האדם שהוא בחי' חי'. ומכיון שבחי' הראש דיעקב [שהוא היו\"ד דיעקב, שהוא היו\"ד דשם הוי' (כנ\"ל סעיף ד)] הוא בחי' חי', מובן מזה, דזה שהעבודה דבחי' דומם שבאדם מגעת למעלה מבחי' ראש דיעקב (כנ\"ל (סו\"ס יא) בפירוש ויקח מאבני המקום וישם מראשותיו), הכוונה בזה היא – שע\"י העבודה דבחי' דומם שבאדם, מתגלית בחינת היחידה שבו (שלמעלה מבחי' חי'). כי ענין העבודה דבחי' דומם שבאדם, היינו דהגם שאין לו שום חיות (לא מצד הרגש המדות שבלב, ולא מצד השכל שבמוח, וגם לא מצד הרצון שלמעלה מהשכל (בחי' חי')) ומ\"מ הוא עובד את עבודתו, הוא מצד העצם שלו, מה שכל אחד מישראל בעצם מהותו הוא רוצה לעשות כל מה שהוא רצון ה', כפס\"ד הרמב\"ם<sup data-n=\"206\">95</sup> הידוע. וזהו שכאו\"א מישראל, גםקל שבקלים, יכול למסור נפשו על קדה\"ש<sup data-n=\"207\">96</sup>, כי כח המס\"נ הוא מצד העצם שלו בחי' יחידה<sup data-n=\"208\">97</sup>, שלגבי בחינה זו אין שייך שום מנגד, בבואה דבבואה לית להו<sup data-n=\"209\">98</sup>. [וזהו גם מה <i>שהבטיחה</i> תורה שסוף ישראל לעשות תשובה כו' ומיד הן נגאלין<sup data-n=\"210\">99</sup>, שהכוונה ב\"סוף ישראל לעשות תשובה\" היא (גם) לכאו\"א מישראל<sup data-n=\"211\">100</sup> – כי על בחינת היחידה שבכ\"א מישראל אין שייך שום מנגד ח\"ו אלא שהיא בהעלם, ותורת אמת מבטיחה שסו\"ס תהי' בגילוי].\n<b>וזוהי</b> השייכות דשני הפירושים בויקח מאבני המקום גו' [העבודה בבחי' הדומם שבאדם, והעבודה דבירור דברים הגשמיים שבעולם שיהיו דירה לו ית'], כי הכח שיש בישראל לעשות מהעולם דירה לו ית', <i>ליחידו</i> של עולם [ע\"י שעושה מאבני המקום דעולם (אבני לשון רבים) שיהיו אבן אחת. שהו\"ע המשכת הוי' אחד, שגם בשמים ובארץ ובד' רוחות העולם (ח' וד'<sup data-n=\"212\">101</sup>), עם היותם בחינת התחלקות ופירוד, מ\"מ ע\"י גילוי אלופו של עולם (א'<sup data-n=\"212\">101</sup>) מתייחדים באחד ממש<sup data-n=\"213\">102</sup>, שאחד זה (דהוי' אחד) הוא כמו יחיד<sup data-n=\"214\">103</sup>], הוא מצד בחי' היחידה שבו, שמקבלת<sup data-n=\"215\">104</sup> מיחיד.\nיג) <b>והנה</b> הגם שהתעוררות היחידה וכח המס\"נ הוא (בדרך כלל) ע\"י העבודה דבחי' דומם, היינו כשהאדם הוא במצב דעניות (בדעת<sup data-n=\"216\">105</sup>), שכחות הפנימיים דנה\"א הם בהעלם ואין לו השגה והרגש באלקות (כנ\"ל סעיף יב), מ\"מ,לאחרי שמעורר את כח המס\"נ בהיותו במצב דעניות, הנה זה פועל גם גילוי כחות הפנימיים דנה\"א<sup data-n=\"217\">106</sup>. וע\"ד הבטחת חז\"ל<sup data-n=\"218\">107</sup> כל המקיים את התורה מעוני סופה לקיימה מעושר, עשירות בדעת, וגם עשירות (והרחבה) בענינים הגשמיים, בבני חיי ומזוני (ובכולם) רויחי [ועד שהעשירות וההרחבה בעניניו הגשמיים היא בריבוי ושופי למעלה ממדידה והגבלה, שאז עשירות זו גופא מביאה לעשירות בדעת, כי גם השכל דנה\"ב משיג שעשירות גדולה כזו (למעלה ממדידה והגבלה) יכולה לבוא רק מה' מקור כל הברכות], וגם אז אופן עבודתו היא במס\"נ למעלה מהשכל. דזהו פירוש כל המקיים את התורה מעוני סופה לקיימה מעושר, שמקיימה מעושר באותו העילוי (מס\"נ שלמעלה מהגבלה) כמו שקיימה מעוני. דזהו\"ע בכל מאדך<sup data-n=\"219\">108</sup> שלאחרי בכל לבבך ובכל נפשך<sup data-n=\"219\">108</sup>, היינו, שענין המס\"נ (למעלה מהשכל) בבכל מאדך הוא לא מצד שחסר ח\"ו בהשגת השכל שלו, כי אם, שהגם שעבודתו היא בכל כחות נפשו (בכל נפשך) שראשיתם הוא כח השכל, ועד שזה מושג גם בהשכל דנה\"ב שלו (בכל לבבך בשני יצריך<sup data-n=\"220\">109</sup>), מ\"מ עבודתו היא במס\"נ שלמעלה מהגבלת השכל, בכל מאדך.\n<b>וזהו</b> ג\"כ מ\"ש ביעקב [שמזה מובן, שכ\"ה גם בכ\"א מישראל], לאחרי עבודתו בהבירור דצאן לבן (שעיקר הבירור הוא בהצאן<sup data-n=\"221\">110</sup>), ויפרוץ האיש מאד מאד גו'<sup data-n=\"222\">111</sup> [מאד סתם, שלמעלה מבחי' מאד שלך<sup data-n=\"223\">112</sup>], כי ע\"י העבודה דבחי' בכל מאדך (מאד שלך) מגיעים לבחי' מאד האמיתי<sup data-n=\"224\">113</sup>. ונאמר מאד מאד (ב' פעמים)<sup data-n=\"225\">114</sup>, דע\"י שהעבודה דבכל מאדך היא נוסף על מצד המקיף דחי' גם מצד המקיף דיחידה, עי\"ז גם ההמשכה שלמעלה היא מאד מאד ב' פעמים, בחי' אריך וגם בחי' עתיק. ואין מקרא יוצא מידי פשוטו<sup data-n=\"226\">115</sup>, שויפרוץ האיש מאד מאד (ויהי לו צאן רבות וגו') הוא (גם) בגשמיות, כי ע\"י העבודה דבכל מאדך, הוא עושה רצונו של מקום<sup data-n=\"227\">116</sup>, היינו שהוא (למעלה מבחי' רצונו של מקום) עושה את הרצון<sup data-n=\"228\">117</sup>, כולל גם הפירוש דעושהמלשון מעשין על הצדקה<sup data-n=\"229\">118</sup>, שהוא מכריח כביכול את הרצון<sup data-n=\"230\">119</sup>, צדיק גוזר והקב\"ה מקיים כמ\"ש<sup data-n=\"231\">120</sup> ותגזר אומר ויקם לך<sup data-n=\"232\">121</sup> [ויתירה מזו הקב\"ה גוזר וצדיק מבטל<sup data-n=\"233\">122</sup>], שנעשה בעה\"ב על כל חלקו בעולם, שיהי' לו הרחבה בכל עניניו, הן בענינים הרוחניים והן בענינים הגשמיים, טוב בריבוי ברכה בריבוי ושלום בריבוי<sup data-n=\"234\">123</sup>, עשירות ברוחניות ועשירות בגשמיות, ובגשמיות וברוחניות גם יחד.\nיד) <b>וביאור</b> הענין (דעיקר העבודה שבשבילה ירדה הנשמה למטה היא ויקח מאבני המקום גו') בעומק יותר, יובן בהקדים שהיתרון בהעבודה דכל מעשיך לשם שמים ובכל דרכיך דעהו על העבודה דלימוד התורה וקיום המצוות הוא לא רק בנוגע להפעולה בעולם, שע\"י העבודה בכל מעשיך לשם שמים מתברר גם התחתון דעולם (כנ\"ל סעיף ט), אלא גם בנוגע להאדם. והענין הוא<sup data-n=\"235\">124</sup>, דהנה ידוע שירידת הנשמה למטה היא ירידה צורך עלי', דע\"י ירידתה למטה היא מתעלית יותר גם מכפי שהיתה קודם הירידה. וענין העלי' הוא, שבאה לענין התשובה. שקודם ירידתה למטה היתה בבחי' צדיק (גמור), וע\"י עבודתה בירידתה למטה נעשית בבחי' בעל תשובה<sup data-n=\"236\">125</sup>. והגם שיש יתרון בעבודת הצדיקים על עבודת הבעלי תשובה [שלכן התמידים היו מכבשים ולא מעזים, אימרא יאי<sup data-n=\"237\">126</sup>], וכמרז\"ל<sup data-n=\"238\">127</sup> במי נמלך בנשמותיהן של צדיקים, הנה היתרון דעבודת הצדיקים הוא מצד הרצון שבו שייך ענין ההמלכה (במי נמלך), משא\"כ מצד עצמותו ית' (בחי' בעל הרצון), עיקר הכוונה הוא בענין התשובה דוקא. וזהו מה שארז\"ל<sup data-n=\"239\">128</sup> מקום שבעלי תשובה עומדין אין צדיקים גמורין <i>יכולין</i> לעמוד בו [לא רק שאינם עומדין שם<sup data-n=\"240\">129</sup>, אלא יתירה מזו שאין <i>יכולין</i> לעמוד שם, כהגירסא המובאת בהדרושים עה\"פ ושבתי בשלום<sup data-n=\"241\">130</sup>], והיינו שמעלת הבע\"ת היא למעלה גם מיכולת הצד\"ג, שענין היכולת הוא<sup data-n=\"242\">131</sup> למעלה מבחי' כח גם מכחותהמקיפים, לפי שענין התשובה מגיע בעצמותו ית', שכל הגילויים (שרש עבודת הצדיקים) הם באין ערוך אליו כלל.\nטו) <b>וע\"פ</b> הנ\"ל יובן מ\"ש ושבתי בשלום אל בית אבי, דצריך להבין, הרי ענין ושבתי הוא (לכאורה) שיחזור להמקום שהי' בתחילה, וא\"כ, מכיון שביציאת יעקב נאמר ויצא יעקב מבאר שבע, הול\"ל ושבתי בשלום אל באר שבע ולמה אומר אל בית אבי. וי\"ל הענין בזה, כי מכיון שע\"י עבודת התשובה מתעלית הנשמה לבחינה נעלית יותר מכמו שהיתה לפני ירידתה (כנ\"ל), לכן ענין ושבתי הוא (לא לבאר שבע, הדרגא של הנשמה כמו שהיתה קודם ירידתה<sup data-n=\"243\">132</sup>, כי אם) אל בית אבי, שלמעלה מבחי' באר שבע<sup data-n=\"244\">133</sup>. ויש להוסיף, דענין זה שייך גם לבית אבי כפשוטו שקאי על יצחק. דיצחק הוא מלשון שמחה ותענוג<sup data-n=\"245\">134</sup>, וידוע<sup data-n=\"246\">135</sup> שתענוג זה (התענוג שבצחוק) הוא מדבר חידוש<sup data-n=\"247\">136</sup> דוקא. ומכיון שענין התשובה הוא דבר חידוש<sup data-n=\"248\">137</sup> [וע\"ד מ\"ש הרמב\"ם<sup data-n=\"249\">138</sup> בענין התשובה כפשוטה (על עבירות), שמעלת התשובה היא מצד זה שאמש הי' זה מובדל כו' והיום הוא מודבק בשכינה], לכן, ע\"י עבודת התשובה נעשה תענוג וצחוק למעלה. שתענוג זה הוא נעלה יותר מהתענוג דעבודת הצדיקים, דזהו מה שבע\"ת הוא אהוב וחביב יותר מצדיק<sup data-n=\"250\">139</sup>, לפי שעיקר התענוג שלמעלה הוא בעבודת התשובה. וזהו ג\"כ מה שבע\"ת צועק ונענה מיד<sup data-n=\"251\">140</sup>, ועד<sup data-n=\"252\">141</sup> אשר והי'<sup data-n=\"253\">142</sup> טרם יקראו ואני אענה<sup data-n=\"251\">140</sup> (הגם שע\"פ סדר מענה בא לאחרי קריאה), כי התענוג שלמעלה הבא מהחידוש דעבודת התשובה פועל חידוש (היפך הסדר) גם למעלה – טרם יקראו ואני אענה<sup data-n=\"254\">143</sup>.טז) <b>והנה</b> עיקר החידוש הגורם התענוג והצחוק שלמעלה הוא החידוש שנעשה בגוף ונפש הבהמית<sup data-n=\"255\">144</sup> גופא. והיינו, שהתשובה דנפש האלקית [מה שגם בירידתה למטה (גם בזמן הגלות) היא עוסקת בתומ\"צ, ואפילו זה שגם עשייתה עניני הרשות היא לש\"ש ועד באופן דדעהו<sup data-n=\"256\">145</sup>] אינו חידוש כ\"כ<sup data-n=\"257\">146</sup>, מכיון שהיא אלקות בעצם מהותה. ובמילא אין בזה תענוג כ\"כ. ועיקר התענוג שלמעלה הוא בהחידוש שנעשה בהגוף ונפש הבהמית גופא<sup data-n=\"258\">147</sup>, הן באופן דאתהפכא (ע\"י עבודת הצדיקים) והן באופן דאתכפיא (ע\"י עבודת הבינונים), שהם שני מיני נחת רוח, מטעמים לשון רבים<sup data-n=\"259\">148</sup>. ותענוג זה הוא נעלה יותר מהתענוג שבעבודת הנשמה (גם מעבודת התשובה של הנשמה), וכמאמר הזהר<sup data-n=\"260\">149</sup> כד אתכפיא (ואתהפכא<sup data-n=\"261\">150</sup>) סט\"א אסתלק יקרא דקוב\"ה בכולהו עלמין, שהאור הנמשך ע\"י אתכפיא ואתהפכא הוא אור שלמעלה מכלים, שלכן נקרא בשם אסתלק<sup data-n=\"262\">151</sup>. וזהו מה שמבואר בתו\"א<sup data-n=\"263\">152</sup> ובתו\"ח<sup data-n=\"264\">153</sup> בפירוש ושבתי בשלום אל בית אבי שהוא (לא ענין התשובה דנה\"א, כ\"א) התשובה דאתכפיא ואתהפכא סט\"א מחשוכא לנהורא, כי הצחוק והתענוג שלמעלה (אל בית אבי יצחק מלשון צחוק ותענוג) נעשה בעיקר ע\"י אתכפיא ואתהפכא.\nיז) <b>ועפ\"ז</b> יובן היתרון שבהעבודה בכל מעשיך לשם שמים ובכל דרכיך דעהו (לא רק בנוגע להפעולה בעולם, אלא) גם בנוגע להאדם (הנשמה), כי זה שהנשמה ע\"י עבודתה בירידתה למטה נעשית בחי' בעל תשובה הוא בעיקר ע\"יהעבודה בעשיית דברי הרשות לשם שמים<sup data-n=\"265\">154</sup>. והענין הוא, הנה כתיב<sup data-n=\"266\">155</sup> ועמך כולם צדיקים, והטעם לזה הוא לפי שאמיתית מהותו של כ\"א מישראל הוא (כנ\"ל סעיף יב) נפשו האלקית. וכפס\"ד הרמב\"ם (הובא לעיל שם) שרצונו האמיתי של כאו\"א מישראל הוא לעשות כל מה שהוא רצון ה', וכאשר כופין אותו (ומכ\"ש כאשר הוא עצמו כופה את עצמו) לעשות איזו מצוה, תשש יצרו הרע ומתגלה בו רצונו האמיתי שלו. ומכיון שבשעה זו שהוא עוסק בתומ\"צ מתגלה בו רצונו האמיתי דנפשו האלקית, הרי בשעה זו הוא בבחי' צדיק. דהגם שגם בשעה זו גופא אפשר שיהי' בו ענינים דהיפך הקדושה, מ\"מ, מכיון שהטעם האמיתי לזה שמקיים המצוה הוא לפי שנתגלה בו רצונו הפנימי, הרי בנוגע להמצוה שעושה הוא בבחי' צדיק. [וזהו מה שבהבקשה דונתן לי לחם לאכול ובגד ללבוש לא נזכר שזה יהי' באופן של שלום, כי ענין השלום שייך כשיש מנגד [וכענין פדה בשלום נפשי<sup data-n=\"267\">156</sup> (השייך להגאולה דיו\"ד כסלו<sup data-n=\"268\">157</sup>) שזהו מצד (כמו שממשיך בכתוב<sup data-n=\"267\">156</sup>) מקרב לי], ולכן כמו שבצדיק אין שייך לומר שעבודתו היא בשלום, מכיון שאין<sup data-n=\"269\">158</sup> לו יצה\"ר כלל, עד\"ז הוא גם בהתומ\"צ (לחם ובגד) דכ\"א מישראל, מכיון שבשעה זו עומד בגילוי הרצון דנפה\"א, והתומ\"צ שעושה הוא מצד רצון הנשמה, בחי' צדיק שבו]. משא\"כ כשעוסק בעניני הרשות, מכיון שעשייתו ענינים אלו היא מצד שהם צורך הגוף וקיומו וחיותו<sup data-n=\"270\">159</sup> או גם מצד נפשו הבהמית (שמתאוה בטבעה לעניני עוה\"ז<sup data-n=\"271\">160</sup>) המעלמת ומסתרת על נפשו האלקית, לכן, זה שעסקו בעניני הרשות הוא לש\"ש ובאופן דדעהו, הוא דוגמת עבודת התשובה.\nחי) <b>והנה</b> בכללות יותר, גם העבודה דתומ\"צ כאשר היא באופן כזה שהאדם צריך לכבוש את יצרו, ובפרט בזמן הגלות שישנם כמה מניעות ועיכובים על עסק התומ\"צ וצריך להתגבר עליהם, הוא בכלל עבודת התשובה. ובזה יובן מ\"ש בזהר<sup data-n=\"272\">161</sup> שכשראה יעקב העניות והצער שיהי' בזמן גלות אדום, (ובפרט) בסוף זמן הגלות, אמר ושבתי בשלום אל בית אבי ואמר ונתן לי לחם לאכול ובגד ללבוש, ואינו מובן, הרי בפסוק נאמר ונתן לי לחם גו' ואח\"כ ושבתי בשלום גו' ומדוע מקדים בזהר ושבתי בשלום לפני ונתן לי לחם גו'<sup data-n=\"273\">162</sup>. וי\"ל הביאור בזה, דמכיון שבזהר שםמדבר בענין העניות והצער דזמן הגלות [שהוא פירוש שלישי בענין ויצא גו' וילך חרנה, שיציאה והליכה זו היא [לא מבחי' בינה למלכות וגם לא מבחי' מלכות לבי\"ע (כב' הפירושים שהובאו לעיל סעיף ג), כי אם] לזמן הגלות<sup data-n=\"274\">163</sup>. דזהו ג\"כ משארז\"ל&lt;39&gt; שחרן הו\"ע חרון אף של מקום בעולם, דענין זה הוא (בעיקר) בזמן הגלות], לכן מקדים ושבתי בשלום גו' לפני ונתן לי לחם גו' ובגד גו', כי מצד ההעלמות וההסתרים דזמן הגלות, גם העבודה דתומ\"צ (לחם ובגד) היא ע\"י הקדמת ענין התשובה (ושבתי בשלום) שכולל (כנ\"ל) ההתגברות על המניעות ועיכובים. ובכתוב נאמר ונתן לי לחם גו' ובגד גו' לפני ושבתי בשלום גו', כי הענין דויצא יעקב מבאר שבע וילך חרנה כמו שהוא בכל דור ודור (גם לפני הגלות) הוא ירידת הנשמה למטה (בכלל, ולא הירידה דגלות), ומכיון שבזמן הבית העבודה דתשובה היא הבירור דעניני הרשות משא\"כ העבודה דתומ\"צ היא (בכללות) עבודת הצדיקים, לכן אומר מיד \"ונתן לי לחם לאכול ובגד ללבוש\", ואינו מקדים תחילה \"ושבתי בשלום\". ואדרבה, ונתן לי לחם גו' הוא לפני ושבתי בשלום, שלאחרי העבודה דתומ\"צ השייכת לנפש האלקית, אז דוקא אפשר להיות הבירור דעניני הרשות (\"ושבתי בשלום\"). וע\"ד מארז\"ל<sup data-n=\"275\">164</sup> קשוט עצמך ואח\"כ קשוט אחרים.\nיט) <b>ויש</b> לומר, דהתשובה דהעבודה דכל מעשיך לשם שמים היא נעלית יותר מהתשובה דקיום התומ\"צ בזמן הגלות, וגם מתשובה כפשוטה על עבירות. כי ענין התשובה דקיום התומ\"צ שבזמן הגלות הוא (כנ\"ל סעיף חי) מה <i>שמתגבר</i> על המניעות והעיכובים דהגלות <i>ואינו</i> מתחשב עמהם. ועד\"ז הוא בתשובה כפשוטה, דענין התשובה הוא שהוא <i>יוצא</i> ממצבו הקודם. ובלשון הרמב\"ם (שהובא לעיל סעיף טו) אמש הי' זה מובדל מה' אלקי ישראל כו' והיום הוא מודבק בשכינה. משא\"כ התשובה דכל מעשיך לשם שמים, מכיון דזה שהוא עוסק בדברי הרשות (מעשי<i>ך</i>) הוא מצד גופו ונפשו הבהמית (כנ\"ל), וזה שהוא עושה אותם לשם שמים, עם היות שזהו מצד הנשמה, הרי אין זה שהנשמה מתגברת על הגוף ונה\"ב (ויוצאת מהם), כי אם, שבעשי' זו גופא שמצד הגוף ונפש הבהמית ישנה הכוונה דלשם שמים שמצד הנשמה. וענין זה (הגילוי דנפש האלקית בעניני הגוף ונה\"ב גופא) הוא חידוש גדול יותר מזה שהנשמה <i>מתגברת</i> על ההעלמות וההסתרים ויוצאת מהם. ומכיון שהעילוי שבתשובה על עבודת הצדיקים הוא מצד החידוש שבה (כנ\"ל סעיף טו), נמצא שעיקר העילוי דתשובה הוא בהתשובה דכל מעשיך לשם שמים.\nכ) <b>אלא</b> שאעפ\"כ, הכוונה בירידת הנשמה למטה היא לא בשביל העלי' דהנשמה, שע\"י ירידתה למטה נעשית בחי' בעל תשובה, כי אם, בשביל הבירור והזיכוך דהגוף ודנה\"ב וחלקו בעולם. ויש לבאר זה, דהחידוש שבהתשובה דהנשמה,מכיון שהנשמה היא חלק אלוקה ממעל ממש<sup data-n=\"276\">165</sup>, הרי זה שהנשמה מתגברת על הדברים המעלימים, וגם זה שהיא מתגלית ופועלת בעניני הגוף ונה\"ב גופא, אין זה חידוש אמיתי. משא\"כ הבירור והזיכוך דהגוף ונה\"ב וחלקו בעולם, הרי זה שנעשים כלים לאלקות הוא חידוש אמיתי. ולכן התענוג שלמעלה (שהוא מדבר חידוש, כנ\"ל) מבירור הגוף וכו' הוא תענוג גדול יותר מהתענוג הבא בתשובה דהנשמה. [ויתירה מזו, שגם כשהפעולה דנה\"ב היא באופן של דחי', אתכפיא סט\"א, יש בזה נח\"ר גדול למעלה, כמבואר בתניא&lt;148&gt;]. ובזה גופא, עיקר החידוש (והנח\"ר דלמעלה) הוא בהבירור דחלקו בעולם, שהבירור דגוף ונה\"ב, מכיון שזה נפש וגוף של ישראל [שגם נפש הבהמית והגוף דישראל הוא לא כבאוה\"ע], אין זה חידוש כ\"כ, ועיקר העילוי הוא בהבירור דחלקו בעולם ובפרט בבירור הניצוצות שבגקה\"ט (ע\"י תשובה כפשוטה שזדונות נעשים כזכיות<sup data-n=\"277\">166</sup>, וכן ע\"י נסיונות<sup data-n=\"278\">167</sup> וכיו\"ב). [ועפ\"ז יובן גם מה שמבואר בכ\"מ<sup data-n=\"279\">168</sup> שבכדי לבוא לבחי' בכל מאדך הוא ע\"י אתהפכא חשוכא לנהורא [החושך של הענינים הגשמיים שעוסק בהם במשך היום], הגם שגם בהעבודה דבכל לבבך בשני יצריך מהפך היצה\"ר לקדושה, כי עיקר העילוי הוא בהבירור דחלקו בעולם (שמחוצה לו)]. וזהו גם ושבתי בשלום אל <i>בית</i> אבי, שהעבודה דאתכפיא ואתהפכא חשוכא לנהורא העושה את הצחוק והתענוג שלמעלה (ענין \"אבי\" – יצחק) היא באופן דבית, היינו שעבודתו זו היא בקביעות<sup data-n=\"280\">169</sup> בכל עניניו, לא רק בגופו ובנפשו הבהמית כ\"א גם בחלקו בעולם.\nכא) <b>וע\"פ</b> כל הנ\"ל יובן בעומק יותר זה שעיקר העבודה שבשביל זה ירדה הנשמה למטה (ויצא יעקב גו' חרנה) הוא ויקח מאבני המקום גו', שקאי (כנ\"ל סעיף ט) על הבירור דעניני העולם, דנוסף על היתרון שבהעבודה דכל מעשיך לשם שמים על העבודה דתומ\"צ (כנ\"ל שם), הנה גם בהעבודה דכל מעשיך לשם שמים גופא שני ענינים, עליית האדם שנעשית עי\"ז (תשובה דהנשמה), וההעלאה של הדברים הגשמיים. ובשני ענינים אלו, עיקר העבודה היא ויקח מאבני המקום, הבירור דדברים הגשמיים, אבני המקום. וזהו ג\"כ מ\"ש והי' הוי' לי לאלקים והאבן הזאת אשר שמתי מצבה יהי' בית אלקים, והי' הוי' <i>לי</i> לאלקים הוא העילוי שנעשה בהאדם ע\"י עבודת הבירורים, ולאח\"ז מוסיף והאבן הזאת אשר שמתי מצבה יהי' בית אלקים, שגם האבן הזאת, הדברים הגשמיים עצמם שהיו בתחילה אבני המקום לשון רבים וע\"י עבודת האדם נעשו אבן אחת [ובאופן דשמתי מצבה מלשון נצב<sup data-n=\"281\">170</sup> מלך, שנעשה בעה\"ב (מלך) על כל עניניו דחלקו בעולם. וגם פירוש מצבה מלשון נצב מלך, שממשיך בהם גילוי מלכותו ית', בחינת מלכותו ברצון קבלו עליהם(שלמעלה מבחי' ממשלה שבהכרח)<sup data-n=\"282\">171</sup>], יהיו בית אלקים, שיהיו בית ודירה לאלקים שלמעלה מהוי' (גם מוהי' הוי' לי לאלקים<sup data-n=\"283\">172</sup> שמצד התשובה דנה\"א<sup data-n=\"284\">173</sup>), להעלם העצמי דעצמותו ית'.\nכב) <b>ובכדי</b> שהאבן הזאת יהי' בית אלקים הוא ע\"י העבודה דויקח את האבן גו' וישם אותה מצבה ויצוק שמן על ראשה<sup data-n=\"285\">174</sup>. ויקח את האבן לשון יחיד, היינו, דגם לאחרי שעשה מאבני המקום (לשון רבים) אבן אחת, בדוגמת יו\"ד דשם הוי' בחי' חכמה, הגבי' אותה למעלה יותר (וישם אותה מצבה, כענין קמה<sup data-n=\"286\">175</sup> אלומתי וגם נצבה<sup data-n=\"287\">176</sup>) לבחי' י\"ג מדות רחמים העליונים שהן בחי' יודי\"ן ווי\"ן<sup data-n=\"288\">177</sup>. דיש וא\"ו שלמטה מהיו\"ד ויש וא\"ו שלמעלה מהיו\"ד [שלכן מובא בתו\"א (בתחילת הענין<sup data-n=\"288\">177</sup>) שהשערה עצמה הוא בחי' ו' ומקום יניקתה הוא בחי' יו\"ד – הגם שבסיום הענין<sup data-n=\"289\">178</sup> מסיק שם שהו' הוא למעלה מיו\"ד – כי יש ב' ענינים בזה<sup data-n=\"290\">179</sup>]. ואח\"כ ויצוק שמן על ראשה, שהמשיך בה מבחינה שלמעלה מי\"ג ת\"ד<sup data-n=\"289\">178</sup>. ועי\"ז והאבן הזאת גו' יהי' בית אלקים, יהי' לשון זכר (הגם שאמר והאבן הזאת לשון נקבה<sup data-n=\"291\">180</sup>), כי קאי על הגילוי דגאולה העתידה שאז יהי' שיר חדש לשון זכר (גאולה שאין אחרי' גלות)<sup data-n=\"292\">181</sup>.\nכג) <b>וזוהי</b> ג\"כ השייכות דענין ושבתי בשלום אל בית אבי כמו שהוא בעבודת האדם בהיותו בחרן (בזמן הגלות) לענין ושבתי בשלום אל בית אבי (כמו שהוא בפשטות) שקאי על ההשבה והחזרה מחרן לבית אביו שתהי' בהגאולה לע\"ל [וכמובן גם מזה שיצחק (אבי) הוא לשון עתיד, כי ענין הצחוק והתענוג יהי' לע\"ל, כמ\"ש<sup data-n=\"293\">182</sup> אז (דוקא) ימלא שחוק פינו. דזהו ג\"כ מה שלעתיד דוקא יאמרו<sup data-n=\"294\">183</sup>ליצחק כי אתה אבינו<sup data-n=\"295\">184</sup>], כי ע\"י העבודה דושבתי בשלום, אתכפיא ואתהפכא חשוכא לנהורא [ענין השלום, שגם המנגד נהפך לקדושה], ולא רק בגופו ונפשו הבהמית אלא גם בחלקו בעולם, עי\"ז יהי' הגילוי דלעתיד, שאז יהי' אמיתית ענין השלום, לא ירעו ולא ישחיתו גו' כי מלאה הארץ דעה את הוי' כמים לים מכסים<sup data-n=\"296\">185</sup>.\nכד) <b>והנה</b> הגם שיצחק הוא לשון עתיד לפי שהצחוק והתענוג שלמעלה יהי' לע\"ל (כנ\"ל), מ\"מ, מזה שנקרא עכשיו בשם יצחק, מובן, שגם עכשיו יש תענוג וצחוק זה [וכמ\"ש<sup data-n=\"297\">186</sup> צחוק עשה לי אלקים, עשה כבר], שהרי הצחוק והתענוג נעשה מהעבודה דאתכפיא ואתהפכא עכשיו, ורק <i>שגילוי</i> התענוג יהי' לע\"ל (כשיושלמו כל הבירורים). [וכ\"ה גם בנוגע לזה שלע\"ל יאמרו ליצחק כי אתה אבינו מצד זה שיציל את ישראל מהגלות&lt;183&gt;, שמעין ענין זה יש גם עכשיו. שגם בזמן הגלות הוא מגין על ישראל, שהגנה זו תהי' אח\"כ באופן דהצלה מהגלות<sup data-n=\"298\">187</sup>].\n<b>ועד\"ז</b> הוא גם בענין השלום, דהגם שאמיתית ענין השלום (באופן דלא ירעו ולא ישחיתו גו') יהי' לע\"ל (כנ\"ל סו\"ס כג), הנה מעין זה אפשר להיות גם עכשיו בזמן הגלות, שהדברים המונעים ומעכבים וכו' לא רק שלא ינגדו, אלא אדרבה יסייעו לעבודת ה'. ועפ\"ז מובן (נוסף להביאור דלעיל שם) השייכות דענין ושבתי בשלום אל בית אבי כמו שהוא בזמן הגלות לענין ושבתי בשלום אל בית אבי שיהי' בגאולה העתידה, כי גם בזמן הגלות כשישנם מונעים ומעכבים [ועד שצריך לבקשה שיהי' ושבתי בשלום גו' שלום ושלילת שפיכות דמים<sup data-n=\"299\">188</sup>], הנה גם אז, ע\"י התוקף דמס\"נ שמצד בחי' יחידה, מתבטלים כל המונעים ומעכבים, ולא עוד אלא שהם גופא מסייעים בעבודת ה', בדוגמת ומעין השלום שיהי' לע\"ל.\nכה) <b>ועפ\"ז</b> יובן גם התיווך דב' הפירושים בפדה בשלום נפשי מקרב לי גו'&lt;156&gt;. פירוש הפשוט הוא שפדה והוציא אותו מקרב (מלחמה). היינו שיש מציאות דלעו\"ז שצריך ללחום כנגדו. דזוהי השייכות דענין פדה בשלום נפשי לדוד (שבפשטות קאי זה על פדיית דוד<sup data-n=\"300\">189</sup>) שהי' לו מנגדים, אלא שנצח אותם. וכמו שידוע<sup data-n=\"301\">190</sup> החילוק בין הבירורים דדוד להבירורים דשלמה, שהבירורים דדוד היו בדרך מלחמה והבירורים דשלמה היו בדרך מנוחה וכמ\"ש<sup data-n=\"302\">191</sup> דם לרוב שפכת ומלחמות גדולות עשית לא תבנה בית לשמי גו' הנה בן נולד לך הוא יהי' איש מנוחה גו' הוא יבנה בית לשמי גו'. והיינו דהגם שגם הנצחון דדוד (מה שנצח אתכל המנגדים) הי' נצחון בתכלית [שלכן הי' קס\"ד שיבנה את ביהמ\"ק], מ\"מ, מכיון שהבירורים שלו היו בדרך מלחמה, הי' בנין ביהמ\"ק ע\"י שלמה דוקא. שמזה מובן, שענין פדה בשלום שנאמר גבי דוד הוא שיש מציאות דלעו\"ז המנגד ורק שמנצחים אותם. וכ\"ה גם בענין פדה בשלום נפשי שהי' בהגאולה די\"ט כסלו<sup data-n=\"303\">192</sup> והגאולה דיו\"ד כסלו<sup data-n=\"304\">193</sup>, שהי' מציאות דלעו\"ז המנגד, אלא שנצחו אותם. ועד שגם לאחרי הגאולה הוצרכו לרשיון מהמלכות דמדינה ההיא [אבל כל המלכיות נקראו על שם מצרים על שם שהם מצירות לישראל<sup data-n=\"305\">194</sup>] על הפצת תורת החסידות. ופירוש הב' הוא כמבואר בד\"ה פדה בשלום נפשי דבעל הגאולה<sup data-n=\"306\">195</sup> וכמה דרושים ד\"ה זה (די\"ט כסלו)<sup data-n=\"307\">196</sup>, שהפדי' היא בדרך שלום, ועד שאין צריך למלחמה כלל, כמו שהי' בימי שלמה שכל הגוים נתבטלו לפניו שלא ע\"י מלחמה כלל. והתיווך דב' פירושים אלו שהם לכאורה מן הקצה אל הקצה, וביותר ע\"פ המבואר בכ\"מ<sup data-n=\"308\">197</sup> שענין פדה בשלום נפשי הוא הפדי' בתכלית השלום כמו שיהי' לע\"ל דאז אהפוך אל עמים שפה ברורה גו' לעבדו שכם אחד<sup data-n=\"309\">198</sup>, שלמעלה גם מענין השלום שהי' בימי שלמה [אלא שהשלום שבימי שלמה הי' הכנה להשלום דלעתיד, שלכן משיח יהי' (מבית דוד ו)מזרע שלמה בלבד<sup data-n=\"310\">199</sup>], שפירוש זה, העילוי [והשלימות] דלעתיד, הוא למעלה מענין הקצוות. אך הענין הוא, דלהיות דכל הגילויים דלעתיד תלויים במעשינו ועבודתינו במשך זמן הגלות<sup data-n=\"311\">200</sup>, לכן, גם בהענין דפדה בשלום נפשי בזמן הגלות יש מעין ענין הפדי' בשלום שיהי' לע\"ל.\nכו) <b>וביאור</b> שייכות ענין זה (שגם עכשיו יש מעין הפדי' בשלום דלע\"ל) להגאולה די\"ט כסלו ודיו\"ד כסלו [שלכן בהדרושים שנאמרו בזמנים אלו מבואר הפירוש (הב' דלעיל) שפדה בשלום נפשי הו\"ע הפדי' בדרך שלום, ועד כמו שיהי' לע\"ל], הנה נת\"ל (סעיף חי) שהטעם לזה שמקדים בזהר ושבתי בשלום (ענין התשובה) לונתן לי לחם גו' הוא, לפי שבזהר שם מדבר בענין סוף זמן הגלות, שאז עיקר העבודה (גם העבודה דתומ\"צ) היא עבודת התשובה. שעי\"ז נעשה הפדי' בדרך שלום (מעין השלום דלע\"ל), מכיון שענין התשובה היא הפיכת הלעו\"ז לקדושה. וזוהי גם השייכות דפדה בשלום נפשי לגאולת אדמו\"ר הזקן(י\"ט כסלו) ואדמו\"ר האמצעי (יו\"ד כסלו), כי מהענינים שנתחדשו ע\"י אדמו\"ר הזקן (גם לגבי הרב המגיד) הוא שעשה [הרבה] בעלי תשובה<sup data-n=\"312\">201</sup>. וענין זה הי' גם עבודתם של רבותינו נשיאינו ממלאי מקומו, ובפרט של בנו אדמו\"ר האמצעי, שעל ידו נתגלה<sup data-n=\"312\">201</sup> ענין זה.\nזך) <b>והי'</b> הוי' לי לאלקים, שע\"י העבודה דושבתי בשלום, שהו\"ע בירור חלקו בעולם (כנ\"ל סעיף ח), יהי' הגילוי דלע\"ל, שאז יוציא הקב\"ה חמה מנרתיקה<sup data-n=\"313\">202</sup>, ויהי' מלאה הארץ דעה את הוי' כמים לים מכסים&lt;185&gt;, ועד שיהי' גילוי העצמות, ולא יכנף עוד מוריך והיו עיניך רואות את מוריך<sup data-n=\"314\">203</sup>. וזהו והי' הוי' לי לאלקים, שלגבי גילוי זה הוי' דעכשיו כאלקים יחשב<sup data-n=\"315\">204</sup>.\nכח) <b>וזהו</b> ושבתי בשלום אל בית אבי, שקאי (כנ\"ל) על עבודת הבירורים, שעי\"ז נעשה (טוט זיך אויף) ענין ושבתי בשלום גו' שיהי' לעתיד עד והאבן הזאת גו' יהי' בית אלקים. וזה גופא מורה על גודל העילוי שבהעבודה דסוף זמן הגלות, שעיקר העבודה אז היא עבודת התשובה (ועד שגם העבודה דתורה ומצוות (לחם ובגד) שבסוף זמן הגלות היא לאחרי קדימת עבודת התשובה (ושבתי בשלום)<sup data-n=\"316\">205</sup>), שהרי ע\"י העבודה דתשובה ומעשים טובים (היינו שגם המעשים טובים הם לאחרי קדימת התשובה<sup data-n=\"317\">206</sup>) נעשה (טוט זיך אויף) ענין ושבתי בשלום גו' שיהי' לע\"ל. [ועד שיפה שעה אחת בתשובה ומעשים טובים בעוה\"ז מכל חיי העוה\"ב<sup data-n=\"318\">207</sup>, לפי שגורם הדבר חזק יותר מהנעשה על ידו. וגם לפי שהתענוג דעוה\"ב הוא תענוג האדם שהוא נברא, והתענוג דתשובה ומע\"ט (בעוה\"ז) הוא תענוג <i>הבורא</i><sup data-n=\"319\">208</sup>]. ובפרט, שזה שע\"י העבודה דעכשיו טוט זיך אויף הגילוי דלעתיד הוא באופן שמעין הגילוי דלעתיד יש גם עכשיו (כנ\"ל סעיף כד-כה). דמכיון שהעבודה שבסוף זמן הגלות היא עבודת התשובה, ובבע\"ת נאמר&lt;142&gt; והי' טרם יקראו ואני אענה&lt;140&gt;, לכן, גם בסוף זמן הגלות [ובפרט כשיש גם התפלה (\"יקראו\") ושבתי בשלום] נעשה כבר ואני אענה, המשכת וגילוי מעין הענינים דלעתיד. ובדוגמת יעקב, שבהיותו עדיין בחרן הי' ויפרוץ האיש מאד מאד ויהי לו צאן רבות (שזהו העיקר&lt;110&gt;) ושפחות ועבדים וגמלים וחמורים&lt;111&gt;, עד\"ז הוא בכאו\"א מישראל, שבסוף זמן הגלות (כשנמצאים בחרן) יהי' ויפרוץ מאד מאד, ובאופן דפדה בשלום, בכל הפירושים ובכל הפרטים, הן בעבודה הרוחנית [ובפרט בלימוד והפצת תורת החסידות, שיהי' בלי שום בלבולים ובתכליתההרחבה] והן בענינים הגשמיים, ובאופן דופרצת<sup data-n=\"320\">209</sup> (ויפרוץ), שזה ימהר ויזרז הגאולה העתידה – אחישנה (באחישנה גופא<sup data-n=\"321\">210</sup>), שבקרוב ממש יהי' קץ שם לחושך<sup data-n=\"322\">211</sup>, ויקבלו פני משיח צדקנו, שיוליכנו לארצנו הקדושה, ארץ אשר גו' תמיד עיני ה' אלקיך בה מרשית השנה ועד אחרית שנה<sup data-n=\"323\">212</sup>, ארץ ישראל לגבולותי', ואח\"כ – וגם זה באופן דאחישנה – ירחיב ה' אלקיך את גבולך<sup data-n=\"324\">213</sup>, ובקרוב ממש ובעגלא דידן<sup data-n=\"325\">214</sup>.\n**********",[["111","*","יצא לאור ב<b>קונטרס</b>*<b> ראש חודש כסלו – תשמ\"ח</b>, \"לקראת מלאות עשר שנה ליום הבהיר ראש חודש כסלו (תשל\"ח – תשמ\"ח) . . <i>עש\"ק מברכים כסלו</i>,<i> שנת הקהל</i>,<i> שנת תשמ\"ח</i>\"."],["112","1","פרשתנו כח, כא."],["113","2","וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300251159\" data-slug=\"likkutei-sichot\" data-id=\"1300251159\">לקו\"ש חכ\"ה</a> שיחה ליו\"ד כסלו (ע' 159 ואילך), שי\"ל שגאולתו מרומזת בפסוק \"ושבתי בשלום\", שי\"ל שרומז על ענין \"פדה בשלום נפשי\" (וראה להלן הערה 157)."],["114","3","שם, כ."],["115","4","ראה תו\"ח ריש פרשתנו (דקדוק הג' – כב, א-ב)."],["116","5","ראה לקמן סעיף ח. וש\"נ."],["117","6","ראה זהר ח\"ב כה, א. שם קסא, א. ח\"ג רסד, א. סהמ\"צ להצ\"צ מצות אחדות ה' (דרמ\"צ נט, ב ואילך). ד\"ה וידעת תרנ\"ז (סה\"מ תרנ\"ז ס\"ע מה ואילך). ועוד."],["118","7","תו\"ח שם (דקדוק הב')."],["119","8","פרשתנו שם, כב."],["120","9","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370102\" data-slug=\"torah-or\" data-id=\"3901370102\">תו\"א</a> פרשתנו (בהביאור על ד\"ה ושבתי בשלום – כא, סע\"ד). תו\"ח שם (כב, סע\"ב)."],["121","10","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370102\" data-slug=\"torah-or\" data-id=\"3901370102\">תו\"א שם</a> סד\"ה ושבתי בשלום (כא, ד). תו\"ח שם סי\"א (כז, א).\n*) <i>קונטרס זה חילק כ\"ק אדמו\"ר שליט\"א בידו הק' לכאו\"א מהשלוחים שיחיו</i>."],["122","11","<a class=\"ft-cite\" href=\"#/read/tanya/3401310022\" data-slug=\"tanya\" data-id=\"3401310022\">תניא רפי\"ז</a>. וראה בארוכה לקו\"ש ח\"ה ע' 240 ואילך."],["123","12","ראה רמב\"ן עה\"פ לך לך יב, ו: כל מה שאירע לאבות סימן לבנים. וראה תנחומא לך לך ט. ב\"ר פ\"מ, ו. אוה\"ת ר\"פ לך לך (עב, סע\"ב)."],["124","13","מכיון ש\"איני מבקש לפי כחי אלא לפי כחן\" (במדב\"ר פי\"ב, ג)."],["125","14","כמובן מהדוגמא דנביאים שברמב\"ן שם. וראה אוה\"ת שם (עג, א): מעשה כו' סימן לבנים <i>שיוכלו</i> אח\"כ כו'. וראה גם ב\"ר שם (הובא ברמב\"ן עה\"פ שם, י): צא <i>וכבוש את הדרך</i> לפני בניך. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201110\" data-slug=\"likkutei-sichot\" data-id=\"1300201110\">לקו\"ש ח\"כ ע' 110</a> ובהנסמן שם בהערה 21."],["126","15","ריש פרשתנו (כח, י)."],["127","16","ביאוה\"ז לאדהאמ\"צ פרשתנו יז, ד (וראה גם ביאוה\"ז להצ\"צ ריש פרשתנו – ע' צז). אוה\"ת ריש פרשתנו (קעב, א-ב). שם (כרך ה) תתלה, א-ב."],["128","17","ח\"א ריש פרשתנו (קמז, א)."],["129","18","וירא כא, לא."],["130","19","תולדות כו, לג. ספורנו שם (הובא באוה\"ת שם קעב, א)."],["131","20","תו\"א ותו\"ח ר\"פ לך לך. ועוד. וראה מאמרי אדהאמ\"צ ויקרא ח\"ב ע' תרכב. וש\"נ."],["132","21","לך לך יז, ה."],["133","22","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370053\" data-slug=\"torah-or\" data-id=\"3901370053\">תו\"א שם (יב, ב</a>). <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670079\" data-slug=\"torat-chaim\" data-id=\"2300670079\">תו\"ח שם (פ, ד</a>)."],["134","23","ראה ס' הליקוטים להאריז\"ל פ' חיי שרה."],["135","24","ראה לקו\"ת לג\"פ לך לך פ, סע\"ב ואילך (וראה גם סידור עם דא\"ח יב, א. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316490045\" data-slug=\"or-hatorah-hb\" data-id=\"8316490045\">אוה\"ת לך לך (כרך ד) תרצב, א</a>), שהאבות הם (לא רק בחג\"ת אלא גם) בחב\"ד: אברהם חכמה (וכנ\"ל בפנים), יצחק בינה וכו'."],["136","25","ראה לקו\"ת פינחס עט, ריש ע\"ב (מפרדס שער כג (שער ערכי הכינויים) ערך גד) \"גימל הוא בינה משקה לדלת שהיא מלכות\"."],["137","26","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370375\" data-slug=\"torah-or\" data-id=\"3901370375\">תו\"א תצוה פד, ב</a>. אוה\"ת דברים (כרך ה) ע' א'תתקצג. ועוד. וראה זח\"ג קצז, א."],["138","27","בראשית ב, יו\"ד. ובתו\"א ריש פרשתנו (כא, א), ש\"נעשים בחי' נפרדים בתכלית\"."],["139","28","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051057\" data-slug=\"likkutei-sichot\" data-id=\"1300051057\">לקו\"ש ח\"ה ע' 57</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201367\" data-slug=\"likkutei-sichot\" data-id=\"1300201367\">שם ע' 354</a> ואילך. ח\"כ ע' 285. ועוד."],["140","29","שלכן צוה יעקב לומר לעשו \"עם לבן גרתי גו'\" (ר\"פ וישלח – לב, ה) – ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370115\" data-slug=\"torah-or\" data-id=\"3901370115\">תו\"א וישלח כד, ג</a>. תו\"ח וישלח מא, ג."],["141","30","ויק\"ר פל\"ו, ה. וראה פסחים נו, א."],["142","31","תולדות כה, כו."],["143","32","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370135\" data-slug=\"torah-or\" data-id=\"3901370135\">תו\"א וישב כט, א</a>."],["144","33","ע\"ח שער ג (שער סדר אצי' למהרח\"ו) פ\"ב. פרדס שער כג (שער ערכי הכינויים) בערכו."],["145","34","הגהות הצ\"צ לתו\"א ריש פרשתנו – אוה\"ת פרשתנו קצב, א (בשוה\"ג (ב))."],["146","35","בדוגמת הראש המנהיג את אברי הגוף. וראה בארוכה שיחת מוצאי ש\"פ בראשית שנה זו (ה'תשל\"ח) סעיף ה, ובהערות שם (<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201283\" data-slug=\"likkutei-sichot\" data-id=\"1300201283\">לקו\"ש ח\"כ ע' 270</a>). וש\"נ."],["147","36","שעהיוה\"א פ\"ז (פב, א), מזח\"ג רנז, סע\"ב (ברע\"מ). פרדס שער א (שער עשר ולא תשע) פ\"ט. וראה גינת אגוז (הובא בהקדמת השל\"ה ה, א)."],["148","37","שעהיוה\"א רפ\"ד. וראה גם זהר ופרדס שם."],["149","38","שעהיוה\"א שם. וראה לקו\"ש שם הערה 45."],["150","39","פרש\"י ס\"פ נח. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151063\" data-slug=\"likkutei-sichot\" data-id=\"1300151063\">לקו\"ש חט\"ו</a> שיחה ה' לפ' נח (ע' 63 ואילך)."],["151","40","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370049\" data-slug=\"torah-or\" data-id=\"3901370049\">תו\"א לך לך (יא, סע\"ב</a> ואילך. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370057\" data-slug=\"torah-or\" data-id=\"3901370057\">שם יג, ב</a>). <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670095\" data-slug=\"torat-chaim\" data-id=\"2300670095\">תו\"ח שם (פא, סע\"א</a> ואילך). <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670270\" data-slug=\"torat-chaim\" data-id=\"2300670270\">תו\"ח חיי שרה קכד, ד</a>."],["152","41","יהושע יד, טו. ובב\"ר פי\"ד, ו (ובפרש\"י עה\"פ מ\"מדרש אגדה\"): זה אברהם."],["153","42","ב\"ר פנ\"ט, ו."],["154","43","תהלים מד, ה."],["155","44","כ\"ה בתו\"ח שם (והוא הנק' שע\"ה נהורין כמ\"ש בזוהר). ובתו\"א שם: ישועות הם <i>ש\"ע</i> נהורין עילאין (וראה בארוכה בהגהות לתו\"א שם – באוה\"ת פרשתנו קצב, סע\"א ואילך). ובאגה\"ק ס\"ג (קד, סע\"ב): ישועה הוא מלשון וישע . . דש\"ע נהורין שבזוה\"ק (ראה זהר ח\"א ד, ב. ח\"ג קלג, סע\"ב. ע\"ח שער טו (שער הזווגים) פ\"ב ואילך. ועוד)."],["156","45","ראה פע\"ח שער כט (שער הלולב וד' מיניו) פ\"ג: יצוה, כמשאמרז\"ל (ברכות ו, סע\"ב) כל העולם כולו לא נברא אלא לצוות לזה שהוא לשון חיבור."],["157","46","ראה פירש\"י עה\"פ פרשתנו כט, א (מב\"ר פ\"ע, ח)."],["158","47","וראה הביאור בזה באוה\"ת פרשתנו ד\"ה וידר יעקב נדר וד\"ה טוב אשר לא תדור (כרך ה תתנא, סע\"ב ואילך. שם תתנב, ב ואילך)."],["159","48","פרשתנו כח, יא."],["160","49","שעהיוה\"א פ\"ז (פב, רע\"א)."],["161","50","ב\"ר פרשתנו פס\"ח, ט. תקו\"ז תכ\"ו (עא, ב)."],["162","51","פרדס שער כג (שער ערכי הכינויים) ע' מקום (מהתקו\"ז שם) – הובא בספר החקירה להצ\"צ עה, ב. ובכ\"מ. ובפרדס שם: והכוונה כי הוא מקומו של עולם. ועד\"ז בתקו\"ז שם."],["163","52","שעהיוה\"א שם (פד, ב)."],["164","53","בפרש\"י עה\"פ: עשאן <i>הקב\"ה</i> אבן אחת [ובתנחומא ריש פרשתנו (וכ\"ה בפרש\"י חולין צא, ב ד\"ה נבלעו): ונעשו]. אבל בתו\"א ובתו\"ח פרשתנו (דלהלן הערה 56) <i>שיעקב</i> עשה מהן אבן אחת (ובתו\"ח שם: <i>ואמרז\"ל</i>)."],["165","54","בחולין שם ובתנחומא מדייק כן (שנעשו אבן אחת) מהא דכתיב לאח\"ז (כח, יח) ויקח את האבן (בלשון יחיד). אבל מזה שרש\"י מפרש \"עשאן . . אבן אחת\" עה\"פ וישם מראשותיו, מוכח, שההכרח לזה הוא גם מפסוק זה גופא [ומה שמסיים \"וזהו שנאמר ויקח את האבן אשר שם מראשותיו\" הוא לתוספת ראי']. וראה גם משכיל לדוד עה\"פ: \"דק\"ל (לרש\"י) דהול\"ל וישימם כיון דרבים היו\"."],["166","55","ראה גו\"א עה\"פ: \"לשון מראשותיו משמע . . <i>למעלה</i> מראשו\". ושם, שמזה מוכיח רש\"י \"עשאן כמין מרזב סביב לראשו\"."],["167","56","תו\"ח פרשתנו (ס\"ג – כג, ג-ד). וראה גם תו\"א ריש פרשתנו."],["168","57","ב\"מ פד, א."],["169","58","שער הגלגולים להאריז\"ל הקדמה וא\"ו ואילך. ובכ\"מ. וראה שמו\"ר פ\"מ, ג."],["170","59","אגה\"ק ס\"ז (קיא, ב)."],["171","60","אור החיים פרשתנו כח, יד. הובא ונתבאר בקיצורים והערות לתניא ע' נז. ד\"ה ויצא תר\"ל (סה\"מ תר\"ל ע' כט ואילך)."],["172","61","ע\"פ לשון חז\"ל – חגיגה ה, ב."],["173","62","קיצורים והערות לתניא ע' מח ואילך. ד\"ה ויצא תר\"ל (סה\"מ תר\"ל ס\"ע לא ואילך)."],["174","63","נדה ל, ב."],["175","64","אור החיים דלעיל הערה 60 – הובא בקיצורים והערות לתניא ובד\"ה ויצא תר\"ל שבהערה הנ\"ל. ובאוה\"ת פרשתנו קעב, ב."],["176","65","קיצורים והערות לתניא ע' נח. ד\"ה ועשית חג שבועות חצר\"ת. ובכ\"מ."],["177","66","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370152\" data-slug=\"torah-or\" data-id=\"3901370152\">תו\"א מג\"א צח, ב</a> (בנוגע לתורה). מקץ לב, ד ואילך (בנוגע למצוות). ולהעיר, דמהמבואר ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370154\" data-slug=\"torah-or\" data-id=\"3901370154\">תו\"א מקץ שם (לג, סע\"ב</a> ואילך) החילוק בין לבושי המצוות לבירור נה\"ב, מובן, דזה שהמצוות נעשים לבושים להנשמה הוא (לא (כ\"כ) מצד הבירור שנעשה ע\"י קיום המצוות אלא) מצד המצוות גופא."],["178","67","ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא פל\"ז (מז, א</a>) שגם ע\"י לימוד התורה נעשה הבירור דהגוף ודנה\"ב. אבל עיקר הבירור הוא ע\"י קיום המצוות דוקא – ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310040\" data-slug=\"tanya\" data-id=\"3401310040\">תניא פל\"ה (מה, א</a>)."],["179","68","אבות פ\"ב מי\"ב. רמב\"ם הל' דעות ספ\"ג. טושו\"ע או\"ח סרל\"א. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300241661\" data-slug=\"likkutei-sichot\" data-id=\"1300241661\">לקו\"ש חכ\"ד ע' 646</a> בהערה ד\"ה כל מעשיך לשם שמים."],["180","69","משלי ג, ו. רמב\"ם וטושו\"ע שם. שו\"ע אדה\"ז או\"ח סקנ\"ו ס\"ב."],["181","70","ראה בארוכה לקו\"ש ח\"ג ע' 907. שם ע' 932. ח\"י ע' 104."],["182","71","ד\"ה ואני נתתי ושלאחריו (סה\"מ עת\"ר ע' קיז ואילך)."],["183","72","ראה תו\"ח פרשתנו כו, א."],["184","73","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310010\" data-slug=\"tanya\" data-id=\"3401310010\">תניא פ\"ה</a>. ובכ\"מ."],["185","74","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא פל\"ז (מח, ב</a>). וזה בא בהמשך למ\"ש שם רפל\"ו, שתכלית הבריאה הוא שיהי' דירה לו ית' בתחתונים (בעוה\"ז הגשמי) שאין תחתון למטה ממנו."],["186","75","ראה תנחומא נשא טז. בחוקותי ג. במדב\"ר פי\"ג, ו. תניא רפל\"ו."],["187","76","תניא שם."],["188","77","ראה המשך תרס\"ו ע' ז (וראה שם ע' ה). שם ע' תמו."],["189","78","וראה שיחת מוצאי ש\"פ נח ה'תשל\"ח ס\"ד ובהערות שם (<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201004\" data-slug=\"likkutei-sichot\" data-id=\"1300201004\">לקו\"ש ח\"כ ע' 4-283</a>)."],["190","79","זח\"ב מב, ב."],["191","80","ע\"ח בתחלתו. שער ההקדמות להאריז\"ל הקדמה ג. וראה לקו\"ש שם הערה 24."],["192","81","הובא באוה\"ת בלק ע' תתקצז. המשך תרס\"ו ס\"ע ז. ובכ\"מ."],["193","82","תו\"א פרשתנו (כא, א). תו\"ח שם (כב, סע\"ד ואילך). ובכ\"מ.\nבתו\"א ותו\"ח שם, שאבני המקום הם האותיות דדבר הוי' שבהם נבראו שמים וארץ. אבל ראה הגהות הצ\"צ לתו\"א שם (אוה\"ת פרשתנו קצה, א ואילך בשוה\"ג (ד)) שקאי גם על אותיות התפלה וכו' – אותיות שבאדם."],["194","83","ראה ספר יצירה פ\"ד מי\"ב (ובמפרשים שם)."],["195","84","ישעי' כא, יב."],["196","85","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370190\" data-slug=\"torah-or\" data-id=\"3901370190\">תו\"א מקץ מב, ב</a>. סה\"מ תקס\"ג ח\"א ע' שיא. אוה\"ת פרשתנו שם קצה, ב בשוה\"ג (ד). אוה\"ת בשלח ס\"ע שצא. ובכ\"מ. וראה של\"ה ג, ב."],["197","86","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370293\" data-slug=\"torah-or\" data-id=\"3901370293\">תו\"א בשלח סה, ד</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380129\" data-slug=\"likkutei-torah\" data-id=\"4001380129\">לקו\"ת צו יג, ב</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380650\" data-slug=\"likkutei-torah\" data-id=\"4001380650\">מטות פב, א</a>. מאמרי אדהאמ\"צ דברים ח\"ב ע' תקעה. וש\"נ. אוה\"ת שלח כרך ו ע' א'תשע ואילך. וש\"נ. סה\"מ ה'ש\"ת ע' כו. ה'תש\"ח ע' 99-98. ד\"ה נתת ליראיך ה'תשל\"ו ס\"ז (לקמן ח\"ד ע' נד). וש\"נ."],["198","87","עקב ח, ג. ל\"ת וס' הליקוטים להאריז\"ל עה\"פ."],["199","88","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370016\" data-slug=\"torah-or\" data-id=\"3901370016\">תו\"א בראשית ד, ג</a>-ד."],["200","89","כ\"ה הלשון (גבוה גבוה – ב' פעמים) ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381221\" data-slug=\"likkutei-torah\" data-id=\"4001381221\">לקו\"ת שה\"ש כג, א</a>. תו\"ח פרשתנו כג, ד. מאמרי אדהאמ\"צ דברים ח\"ג ריש ע' תתצז. סה\"מ ה'ש\"ת וה'תש\"ח שם. ובכ\"מ."],["201","90","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310040\" data-slug=\"tanya\" data-id=\"3401310040\">תניא פל\"ה</a>, ש\"כדי להמשיך . . גם על גופו כו'\" אינו מספיק דיבור (דתורה) כ\"א \"צריך לקיים מצוות מעשיות הנעשים ע\"י הגוף ממש\" – אף שבכללות נעשה זה גם ע\"י הדיבור לפי דעקימת שפתיו הוי מעשה (<a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא פל\"ז – מז, א</a>)."],["202","91","אבות פ\"א מי\"ז. תקו\"ז תנ\"ב (פז, סע\"א). ת\"ס (צג, ב). ת\"ע (קלג, ב. קלד, א)."],["203","92","ד\"ה מי יתנך תקס\"ה (סה\"מ תקס\"ה ח\"א ע' תפט. ועם הגהות – ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770311\" data-slug=\"or-hatorah-hb\" data-id=\"8316770311\">אוה\"ת שה\"ש כרך ב ע' תרעט</a> ואילך). אוה\"ת בלק ע' תתקצז. סה\"מ תרס\"ב ע' שלח. תרע\"ח ע' קצג. המשך תרס\"ו ס\"ע ג. שם ע' תמה. סה\"מ תרצ\"ט ע' 84. ובכ\"מ."],["204","93","להעיר מהמבואר בכ\"מ (סה\"מ תרצ\"ט שם. ובכ\"מ) דזה שנש\"י בכחם לעשות דירה לו ית' לו לעצמותו הוא מצד זה שנש\"י מושרשים בעצמות."],["205","94","ע\"ח שער מ\"ב (שער דרושי אבי\"ע) פ\"ה. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380824\" data-slug=\"likkutei-torah\" data-id=\"4001380824\">לקו\"ת ראה כז, א</a>."],["206","95","הל' גירושין ספ\"ב."],["207","96","<a class=\"ft-cite\" href=\"#/read/tanya/3401310023\" data-slug=\"tanya\" data-id=\"3401310023\">תניא פי\"ח</a>."],["208","97","בתניא שם, שכח המס\"נ הוא מבחי' חכמה שבנפש. ובקיצורים והערות לתניא שם (ע' צט) וב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381325\" data-slug=\"likkutei-torah\" data-id=\"4001381325\">לקו\"ת שה\"ש (מט, סע\"ב</a> ואילך) שהוא בחי' חי' (אבל יחידה היא למעלה מחכמה). אבל ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380871\" data-slug=\"likkutei-torah\" data-id=\"4001380871\">לקו\"ת תצא (לח, ג</a> ואילך) ובמאמרי אדהאמ\"צ דברים ח\"ב ע' תרמד ואילך (נדפס גם באוה\"ת תצא ע' תתקפב ואילך) שכח המס\"נ הוא מבחי' (קוצו של יו\"ד –) יחידה שלמעלה מחכמה*. וראה גם קונטרס העבודה פ\"ה (ע' 30).\nוראה לקו\"ש ח\"ד ע' 1202 בהערה, שכח המס\"נ הוא מבחי' יחידה, אלא שהארת היחידה (שממנה בא כח המס\"נ) היא בבחינת חכמה (ראש) שבנפש – דוגמת בחי' יחידה הכללית המאירה (שע\"ת לאדהאמ\"צ ח\"א (שער התפלה) ד\"ה פדה בשלום סי\"ב) בראשי ישראל."],["209","98","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380867\" data-slug=\"likkutei-torah\" data-id=\"4001380867\">יבמות קכב, א</a>. וש\"נ. לקו\"ת תצא לז, ג. מאמרי אדהאמ\"צ דברים ח\"ב ס\"ע תקמב ואילך."],["210","99","רמב\"ם הל' תשובה פ\"ז ה\"ה."],["211","100","ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300111002\" data-slug=\"likkutei-sichot\" data-id=\"1300111002\">לקו\"ש חי\"א ע' 2</a>. וראה הל' ת\"ת לאדה\"ז פ\"ד ס\"ג. תניא ספל\"ט."],["212","101","ראה סמ\"ק, הובא בב\"י או\"ח סס\"א (ד\"ה כתב סמ\"ק)."],["213","102","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380174\" data-slug=\"likkutei-torah\" data-id=\"4001380174\">לקו\"ת תזריע כג, ג</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370248\" data-slug=\"torah-or\" data-id=\"3901370248\">תו\"א וארא נה, סע\"ב</a>."],["214","103","ראה סה\"מ קונטרסים ח\"א קב, ב: \"(הוי') אחד פירושו הוא איינער כמו יחיד דפירושו איינציג\". ורק \"שהאחדות (דאחד) ניכרת מפרטי הנבראים וההתהוות\". וראה גם ד\"ה הוי' לי בעוזרי ה'תשי\"ז (לקמן ח\"ד ע' יח ואילך) סי\"א (מסה\"מ תרפ\"ז ע' רא. קונטרסים ח\"א קעט, א)."],["215","104","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380816\" data-slug=\"likkutei-torah\" data-id=\"4001380816\">לקו\"ת ראה כה, א</a>. הנסמן בברכת ערב יוהכ\"פ אחרי תפלת מנחה ה'תשמ\"ז הערה 6 (סה\"ש תשמ\"ז ח\"א ע' 2)."],["216","105","<a class=\"ft-cite\" href=\"#/read/tanya/3401310024\" data-slug=\"tanya\" data-id=\"3401310024\">ראה נדרים מא, א</a>: אין עני אלא בדעה. כתובות סח, א: עני – עני בדעת, עשיר – עשיר בדעת. זח\"ג רעג, ב. וראה להלן הערה 107.\n*) <i>בסה\"ש ה'תש\"ב ע' 80</i>,<i> שה' הלשונות שבתניא פי\"ט (כד</i>,<i> ב) </i>\"<i>טעם ודעת ושכל מושג ומובן</i>\" <i>הם כנגד ה' הבחינות יחידה חי' נשמה רוח ונפש</i>.<i> ומזה משמע שכח המס\"נ הוא מעצם הנשמה שלמעלה גם מבחי' יחידה</i>,<i> שהרי כח זה</i>, \"<b>אינו</b><i> בבחי' טעם כו</i>'\"."],["217","106","להעיר מקונטרס העבודה פ\"ה (ע' 3-32). ולהעיר גם מהמשך תרס\"ו ע' כז."],["218","107","אבות פ\"ד מ\"ט. ובמדרש שמואל שם (הובא בלקו\"ת ויקרא ו, ריש ע\"ד) דר\"ל עוני ועושר בדעת. ובלקו\"ת שם, שהעניות הו\"ע האמונה."],["219","108","ואתחנן ו, ה."],["220","109","ברכות נד, א במשנה. ספרי (הובא בפרש\"י) עה\"פ שם."],["221","110","תו\"ח ד\"ה וישלח פ\"א-ד (לט, ג ואילך. מב, א ואילך). וראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370109\" data-slug=\"torah-or\" data-id=\"3901370109\">תו\"א פרשתנו כג, ג</a>."],["222","111","פרשתנו ל, מג."],["223","112","תו\"א שם."],["224","113","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370180\" data-slug=\"torah-or\" data-id=\"3901370180\">תו\"א מקץ לט, ד</a>. דרמ\"צ קכג, ב. קמ, ב. ועוד."],["225","114","וע\"ד המבואר ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380460\" data-slug=\"likkutei-torah\" data-id=\"4001380460\">לקו\"ת שלח (לז, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380466\" data-slug=\"likkutei-torah\" data-id=\"4001380466\">שם לח, ג</a>) בפירוש טובה הארץ מאד מאד – הובא בתו\"א פרשתנו שם לענין ויפרוץ האיש מאד מאד."],["226","115","שבת סג, א. וש\"נ."],["227","116","חדא\"ג מהרש\"א לברכות לה, ב. או\"ת להה\"מ (הוצאת קה\"ת) עקב נג, ד (בהוצאת קה\"ת ה'תש\"מ ואילך – סי' קסו). אוה\"ת פרשתנו קצה, ב בשוה\"ג (ד)."],["228","117","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380217\" data-slug=\"likkutei-torah\" data-id=\"4001380217\">לקו\"ת אמור לב, סע\"ד</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381125\" data-slug=\"likkutei-torah\" data-id=\"4001381125\">ברכה צט, ג</a>. אמ\"ב שער הק\"ש פפ\"ו. הנסמן להלן בהערה 119. ועוד."],["229","118","ב\"י לטור יו\"ד סרמ\"ח."],["230","119","ראה חינוך לאדהאמ\"צ (נדפס בספרו שערי תשובה ח\"ב) פמ\"ט; אוה\"ת עקב ס\"ע תפד, שהמשכה זו הו\"ע ביטול רצון כביכול."],["231","120","איוב כב, כח."],["232","121","תנחומא וירא יט. וראה שבת נט, ב."],["233","122","מו\"ק טז, ב. וש\"נ."],["234","123","ראה אסת\"ר בסופו."],["235","124","ראה בארוכה ד\"ה מים רבים דמוצאי ש\"פ נח שנה זו (ה'תשל\"ח) ס\"ד-ה (לעיל ח\"א ס\"ע רמז ואילך)."],["236","125","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380610\" data-slug=\"likkutei-torah\" data-id=\"4001380610\">לקו\"ת בלק עג, סע\"א</a>. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תשכז. ובכ\"מ. ובלקו\"ת שם, שזהו \"התירוץ האמיתי\" למה ירדה הנשמה לעוה\"ז."],["237","126","פסחים נז, סע\"א ואילך. כריתות בסופה. וראה אוה\"ת וישלח תכו, א. ד\"ה מלכא ומלכתא תרצ\"ז."],["238","127","ב\"ר פ\"ח, ז. רות רבה פ\"ב א (ג). וראה ד\"ה מי יתנך תקס\"ה (סה\"מ תקס\"ה ח\"א ע' תפז. ועם הגהות – ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770266\" data-slug=\"or-hatorah-hb\" data-id=\"8316770266\">אוה\"ת שה\"ש כרך ב ס\"ע תרלד</a>. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770307\" data-slug=\"or-hatorah-hb\" data-id=\"8316770307\">שם ריש ע' תרעה</a>); <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316600127\" data-slug=\"or-hatorah-hb\" data-id=\"8316600127\">אוה\"ת נ\"ך כרך א ע' קכז</a>; ספר השיחות תורת שלום ע' 152, שמדייק צדיקים ולא בע\"ת."],["239","128","רמב\"ם הל' תשובה פ\"ז ה\"ד."],["240","129","ברכות לד, ב."],["241","130","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370101\" data-slug=\"torah-or\" data-id=\"3901370101\">תו\"א פרשתנו כא, ג</a>. תו\"ח פרשתנו כה, ב. וכ\"ה גם בלקו\"ת שבהערה 125; סה\"מ תקס\"ה ואוה\"ת שה\"ש שבהערה 127."],["242","131","המשך ר\"ה תש\"ג פי\"ג (סה\"מ ה'תש\"ג ע' 33-32). ובכ\"מ."],["243","132","ועל פי המבואר לעיל (סעיף ז) שבאר שבע הוא ענין משביעין אותו – הנתינת כח להנשמה שתוכל לעבוד עבודתה בירידתה למטה (שלמעלה מדרגת הנשמה כמו שהיא מצד עצמה) – צריך לומר, שהעלי' הנעשית בה על ידי עבודתו בירידתה למטה (ושבתי גו' אל בית אבי) הוא למעלה גם מבחינת משביעין אותו."],["244","133","וכמו שהוא בפשטות, שביתו של יצחק (בית אבי) הוא מקום מיוחד (ונעלה) בהעיר באר שבע."],["245","134","כמו שאמרה שרה בלידת יצחק (וירא כא, ו) \"צחוק עשה לי אלקים כל השומע יצחק לי\" (ובפרש\"י: יצחק לי – ישמח עלי). וראה במפרשים שם. וראה פרש\"י עה\"פ (לך לך יז, יט) וקראת את שמו יצחק: על שם הצחוק."],["246","135","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370101\" data-slug=\"torah-or\" data-id=\"3901370101\">תו\"א פרשתנו כא, ג</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370084\" data-slug=\"torah-or\" data-id=\"3901370084\">שם כב, ג</a>. תולדות יז, ד ואילך. תו\"ח פרשתנו כד, סע\"ד ואילך. תולדות ה, ג. וראה גם שם יא, א."],["247","136","כהשמחה (צחוק) דלידת יצחק שהי' דבר פלא – ראה רמב\"ן עה\"פ וירא שם, ז: כל השומע יצחק לי למלאות פיו ברנה ושחוק בפלא הנעשה לי. וברשב\"ם עה\"פ שם, ו: צחוק – שמחה של תמהון."],["248","137","ראה גם ד\"ה ביום השמיני עצרת גו' ה'תש\"מ ס\"ה (לעיל ח\"א ע' רכ ואילך). ד\"ה ביום השמיני שלח את העם גו' ה'תשמ\"א (שם ע' קלד ואילך)."],["249","138","הל' תשובה פ\"ז ה\"ז. וראה גם שם ה\"ו."],["250","139","ראה רמב\"ם שם ה\"ד."],["251","140","רמב\"ם שם ה\"ז."],["252","141","ומ\"ש ברמב\"ם שם \"שנאמר\" (שמזה משמע שהוא ענין אחד עם \"צועק ונענה מיד\") – ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300121061\" data-slug=\"likkutei-sichot\" data-id=\"1300121061\">לקו\"ש חי\"ב ע' 61</a> הערה 28."],["253","142","ישעי' סה, כד."],["254","143","ראה גם ד\"ה ביום השמיני עצרת ה'תש\"מ שם."],["255","144","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310029\" data-slug=\"tanya\" data-id=\"3401310029\">תניא פכ\"ד</a> (ובכ\"מ) שבשעת החטא וכו' הם בתכלית <i>הפירוד</i> כו' (שזהו פי' סט\"א – ראה לקמן בפנים)."],["256","145","ראה לקמן סעיף יז."],["257","146","<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670125\" data-slug=\"torat-chaim\" data-id=\"2300670125\">ראה ד</a>\"ה לריח שמניך תש\"ו ס\"ו (סה\"מ ה'תש\"ו ע' 105), שתוקף הרצון דנה\"א הבא ע\"י הסתר והעלם הנה\"ב \"אין זה התחדשות\", לפי שרצון זה יש בנה\"א בעצם, ורק <i>שמתעורר</i> ע\"י הסתר נה\"ב [ולכן \"לא הגיע בזה לבחי' העצמות כ\"א בבחי' הגילויים לבד\"], ואמיתית העילוי הוא \"כאשר הנה\"א בעבודתו עושה ופועל שהנה\"ב עצמו יתעורר כו'\" [ש\"בזה הוא מגיע בעצמות א\"ס\"].\nוראה גם תו\"ח נח ס, סע\"ב ואילך, שעיקר הענין דיתרון האור מן החושך הוא (לא שהחושך <i>גורם</i> ליתרון האור כי אם) כשהחושך עצמו נהפך לאור."],["258","147","דנוסף לזה שהוא חידוש גדול יותר (כבהערה הקודמת), הרי מכיון שבזה דוקא נשלם מה שנתאוה כו' דירה בתחתונים [ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310041\" data-slug=\"tanya\" data-id=\"3401310041\">תניא פל\"ו</a>, שענין נתאוה כו' דירה בתחתונים הוא \"שכך עלה ברצונו ית' להיות נח\"ר לפניו ית' כד אתכפיא סט\"א ואהתפך חשוכא לנהורא\"] – הרי תענוג זה* הוא כביכול בעצמותו ית' (ראה לעיל סעיף יו\"ד שענין נתאוה הוא בעצמותו ית')."],["259","148","<a class=\"ft-cite\" href=\"#/read/tanya/3401310032\" data-slug=\"tanya\" data-id=\"3401310032\">תניא פכ\"ז</a>."],["260","149","ראה תניא שם ולקו\"ת ר\"פ פקודי (מזח\"ב קכח, ב. וראה גם שם סז, ב. קפד, א). <a class=\"ft-cite\" href=\"#/read/torah-or/3901370403\" data-slug=\"torah-or\" data-id=\"3901370403\">תו\"א ויקהל פט, ד</a>. לקו\"ת חוקת סה, ג. ד\"ה באתי לגני ה'שי\"ת פ\"א. ועוד."],["261","150","בתו\"א שם מובא מאמר זה בהמשך להמבואר שם המעלה דאתכפיא על אתהפכא. אבל בד\"ה באתי לגני שם: ע\"י העבודה דבחינת אתכפיא ואתהפכא."],["262","151","תו\"א שם."],["263","152","פרשתנו כב, ג."],["264","153","פרשתנו כה, א-ב.\n*) <i>משא\"כ ענין התשובה דנה\"א (שגם בירידתה למטה</i>,<i> וגם כשעוסקת בעניני הרשות</i>,<i> היא דבוקה באלקות) הוא דוגמת ענין </i>\"<i>יתגלו שלימות כחותיו כו'</i>\"<i> (ראה שיחת מוצאי ש\"פ נח שנה זו (ה'תשל\"ח) הערה 30 – <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201297\" data-slug=\"likkutei-sichot\" data-id=\"1300201297\">לקו\"ש ח\"כ ע' 284</a>)</i>,<i> שהוא רק בבחי' הגילויים (כנ\"ל סעיף יו\"ד)</i>."],["265","154","להעיר מהמבואר בכ\"מ (ד\"ה מלכא ומלכתא תרצ\"ז בסופו. וראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370039\" data-slug=\"torah-or\" data-id=\"3901370039\">תו\"א נח ט, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381307\" data-slug=\"likkutei-torah\" data-id=\"4001381307\">לקו\"ת שה\"ש מד, סע\"ד</a>) שיושבי אוהל ובעלי עסקים הם דוגמת צדיקים ובעלי תשובה."],["266","155","ישעי' ס, כא. סנהדרין ר\"פ חלק."],["267","156","תהלים נה, יט."],["268","157","ראה \"בית רבי\" ח\"ב ספ\"ה בהערה א שגאולת אדהאמ\"צ היתה בשעה שאמר בתהלים הפסוק \"פדה בשלום נפשי\". וראה רד\"ה פדה בשלום שנה זו – ה'תשל\"ח – (לקמן ע' קמב); בשיחה שלפני המאמר."],["269","158","<a class=\"ft-cite\" href=\"#/read/tanya/3401310006\" data-slug=\"tanya\" data-id=\"3401310006\">תניא פ\"א</a>. פ\"י. ועוד."],["270","159","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310012\" data-slug=\"tanya\" data-id=\"3401310012\">תניא רפ\"ז</a>."],["271","160","ראה בארוכה שיחת מוצאי ש\"פ חיי שרה שנה זו (ה'תשל\"ח) סכ\"ו (<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201005\" data-slug=\"likkutei-sichot\" data-id=\"1300201005\">לקו\"ש ח\"כ ע' 5-334</a>), שאמיתית הענין ד\"וכל מעשיך יהיו לשם שמים\" ו\"בכל דרכיך דעהו\" הוא כאשר עשייתו עניני הרשות הוא מצד זה שמתאווה להם בטבעו, ואעפ\"כ הוא באופן ד\"לשם שמים\" ו\"דעהו\"."],["272","161","<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316480046\" data-slug=\"or-hatorah-hb\" data-id=\"8316480046\">ח\"א כג, ב</a> – הובא באוה\"ת פרשתנו כרך ה תתנד, א."],["273","162","ולהעיר, שבאוה\"ת שם: ונתן לי לחם גו' (ואח\"כ) ושבתי בשלום (כהסדר בכתוב)."],["274","163","ראה – נוסף לזהר שם – זח\"א ריש פרשתנו (קמז, א): אוקי האי קרא בגלותא. ב\"ר פרשתנו פס\"ח, יג. ובשל\"ה פרשתנו (רצב, ב): ענין ויצא יעקב רומז ג\"כ לגלות. ע\"ש."],["275","164","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380108\" data-slug=\"likkutei-torah\" data-id=\"4001380108\">ב\"מ קז, סע\"ב</a>. וש\"נ. וראה גם איכ\"ר פ\"ג, נ. פרש\"י עה\"פ בראשית ד, כה. ולהעיר מלקו\"ת צו ח, רע\"א."],["276","165","<a class=\"ft-cite\" href=\"#/read/tanya/3401310007\" data-slug=\"tanya\" data-id=\"3401310007\">תניא רפ\"ב</a>."],["277","166","יומא פו, ב."],["278","167","ראה דרמ\"צ קצא, ריש ע\"ב."],["279","168","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370037\" data-slug=\"torah-or\" data-id=\"3901370037\">תו\"א נח ט, א</a>."],["280","169","דבית ענינו התיישבות וקביעות – ראה שמואל-ב ז, ה-ז (בית לגבי אהל). מפרשים (חדא\"ג מהרש\"א, עיון יעקב לע\"י, ועוד) לפסחים פח, א (בית לגבי הר ושדה)."],["281","170","מלכים-א כב, מח."],["282","171","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380944\" data-slug=\"likkutei-torah\" data-id=\"4001380944\">לקו\"ת דברים א</a>, <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151249\" data-slug=\"likkutei-sichot\" data-id=\"1300151249\">ריש ע\"ב</a>. דרושים לר\"ה נו, סע\"ב ואילך. אוה\"ת ר\"ה ע' א'שמא. מאמרי אדהאמ\"צ דברים ח\"ג ע' א'מה. וש\"נ. הנסמן בלקו\"ש חט\"ו ע' 237 הערה 60. ובכ\"מ."],["283","172","ראה תו\"ח שם כז, א-ב שבחי' אלקים דוהאבן הזאת גו' בית אלקים היא למעלה מבחי' אלקים דוהי' הוי' לי לאלקים."],["284","173","בתו\"ח שם (כז, א), דזה שוהאבן הזאת גו' בית אלקים הוא למעלה מוהי' הוי' לי לאלקים הוא לפי שוהי' גו' לאלקים הוא ע\"י התומ\"צ דצדיקים (לחם ובגד), וענין והאבן הזאת גו' בית אלקים הוא ע\"י הבירורים דתשובה (ושבתי בשלום). אבל ע\"פ המבואר לעיל סעיף טז (ובהערה 147 ובשוה\"ג שם) שגם העילוי שבעבודת התשובה (דנפש האלקית) הוא רק בבחי' הגילויים – יש לומר, שגם בעבודת הבירורים (\"ושבתי בשלום גו'\") גופא ב' ענינים: העילוי שנעשה באדם עי\"ז, התשובה דנה\"א, ועי\"ז – \"והי' הוי' לי לאלקים\"; הבירור דדברים הגשמיים גופא, ועי\"ז \"<i>והאבן</i> גו' בית אלקים\"."],["285","174","פרשתנו כח, יח."],["286","175","וישב לז, ז."],["287","176","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370103\" data-slug=\"torah-or\" data-id=\"3901370103\">תו\"א פרשתנו כב, סע\"א</a>. תו\"ח שם כד, א."],["288","177","תו\"א שם."],["289","178","שם כב, ב."],["290","179","ראה אוה\"ת פרשתנו קצד, ב."],["291","180","וכמו שמדייק בתו\"א ריש פרשתנו (כא, א). תו\"ח שם (כב, ב)."],["292","181","ראה מכילתא עה\"פ בשלח טו, א. שמו\"ר פכ\"ג, יא. תוד\"ה ה\"ג ונאמר – פסחים קטז, ב."],["293","182","תהלים קכו, ב. וראה ברכות לא, א. טושו\"ע או\"ח סו\"ס תקס. וראה ד\"ה ויהיו חיי שרה ה'תשמ\"א ס\"ה (לעיל ח\"א ע' רפא)."],["294","183","שבת פט, ב."],["295","184","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370101\" data-slug=\"torah-or\" data-id=\"3901370101\">תו\"א פרשתנו כא, ג</a>. תו\"ח פרשתנו כד, ד. ועוד."],["296","185","ישעי' יא, ט."],["297","186","וירא כא, ו."],["298","187","ראה בארוכה שיחת מוצאי ש\"פ חיי שרה שנה זו (ה'תשל\"ח) סעיף מא (<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201356\" data-slug=\"likkutei-sichot\" data-id=\"1300201356\">לקו\"ש ח\"כ ע' 343</a>)."],["299","188","ב\"ר פ\"ע, ד. וראה אוה\"ת פרשתנו קצז, סע\"ב. שם כרך ה תתנג, סע\"ב ואילך."],["300","189","ראה פרש\"י עה\"פ. ירושלמי סוטה פ\"א ה\"ח."],["301","190","המשך פדה בשלום תרנ\"ט (סה\"מ תרנ\"ט ע' קסד) ותש\"ד (סכ\"א – סה\"מ ה'תש\"ד ע' 11-110). ועוד."],["302","191","דברי הימים-א כב, ח-י."],["303","192","כמ\"ש אדה\"ז בנוגע לגאולתו בי\"ט כסלו (אגרות-קודש שלו [ח\"א] סי' לח. וש\"נ) \"כשקריתי בס' תהלים בפסוק פדה בשלום נפשי כו' יצאתי בשלום כו'\". וראה אגרות-קודש אדמו\"ר מוהריי\"צ ח\"ג ע' תעג ואילך."],["304","193","ראה לעיל הערה 157. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300251160\" data-slug=\"likkutei-sichot\" data-id=\"1300251160\">לקו\"ש חכ\"ה</a> שיחה ליו\"ד כסלו (ע' 160 ואילך), די\"ל שהשייכות דהפסוק \"פדה בשלום\" ליו\"ד כסלו היא יותר משייכותו לי\"ט כסלו."],["305","194","ב\"ר פט\"ז, ה."],["306","195","נדפס בספרו שערי תשובה ח\"א (שער התפלה) מט, א ואילך. – סעיף יא ואילך (נה, ג ואילך)."],["307","196","דשנת תרנ\"ט (ראה סה\"מ תרנ\"ט שם), תרע\"ה (המשך תער\"ב ח\"ב ע' תשסט. שם ע' תשעה), תש\"ד (ראה סה\"מ ה'תש\"ד שם). ועוד. וראה גם אוה\"ת לתהלים (יהל אור) עה\"פ (ס\"ע רח)."],["308","197","ד\"ה פדה בשלום תרע\"ה (המשך תער\"ב ח\"ב פשע\"ד – ע' תשסט). וראה גם שערי תשובה שם (נה, ד ואילך)."],["309","198","צפני' ג, ט."],["310","199","פירוש המשנית להרמב\"ם סנהדרין פ' חלק יסוד הי\"ב. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300081225\" data-slug=\"likkutei-sichot\" data-id=\"1300081225\">לקו\"ש ח\"ח ע' 215</a> הערה 53. וש\"נ."],["311","200","<a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא רפל\"ז</a>."],["312","201","ספר השיחות תורת שלום ע' 86. לקוטי דבורים כרך ד תשנו, ב ואילך."],["313","202","נדרים ח, ב. ע\"ז ג, סע\"ב. זח\"ג יז, רע\"א. וראה תו\"א ותו\"ח שבהערה 204."],["314","203","ישעי' ל, כ. וראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310041\" data-slug=\"tanya\" data-id=\"3401310041\">תניא פל\"ו (מו, א</a>)."],["315","204","בתו\"ח פרשתנו (כו, ד), שהוי' יהי' בגילוי כמו שם אלקים. אבל ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370102\" data-slug=\"torah-or\" data-id=\"3901370102\">תו\"א שם (כא, ד</a>): שם הוי' יהי' אז בחי' אלקים לגבי בחי' עונג העליון. ושם כב, ג: נחשב בחי' אלקים דהיינו בחי' צמצום."],["316","205","ראה לעיל סעיף חי. כה."],["317","206","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381199\" data-slug=\"likkutei-torah\" data-id=\"4001381199\">לקו\"ת שמע\"צ פה, א</a>. שה\"ש יז, ג. ובכ\"מ."],["318","207","אבות פ\"ד מי\"ז."],["319","208","המשך וככה תרל\"ז פי\"ב."],["320","209","פרשתנו שם, יד."],["321","210","מכיון ש\"אחישנה\" תלוי ב\"זכו\" (סנהדרין צח, א)."],["322","211","איוב כח, ג."],["323","212","עקב יא, יב."],["324","213","ראה יב, כ. שופטים יט, ח. וראה ספרי עה\"פ ראה שם. פרש\"י עה\"פ שופטים שם."],["325","214","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091023\" data-slug=\"likkutei-sichot\" data-id=\"1300091023\">לקו\"ש ח\"ט ע' 23</a> הערה 61."]]],[1500370005,"<h3>בס\"ד. מוצאי ש\"פ ויצא, ט' כסלו, אור ליו\"ד כסלו, ה'תשל\"ט<sup data-n=\"326\">*</sup></h3>\n<b>פדה</b> בשלום נפשי מקרב לי כי ברבים היו עמדי<sup data-n=\"327\">1</sup>, ומבאר בעל הגאולה במאמרו ד\"ה זה (שנדפס בספרו שערי תשובה<sup data-n=\"328\">2</sup>)<sup data-n=\"329\">3</sup> דפירוש פדה בשלום (בשלום דוקא) הוא שהפדי' היא באופן שהמנגד מתבטל לגמרי, שלכן אין צריך למלחמה כלל. וע\"ד שהי' בימי שלמה<sup data-n=\"330\">4</sup>, שכל הגוים נתבטלו לגבי שלמה שלא ע\"י מלחמה, שלכן נקרא בשם שלמה כי שלום הי' בימיו<sup data-n=\"331\">5</sup>. ומדייק בהמאמר<sup data-n=\"332\">6</sup>, דכאשר נמצאים במצב שאין מנגדים כלל, למה צריך פדי'. ויש לומר הביאור בדיוק זה, כי פירוש פדה בשלום הוא לא שהשלום בא לאחרי הפדי' (היינו שהפדי' היא בדרך מלחמה ואח\"כ נעשה שלום), כי אם, שהפדי' (עצמה) היא בשלום, ולכן מדייק, שבמצב של שלום אין צריך לכאורה לפדי'. ויש להוסיף עוד דיוק, דבפסוק זה גופא כתיב פדה גו' מקרב לי, דזה שפדה נפשי הוא מן המלחמות הבאים עלי<sup data-n=\"333\">7</sup>, והיאך שייך שהפדי' מן המלחמות היא פדי' בשלום, דלכאורה הם שני ענינים הפכים.\nב) <b>ויש</b> להוסיף, דשני ענינים אלו (פדה בשלום ומקרב לי) הם לא רק שני הפכים (סתם) אלא שהם הפכים מן הקצה אל הקצה. דהנה הטעם על זה שמלחמה נקראת בשם קרב מלשון קירוב (אף שמלחמה הוא היפך ענין הקירוב), הוא (כמובן מהמאמר<sup data-n=\"334\">8</sup>), לפי שעיקר ותוקף של מלחמה הוא כשהיא באופן של קירוב. דהנה במלחמה יש שני אופנים. ששני הלוחמים הם בריחוק זה מזה, אלא שזורקים (אחד על השני) אבני חצים ובליסטראות וכיו\"ב. או ששני הלוחמים מתקרבים זה לזה (בקירוב מקום) ועד שהם נאבקים זה עם זה<sup data-n=\"335\">9</sup>, ויאבק איש עמו<sup data-n=\"336\">10</sup>, שהם מתקרבים זה לזה (לא רק במקום, אלא) גם בגופם, ועד דשני הלוחמים חובקים זה את זה. דמלחמה זו (תכלית הקירוב) היא מלחמה קשה ביותר.<b>ועד\"ז</b> הוא לאידך, שגם השלום שבפסוק זה הוא (לא שלום סתם, אלא) תכלית השלימות שבשלום. וכמו שמבאר בעל הגאולה בהמאמר<sup data-n=\"337\">11</sup> דאמיתית הענין דפדה בשלום נפשי הוא שאלו שהיו מקודם שונאים ומנגדים הם \"נעשים אוהבים גמורים\", דענין זה הוא למעלה גם מהשלום שהי' בימי שלמה<sup data-n=\"338\">12</sup>, דהשלום שהי' בימי שלמה הוא שכולם נתבטלו מצד הגילוי אור (אבל לא נהפכו לקדושה)<sup data-n=\"339\">13</sup>, ואמיתית ענין השלום (שגם המנגד נהפך לקדושה) יהי' לע\"ל, כמ\"ש<sup data-n=\"340\">14</sup> אז אהפוך אל עמים שפה ברורה גו' לעבדו שכם אחד, ועד\"ז בנוגע לבעלי חיים – וגר זאב עם כבש וגו'<sup data-n=\"341\">15</sup>, ועד שגם הנחש (פתן וצפעוני<sup data-n=\"342\">16</sup>) יהפך לטוב, כמ\"ש<sup data-n=\"343\">17</sup> גם אויביו ישלים אתו זה הנחש, וכמו שהי' בתחלת הבריאה (לפני חטא עה\"ד) שהי' שמש גדול<sup data-n=\"344\">18</sup>. ויתירה מזו יש לומר, דכיון שכל ירידה היא צורך עלי', בהכרח לומר, שבירור ועליית הנחש לעתיד לבוא תהי' למעלה יותר גם מהדרגא ד\"שמש גדול\" שהי' לפני הירידה<sup data-n=\"345\">19</sup>. ועפ\"ז צריך להבין עוד יותר מ\"ש פדה בשלום גו' מקרב לי, והרי הקרב והשלום שבפסוק זה הם שני הפכים מן הקצה אל הקצה, ואיך זה פדה בשלום גו' מקרב לי.\nג) <b>ויובן</b> זה בהקדים המבואר בהמאמר דבעל הגאולה<sup data-n=\"346\">20</sup>, ששני הענינים דקרב ושלום ישנם בעבודת התפלה. ולהעיר, דבכ\"מ<sup data-n=\"347\">21</sup> מבואר שהבירור דתפלה הוא בדרך מלחמה, שעת צלותא שעת קרבא<sup data-n=\"348\">22</sup>, והבירור בדרך מנוחה (שלום) הוא ע\"י עסק התורה<sup data-n=\"349\">23</sup>. אבל בדרוש זה דבעל הגאולה מבואר, שגם בעבודת התפלה ישנם שני הענינים. האהבה<sup data-n=\"350\">24</sup> דבכל לבבך, שמצד בחינת נר\"נ, עם היות שגם ע\"י אהבה זו הוא פועל שגם נה\"ב יהי' לה אהבת ה', בכל לבבך בשני יצריך<sup data-n=\"351\">25</sup>, מ\"מ, מכיון שהאהבה דבכל לבבך היא מצד ההבנה וההשגה (שאלקות הוא טוב), ומכיון ששכל הוא בחינת פנימי (שמתלבש בהדבר שפועל בו), הרי מובן דפעולת נה\"א בנה\"ב שתאהוב את הוי' הוא ע\"י שנה\"א מתלבשת בנה\"ב, שההתבוננות של נה\"א צריכהלהיות בענינים כאלו ובאופן שגם נה\"ב יכולה להשיג<sup data-n=\"352\">26</sup>, הרי התלבשות זו (שנה\"א מתלבשת בנה\"ב) הו\"ע של מלחמה<sup data-n=\"353\">27</sup>. וגם האהבה דבכל נפשך, שמצד בחינת חי', הגם שחי' היא בחינת מקיף, והבירור דנה\"ב שע\"י אהבה זו הוא (לא בדרך התלבשות, אלא) שמצד תוקף הרצון דנה\"א (רצון שלמעלה מטעם) מתבטלים ממילא הרצונות דנה\"ב, אעפ\"כ, מכיון שביטול הרצונות דנה\"ב הוא רק מצד התגברות הרצון דנה\"א, היינו שגם עכשיו יש לנה\"ב בהעלם רצונות זרים אלא שמצד התגברות הרצון דנה\"א אינם באים בפועל, לכן נכלל זה בהעבודה דבירור שבדרך מלחמה. וענין פדה בשלום נפשי הוא בהאהבה דבכל מאדך, שמצד בחינת יחידה. כי כיון שבחינת היחידה אין כנגדה לעומת זה, בבואה דבבואה לית להו<sup data-n=\"354\">28</sup>, לכן, כשמתגלית בחינת היחידה, מתבטל הלעו\"ז. דבחינת חי', כיון שיש כנגדה לעו\"ז, לכן הגילוי דבחינת חי' אינו שולל ומבטל הרצונות זרים דנה\"ב, והוא רק בדרך התגברות, שהרצון לאלקות (שמבחינת חי') מתגבר על הרצונות דנה\"ב, ובכדי שיהי' ביטול הרצונות דנה\"ב הוא ע\"י גילוי היחידה.\nד) <b>ויש</b> לקשר זה עם הידוע<sup data-n=\"355\">29</sup> בענין כח המס\"נ שבכאו\"א מישראל (דכח המס\"נ הוא מצד יחידה<sup data-n=\"356\">30</sup>), דזה שהוא מוסר נפשו שלא להפרד ח\"ו מאחדותו ית' הוא לא מצד הרצון שלו (היינו שאפשר להיות באופן אחר אלא שרוצה באופן זה), אלא מפני שאינו יכול להפרד ח\"ו מאחדותו ית'. ועפ\"ז יש לבאר מה שמבואר בכ\"מ<sup data-n=\"357\">31</sup> שהאהבה דבכל מאדך הו\"ע המס\"נ. דלכאורה אינו מובן, והרי גם האהבה דבכל לבבך ובכל נפשך מחייבת לכאורה ענין המס\"נ, דכשאוהב את הוי' בכל לבבו ועאכו\"כ כשאהבתו את הוי' היא בכל נפשו הרי בודאי ימסור נפשו עבורו<sup data-n=\"358\">32</sup>, ומהו העילוי והחידוש בהאהבה דבכל מאדך. והביאור בזה, שהמס\"נ שמצד האהבה דבכל לבבך ובכל נפשך היא באופן שרוצה למסור נפשו עבור הוי' (באהבה דבכל לבבך, נר\"נ – רצון שע\"פ טו\"ד, ובאהבה דבכל נפשך, חי' – רצון שלמעלה מטעם), משא\"כ המס\"נ שמצד האהבה דבכל מאדך, יחידה, היא באופן שאינו יכול להיות נפרד ח\"ו. וזהו שענין המס\"נ הוא בהאהבה דבכל מאדך, כי מס\"נ הו\"ע הביטול, ואמיתית ענין הביטול הוא כשהמס\"נ היא לא מצד הרצון (מציאות) שלו אלא מצד האלקות. ויש לומר, שזהו גם מהביאורים בזה שביטול הרצונות זרים דנה\"ב הוא דוקא בהאהבה דבכל מאדך, כי האהבה דבכל לבבך ובכל נפשך, מכיון שמצד אהבה זו יש אפשרות שלא למסור נפשו (וזה שמוסר נפשו הוא רק מצד הרצון), הרי זה מוכיח שנשאר עדיין מציאות הלעו\"ז. והביטול דלעו\"ז (ביטול לגמרי) הוא ע\"י האהבה דבכל מאדך, שמצד אהבה זו <i>אי אפשר</i> להיות באופן אחר ח\"ו.ה) <b>והנה</b> בהמאמר הנ\"ל דבעל הגאולה בתחלת הענין<sup data-n=\"359\">33</sup> מבואר דענין המלחמה (של נה\"א עם נה\"ב) היא בנר\"נ המלובשים בגוף ונה\"ב, משא\"כ בהמקיפים דחי' יחידה לא שייך מלחמה. אלא שלאח\"ז בהמשך המאמר<sup data-n=\"360\">34</sup> מבאר בפרטיות יותר שגם בבחינת חי' יש ענין המלחמה, וענין השלום הוא ביחידה דוקא. ויש לומר, שהוא ע\"ד שאמר הקב\"ה לדוד המלך (כשרצה לבנות בית המקדש) דם לרוב שפכת גו' (ולכן) לא תבנה בית לשמי גו' הנה בן נולד לך הוא יהי' איש מנוחה גו' הוא יבנה בית לשמי גו'<sup data-n=\"361\">35</sup>. אלא שאעפ\"כ תבנית המקדש נעשה ע\"י דוד (מיד ה' עלי השכיל<sup data-n=\"362\">36</sup>), ויתן דויד לשלמה בנו את תבנית האולם וגו'<sup data-n=\"363\">37</sup>. וצריך להבין, דכיון שביהמ\"ק קשור עם מנוחה<sup data-n=\"364\">38</sup> ושלום דוקא, שלכן נאמר לדוד לא תבנה בית לשמי כי איש מלחמות אתה<sup data-n=\"365\">39</sup>, למה נעשו ההכנות לביהמ\"ק ע\"י דוד שהי' איש מלחמות. ויש לומר הביאור בזה, כי אז (כשרצה דוד לבנות ביהמ\"ק, ומכ\"ש כשהכין את התבנית וכו') הי' דוד במצב של מנוחה, וה' הניח לו מסביב מכל אויביו<sup data-n=\"366\">40</sup>. אלא שכיון שהמנוחה דדוד באה ע\"י המלחמות שעשה, לכן בנין ביהמ\"ק הוצרך להיות ע\"י שלמה, איש מנוחה, מנוחה בעצם. ויש לומר, דזה שמבואר בהמאמר (בתחלת הענין) שגם בבחינת חי' לא שייך מלחמה הוא ע\"ד המנוחה דדוד לאחרי שנצח כל המלחמות. דבבחינת נר\"נ שמתלבשים בהגוף ונה\"ב, כיון שפעולת נה\"א בנה\"ב היא בדרך התלבשות והתעסקות, דנפש הבהמית ההשגה שלה היא בהטוב דדברים גשמיים, ונפש האלקית מתעסקת עמה לבאר לה הטוב דאלקות, הרי זה ענין של מלחמה ממש. משא\"כ בחינת חי', כיון שפעולתה בנה\"ב הוא (לא בדרך התלבשות אלא) שמצד גילוי תוקף הרצון לאלקות דנה\"א מתבטלים במילא הרצונות דנה\"ב, אין זה ענין של מלחמה. ובכללות, הו\"ע של מנוחה. אלא שמנוחה זו היא (לא מנוחה בעצם, ורק) מצד תגבורת הרצון דנה\"א, בדוגמת המנוחה דדוד לאחרי שה' הניח לו מכל אויביו, שהמנוחה שלו היתה מצד זה שנצח כל המלחמות. משא\"כ ביטול הרצונות דנה\"ב ע\"י גילוי היחידה הוא (לא שע\"י גילוי היחידה <i>נעשה</i> ביטול הרצונות, כי אם) שמצד היחידה (שאין כנגדה לעו\"ז) אין מקום מלכתחילה לרצונות זרים, בדוגמת המנוחה דשלמה, שהיתה (לא ע\"י נצחון, אלא) מנוחה בעצם.\nו) <b>והנה</b> עד\"ז הוא בהעבודה שבדרך מלחמה שיש בה כו\"כ דרגות. דהמלחמה שבתפלה, שעת צלותא שעת קרבא, כיון שבעת התפלה הוא מופשט מעניני העולם וההתעסקות שלו היא להתבונן בעניני אלקות ולעורר אהבת ה' ויראת ה',אלא שההתבוננות (והאהוי\"ר) צריכות להיות באופן שיהי' מושג גם בהשכל דנה\"ב, אין זה מלחמה ממש (ונק' זה בשם חרב<sup data-n=\"367\">41</sup> של שלום<sup data-n=\"368\">42</sup>). והעבודה בדרך מלחמה היא בעיקר בשעת האכילה ושתי', נהמא אפום חרבא ליכול<sup data-n=\"369\">43</sup>, ועד\"ז בשאר צרכי הגוף. ובזה גופא, עיקר המלחמה היא בשעת העסק במשא ומתן, מסחר. כי המלחמה דאכילה (ועד\"ז בשאר צרכי הגוף) היא שאכילתו תהי' לשם שמים ולא למלאות תאות נפשו, היינו שלוחם <i>נגד</i> התאוה והתענוג שבהמאכל (ואינו מלובש בו), משא\"כ ההתעסקות במשא ומתן מוכרחת להיות (ע\"פ תורה) בדרך התלבשות, נשאת ונתת באמונה<sup data-n=\"370\">44</sup>. [ויש לומר, דזהו גם הטעם על זה שכללות הבירורים נק' בשם כנען, דפירוש כנען הוא סוחר<sup data-n=\"371\">45</sup>, כי עיקר הבירורים שבדרך התלבשות הוא במשא ומתן]. ונמצא, שהמלחמה דאכילה היא דוגמת המלחמה בחרב (נהמא אפום <i>חרבא</i> ליכול), דעם היות שהמלחמה דחרב היא דוקא כשהוא בקירוב להשונא (דזהו החילוק בין חרב לקשת<sup data-n=\"372\">46</sup>), הרי קירוב זה הוא רק במקום. משא\"כ המלחמה שבמשא ומתן היא דוגמת המלחמה שנקראת בשם קרב מלשון קירוב, שהקירוב דקרב הוא (לא רק במקום, אלא) ששני הלוחמים מחבקים זה את זה, כנ\"ל (סעיף ב) בארוכה.\nז) <b>וזהו</b> פדה בשלום נפשי מקרב לי, שגם עבודת הבירורים שבדרך קרב (ולא רק בדרך מלחמה אלא בדרך קרב) תהי' באופן דפדה בשלום, שלום בתכלית השלימות כהשלום שהי' בימי שלמה, ולמעלה יותר – כהשלום שיהי' לע\"ל. והטעם לזה הוא כההמשך בכתוב כי ברבים היו עמדי. שע\"י העבודה דברבים היו עמדי, שהיא התעוררות וגילוי היחידה כמבואר בארוכה בדרוש הנ\"ל דבעל הגאולה<sup data-n=\"373\">47</sup>, דכאו\"א מישראל בכחו לעורר ולגלות היחידה שבו, הנה עי\"ז נעשה פדה בשלום נפשי, נפשו של האדם העובד, דהגם שעוסק בעניני העולם בכדי לבררם באופן של קרב, מ\"מ לא יהי' נתפס בזה והפדי' שלו תהי' בשלום, ועד לשלום בתכלית השלימות. ויתירה מזו שגם פדיית הניצוצות שבעניני העולם תהי' בשלום, ברבים היו עמדי, שגם הניצוצות שהיו תחלה בבחי' רבים (כי היו בגלות ברשות הרבים טורי דפרודא)<sup data-n=\"374\">48</sup> נכללים בנשמתו של האדם המבררם, היו עמדי, ועד שהם נכללים בהיחידה שבו.\nח) <b>ויש</b> לומר שזהו גם הקשר והשייכות של הגאולה דיו\"ד כסלו ודי\"ט כסלו להפסוק פדה בשלום נפשי<sup data-n=\"375\">49</sup>, דהגם שהפדי' היתה מקרב, כולל גם זהשהמאסר בא ע\"י המלשינות של אלו שהי' להם יחס של קירוב, דזה (שהמאסר בא על ידם) הוא ירידה וצער גדול, ואעפ\"כ היתה הפדי' בשלום ובשלימות, ועד שזה נעשה הקדמה והכנה לתכלית השלימות שיהי' לע\"ל. שע\"י יפוצו מעינותיך חוצה שהותחל בעיקר בי\"ט כסלו<sup data-n=\"376\">50</sup>, ובפרט ע\"י העבודה של בעל הגאולה דיו\"ד כסלו שהפצת המעינות שלו היתה באופן של רחובות הנהר<sup data-n=\"377\">51</sup>, היינו שהמשיך את <i>המעיין</i> באופן של רחובות הנהר, הנה עי\"ז אתי מר דא מלכא משיחא<sup data-n=\"378\">52</sup>, שאז יהיו שלום ושלוה אמיתים בתכלית השלימות. וטועמי' חיים זכו<sup data-n=\"379\">53</sup>, שמתחילים לטעום מעין זה עוד בימי הגלות האחרונים, שיכולים להתעסק מתוך מנוחה ושמחה וטוב לבב בהעבודה דיפוצו מעינותיך חוצה באופן דמוסיף והולך ואור. ובקרוב ממש נזכה ללילה כיום יאיר<sup data-n=\"380\">54</sup>, בביאת משיח צדקנו.\n**********",[["326","*","יצא לאור ב<b>קונטרס ט'-יו\"ד כסלו – תשמ\"ט</b>, \"לקראת ט' כסלו, יום ההולדת דאדמו\"ר האמצעי (בשנת תקל\"ד) ויום ההילולא שלו (בשנת תקפ\"ח), ויו\"ד כסלו, יום הגאולה דאדמו\"ר האמצעי (בשנת תקפ\"ז) . . <i>ט' כסלו תשמ\"ט</i>\"."],["327","1","תהלים נה, יט."],["328","2","ח\"א (שער התפלה) מט, א ואילך."],["329","3","פי\"א (נה, ד ואילך)."],["330","4","וראה לקמן סעיף ב דאמיתית ענין פדה בשלום נפשי הוא למעלה יותר גם מהשלום שהי' בימי שלמה."],["331","5","כמ\"ש (דברי הימים-א כב, ט) שלמה יהי' שמו ושלום ושקט אתן על ישראל בימיו."],["332","6","שם – נו, א."],["333","7","פרש\"י לתהלים שם."],["334","8","בתחלתו – מט, א."],["335","9","גם מלחמה ע\"י חרב היא דוקא בקירוב מקום. דזהו החילוק שבין חרב לקשת. אבל אין זה כקירוב דהנאבקים. וראה לקמן סעיף ו."],["336","10","וישלח לב, כה."],["337","11","פי\"א – נו, א."],["338","12","כמפורש בהמשך תער\"ב שבהערה הבאה. ועפ\"ז יומתק הלשון דבעל הגאולה שם \"בדרך שלום . . כמו לע\"ל . . <i>וכה\"ג</i> הי' בימי שלמה\"."],["339","13","ד\"ה פדה בשלום תרע\"ה (המשך תער\"ב ח\"ב פ' שעד – ע' תשסט)."],["340","14","צפני' ג, ט. – הובא במאמר הנ\"ל שם."],["341","15","ישעי' יא, ו ואילך."],["342","16","ישעי' שם, ח. וראה פרש\"י שם. מצודות שם. ועוד."],["343","17","משלי טז, ז. ירושלמי תרומות פ\"ח סוף ה\"ג. ב\"ר רפנ\"ד. וראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316600603\" data-slug=\"or-hatorah-hb\" data-id=\"8316600603\">אוה\"ת נ\"ך עה\"פ (ס\"ע תרג</a> ואילך)."],["344","18","סנהדרין נט, ב."],["345","19","וכמובן גם מזה שבתחלה, אף שהי' \"שמש גדול\" היתה אפשרות לירידה עד לחטא עה\"ד, משא\"כ לע\"ל. וראה עד\"ז סה\"מ עטר\"ת ע' תטו."],["346","20","פ\"ה (נא, ד) ואילך."],["347","21","ראה בארוכה המשך פדה בשלום תרנ\"ט (סה\"מ תרנ\"ט ע' קסב ואילך) ותש\"ד (פי\"ט ואילך – סה\"מ ה'תש\"ד ע' 106 ואילך)."],["348","22","זהר הובא בלקו\"ת ר\"פ תצא. ובכ\"מ. וראה זהר ח\"א רמ, ב. ח\"ג רמג, א."],["349","23","להעיר גם מהמאמר דבעל הגאולה פי\"א (נו, א) \"ענין שלום . . וכמו\"כ ע\"י עסק התורה\"."],["350","24","להעיר מהידוע שכל העבודה והיגיעה דתפלה היא לבוא למדת האהבה (קונטרס העבודה בתחלתו. שם ספ\"ג)."],["351","25","ואתחנן ו, ה. ברכות נד, א במשנה. ספרי (הובא בפרש\"י) עה\"פ."],["352","26","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370136\" data-slug=\"torah-or\" data-id=\"3901370136\">תו\"א וישב כט, ב</a>. המשך תרס\"ו ס\"ע קלה ואילך. סה\"מ עת\"ר ע' כה. ה'תש\"י ע' 56. ובכ\"מ."],["353","27","דנוסף לזה שכללות ענין השכל (גם השכל דנה\"א) הוא בדרך שקו\"ט שנותן מקום גם לההיפך – מיתוסף בזה גם ירידת השכל דנה\"א בהשכל דנה\"ב, שעי\"ז ה\"מלחמה\" גדולה יותר."],["354","28","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380867\" data-slug=\"likkutei-torah\" data-id=\"4001380867\">יבמות קכב, א</a>. וש\"נ. לקו\"ת תצא לז, ג. מאמרי אדהאמ\"צ דברים ח\"ב ס\"ע תקמב ואילך. ובכ\"מ."],["355","29","המשך תרס\"ו ע' רסז. וראה גם <a class=\"ft-cite\" href=\"#/read/tanya/3401310023\" data-slug=\"tanya\" data-id=\"3401310023\">תניא ספי\"ח</a> \"שאי אפשר כלל\"."],["356","30","ראה ד\"ה ושבתי בשלום ה'תשל\"ח סי\"ב, ובהערה 97 שם (לעיל ריש ע' כו)."],["357","31","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380873\" data-slug=\"likkutei-torah\" data-id=\"4001380873\">לקו\"ת תצא לט, א</a>. דרמ\"צ קכג, ב. קנד, א. אוה\"ת תשא ע' א'תתסו. סה\"מ תרנ\"ו ע' שמב. ועוד."],["358","32","ולהעיר ממרז\"ל \"ובכל נפשך אפילו נוטל את נפשך\" (נסמן לעיל הערה 25)."],["359","33","פ\"ה ופ\"ו. ובהתאם לזה מבאר שם, שהאהבה דבכל לבבך ובכל נפשך היא בנר\"נ, והאהבה דבכל מאדך היא במקיפים חי' יחידה."],["360","34","ספ\"ו ואילך."],["361","35","דברי הימים-א כב, ח-י."],["362","36","שם כח, יט."],["363","37","שם כח, יא."],["364","38","להעיר גם שביהמ\"ק נקרא \"בית מנוחה\" (שם כח, ב)."],["365","39","שם כח, ג."],["366","40","שמואל-ב ז, א."],["367","41","תענית כב, סע\"א ואילך."],["368","42","המשך פדה בשלום תרנ\"ט (סה\"מ תרנ\"ט ע' קסב ואילך) ותש\"ד (פי\"ח. שם פי\"ט – סה\"מ ה'תש\"ד ע' 103. שם ע' 106)."],["369","43","זח\"ג קפח, ב."],["370","44","שבת לא, סע\"א."],["371","45","תו\"א ר\"פ וישב. ובכ\"מ."],["372","46","כמובן בפשטות. ומזה מובן שכ\"ה גם ברוחניות. וראה ד\"ה לא יצא האיש לאדמו\"ר מהר\"ש (קה\"ת, תשט\"ז) ע' 7 [סה\"מ תרל\"ב ח\"א ע' נז]. המשך פדה בשלום תרנ\"ט (סה\"מ שם ע' קנז) ותש\"ד (פט\"ו – סה\"מ שם ע' 98). ובכ\"מ."],["373","47","פי\"ב – נו, ג."],["374","48","ראה אוה\"ת (יהל אור) להצ\"צ עה\"פ ע' רח."],["375","49","ראה ד\"ה פדה בשלום ה'תשמ\"א ס\"ח, ובהנסמן שם הערה 47 (לקמן ע' מט)."],["376","50","ספר השיחות תורת שלום ס\"ע 112 ואילך."],["377","51","ראה \"התמים\" חוברת ב ע' עח [פו, ד]. לקוטי לוי\"צ – אגרות-קודש ע' שלד."],["378","52","ראה אגה\"ק דהבעש\"ט, נדפסה גם בכתר שם טוב (הוצאת קה\"ת) בתחלתו."],["379","53","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151295\" data-slug=\"likkutei-sichot\" data-id=\"1300151295\">לקו\"ש חט\"ו ע' 282</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201173\" data-slug=\"likkutei-sichot\" data-id=\"1300201173\">ח\"כ ע' 173</a>. וש\"נ."],["380","54","תהלים קלט, יב."]]],[1500370006,"<h3>בס\"ד. אור ליום ג', יו\"ד כסלו ה'תשמ\"א<sup data-n=\"381\">*</sup></h3>\n<b>פדה</b> בשלום נפשי מקרב לי כי ברבים היו עמדי<sup data-n=\"382\">1</sup>, ומבאר בעל הגאולה במאמרו ד\"ה זה (שנדפס בספרו שערי תשובה<sup data-n=\"383\">2</sup>)<sup data-n=\"384\">3</sup>, דפירוש פדה בשלום (בשלום דוקא) הוא שהפדי' היא באופן שהמנגד מתבטל לגמרי, שלכן אין צריך למלחמה כלל. וע\"ד שהי' בימי שלמה, שכל הגוים נתבטלו לגבי שלמה, שלא ע\"י מלחמה, שלכן נקרא בשם שלמה כי שלום הי' בימיו כו'<sup data-n=\"385\">4</sup>. אלא שהשלום שבימי שלמה לא הי' עדיין בשלימות<sup data-n=\"386\">5</sup>, ותכלית השלימות שבזה יהי' בימות המשיח שאז יתבטל הרע לגמרי (כמ\"ש<sup data-n=\"387\">6</sup> ואת רוח הטומאה אעביר מן הארץ), שלכן יהי' אז ונהרו אליו כל הגוים גו'<sup data-n=\"388\">7</sup> (ונהרו מעצמם), וכמו\"כ בנוגע לבע\"ח – לא ירעו ולא ישחיתו גו'<sup data-n=\"389\">8</sup> וארי' כבקר יאכל תבן<sup data-n=\"390\">9</sup>, ואולי י\"ל, דמזה שמביא בהמאמר הפסוק וארי' כבקר יאכל תבן, מובן, דבימות המשיח גופא, השלימות דפדה בשלום תהי' בתקופה השני' דוקא<sup data-n=\"391\">10</sup>. וכמבואר במק\"א<sup data-n=\"392\">11</sup> תיווך הדעות<sup data-n=\"393\">12</sup> בפירוש וגר זאב עם כבש וגו'<sup data-n=\"394\">13</sup>, שבתקופה הראשונה דימות המשיח יהי' זה בדרך \"משל וחידה\"<sup data-n=\"395\">14</sup>, והכוונה לאומות העולם, ובתקופה השני' יהי' זה כפשוטו (בנוגע לבע\"ח).ב) <b>וביאור</b> הענין (דהגם שענין הפדי' בשלום הי' גם בימי שלמה, מ\"מ, תכלית השלימות שבזה יהי' בימות המשיח, ובהם גופא בתקופה הב'), יובן מזה שמבאר בהמאמר<sup data-n=\"396\">15</sup>, דגם ע\"י עסק התורה (עכשיו) נעשה פדי' בשלום<sup data-n=\"397\">16</sup>, כי הבירור שע\"י עסק התורה הוא \"בחי' ביטול הרע בעצם\". וכמבואר בכמה דרושים<sup data-n=\"398\">17</sup> ההפרש בין תורה לתפלה, שהבירור דתפלה הוא בדרך מלחמה, שעת צלותא שעת קרבא<sup data-n=\"399\">18</sup>, והבירור דתורה הוא בדרך מנוחה. דהחילוק שבין בירור בדרך מלחמה לבירור בדרך מנוחה הוא שבבירור שבדרך מלחמה צריך המברר להתלבש בלבושי המתברר, משא\"כ בהבירור שבדרך מנוחה, המברר נשאר במקומו, וע\"י הגילוי אור (דהמברר) שמאיר על המתברר, הוא מתברר ממילא. וכמו שהי' בימי שלמה, דשלמה הי' במקומו, וע\"י גדולת שמו שנשמע גם במקומות הרחוקים, נמשכו אליו מעצמם, כמ\"ש<sup data-n=\"400\">19</sup> ומלכת שבא שומעת את שמע שלמה גו' ותבא ירושלמה גו'. דכמו\"כ הוא החילוק שבין הבירור דתפלה להבירור דתורה, שהבירור דתפלה הוא באופן שנפש האלקית מתלבשת בנפש הבהמית (וכידוע<sup data-n=\"401\">20</sup> שבכדי שההתבוננות דתפלה תפעול בירור נה\"ב, צריכה להיות ההתבוננות בענינים כאלו ובאופן שגם נה\"ב יכולה להשיג), משא\"כ הבירור דתורה הוא בדרך ממילא, דע\"י שלומדים בתורה שדבר זה מותר ודבר זה אסור, הם מתבררים ממילא.\nג) <b>והנה</b> בהבירור דתורה יש חילוק בין הבירור שע\"י גליא דתורה להבירור שע\"י פנימיות התורה<sup data-n=\"402\">21</sup>. דבהבירור שע\"י לימוד גליא דתורה צריך להיות הלימוד בענינים אלו שצריכים לבררם, ומהטעמים על זה שהתורה נתלבשה בדברים גשמיים וגם בדברים האסורים ועד לטענות של שקר<sup data-n=\"403\">22</sup>, הוא, בכדי לפעול הבירור גם בענינים אלו<sup data-n=\"404\">23</sup>. וזה שגם הבירור שע\"י גליא דתורה נק' בשם בירור בדרך מנוחה<sup data-n=\"405\">24</sup>הוא מפני שגם ענינים אלו (דברים האסורים וגם טענות של שקר) כמו שהם בתורה<sup data-n=\"406\">25</sup>, הם <i>תורה</i>, תורת אמת, ומכיון שגם דברים אלה שבתורה הם דבר ה'<sup data-n=\"407\">26</sup>, הלא כה דברי כאש<sup data-n=\"408\">27</sup> מה אש כו' אף דברי תורה אינן מקבלין טומאה<sup data-n=\"409\">28</sup>, הרי שהתורה היא תמיד במקומה ומדריגתה (דבר ה'), והבירור הוא בדרך ממילא. אלא שאעפ\"כ אין זה דומה להבירור שע\"י פנימיות התורה, דבהבירור שע\"י גליא דתורה הרי זה גופא שהתורה מדברת בנוגע לדברים גשמיים וכו', הרי זה ענין של ירידה<sup data-n=\"410\">29</sup> כביכול, אלא שגם לאחרי ירידתה והמשכתה למטה היא תורה, דבר ה' (ולא שיורדת ומתלבשת בענין אחר). משא\"כ הבירור שע\"י פנימיות התורה, מכיון שפנימיות התורה היא אילנא דחיי (שאינה מלובשת בטו\"ר)<sup data-n=\"411\">30</sup>, הרי הבירור שנעשה עי\"ז הוא שלא בדרך התלבשות כלל.\nד) <b>ואולי</b> יש להוסיף בהחילוק שבין גליא דתורה לפנימיות התורה, דאמיתית הענין דמנוחה ושלום הוא דוקא בפנימיות התורה, הוא לא רק בענין הבירורים שע\"י לימוד התורה, אלא גם בלימוד התורה גופא. דהלימוד בנגלה דתורה הוא באופן דקושיות ותירוצים, שבתחלה קס\"ד שהסברא היא כך וכך, ואח\"כ מגיעים להבנה עמוקה יותר ושוללים את הסברא הקודמת, ועד שאומרים עלי' בדותא היא<sup data-n=\"412\">31</sup>. דשלילת סברא הקודמת הו\"ע \"דם לרוב שפכת\" (שנאמר גבי דוד<sup data-n=\"413\">32</sup>) כמו שהוא בעולם השכל. ואמיתית ענין השלום הוא דוקא בפנימיות התורה, דלית תמן לא קושיא ולא מחלוקת<sup data-n=\"414\">33</sup>. ויש לומר, דחילוק זה שבין גליא דתורה לפנימיות התורה שבאופן הלימוד גופא, היא הסיבה להחילוק שביניהם בענין הבירור שעל ידם, דכל פועל פועל בדוגמתו, ולכן, דוקא פנימיות התורה, שבה עצמה לית תמן לא קושיא ולא מחלוקת, גם הבירור שעל ידה הוא בדרך שלום ומנוחה.\nה) <b>והנה</b> גם בפנימיות התורה גופא יש שני אופנים בכללות. כמו שנתלבשה בהבנת והשגת השכל, דבחינה זו שבפנימיות התורה ישנה גם עכשיו, וכמו שהיא בבחינת ראי' (למעלה מהבנה והשגה), שבחינה זו תהי' לע\"ל, כידוע<sup data-n=\"415\">34</sup> שמשיח ילמד (פנימיות) התורה לכל ישראל באופן דראי'. וההפרש שבין השגהלראי' הוא, דבהשגה, גם כשהיא בהתאמתות, אפשר שע\"י קושיא יהי' אצלו שינוי או חלישות עכ\"פ. משא\"כ בראי', גם כשיקשו לו קושיות הכי חזקות, לא יהי' אצלו שום ספק במה שראה. והטעם לזה הוא, כי כשאדם משיג בשכלו איזה דבר, הרי זהו דבר נוסף עליו, משא\"כ כשהוא רואה איזה דבר, הדבר נחקק בפנימיותו וכאילו שנעשה חלק מעצמותו ולכן אין שייך בזה שינוי.\nו) <b>וע\"פ</b> כל הנ\"ל יש לבאר, דהגם שענין פדה בשלום הי' גם בימי שלמה, מ\"מ, השלימות שבזה יהי' בימות המשיח, ובימות המשיח גופא בתקופה הב', דיש לומר, שג' דרגות אלו בשלום (בימי שלמה, בתקופה הא' דימות המשיח ובתקופה הב') הם דוגמת ג' הדרגות הנ\"ל שבתורה. והענין הוא, דזה שמלכת שבא שמעה את שמע שלמה הוא ע\"י ששמו (דשם הוא הארה) נמשך ונתפשט למרחקים עד לארץ שבא, ששלמה עצמו הי' במקומו והשם שלו (שמע שלמה) נמשך והגיע לשבא, וכל מה שההמשכה נמשכה למקום רחוק יותר היא מתקטנת יותר. ועד\"ז גם בנוגע להבירור גופא, דגם לאחרי שמלכת שבא שמעה את שמע שלמה, הוצרך להיות ותבוא ירושלמה<sup data-n=\"416\">35</sup> (שההליכה משבא לירושלים לוקח משך זמן וטרחא כו'), ורק אז נעשה הבירור (בדוגמת הבירור שע\"י גליא דתורה). משא\"כ הבירור שיהי' בימות המשיח, כיון שאז<sup data-n=\"417\">36</sup> יהי' הגילוי דאוא\"ס הבל\"ג שקודם הצמצום, דאור זה הוא בכל מקום בשוה<sup data-n=\"418\">37</sup>, לכן יהי' אז הבירור (לא באופן של המשכת וירידת האור למטה, והעלאת המתברר למעלה, כי אם) שהאור כמו שהוא יאיר בכל מקום, שלכן אז<sup data-n=\"419\">38</sup> אהפוך אל עמים (כמו שהם במציאותם ובמקומם) גו' כולם גו' לעבדו שכם אחד.\n<b>אלא</b> שבזה גופא יש חילוק בין תקופה ראשונה לתקופה השני'. דבתקופה הראשונה לא יהי' חידוש במע\"ב, הגילוי אלקות שיהי' בהעולם יהי' מצד גילוי אוא\"ס הבל\"ג שמאיר בכל מקום, אבל לא מצד העולם גופא, מכיון שעולם כמנהגו נוהג. ולכן יהי' אז הגילוי דהנבראים (והביטול שלהם) כמו דבר נוסף על מציאותם. [וע\"ד<sup data-n=\"420\">39</sup> ההבנה וההשגה דפנימיות התורה, שהיא כמו דבר נוסף על האדם, שלכן שייך בזה שינוי או חלישות עכ\"פ, כנ\"ל]. משא\"כ בתקופה השני' דימות המשיח שיהי' <i>שינוי וחידוש</i> במע\"ב, יש לומר, שהגילוי בעולם (והביטול בהנבראים) יהי' גם מצד טבע וגדר העולם גופא.ז) <b>והנה</b> ג' פירושים (ודרגות) הנ\"ל דפדה בשלום נפשי, כיון שכל הפירושים הם באותו הפסוק, הם שייכים זל\"ז<sup data-n=\"421\">40</sup>, ובאים בהמשך אחד. דנוסף על זה שכל הדרגות הם תורה [דכמו שבתפלה, גם התפלה דשבת, עם היות שהבירור דשבת הוא בדרך מנוחה<sup data-n=\"422\">41</sup>, מ\"מ, גם התפלה דשבת ענינה הוא <i>תפלה</i>, עד\"ז הוא גם בנוגע לתורה, שגם גליא דתורה שבבחי' התלבשות, ענינה הוא <i>תורה</i>], הנה כל הדרגות דתורה הם ענין אחד<sup data-n=\"423\">42</sup>, תורה אחת. שלכן, ע\"י לימוד התורה עכשיו (גם הלימוד דנגלה שבתורה) יזכו לתורתו של משיח דבחי' ראי', כידוע בענין ותלמודו<sup data-n=\"424\">43</sup> בידו<sup data-n=\"425\">44</sup>.\nח) <b>ואולי</b> יש לומר בעומק יותר, שגם הדרגא דפדי' שבדרך מלחמה, כיון שנקראת בשם פדי', היא שייכת לפדי' בשלום (עד לדרגא הכי נעלית שתהי' בימות המשיח בתקופה השני'). ובלשון חז\"ל<sup data-n=\"426\">45</sup> מלחמה נמי אתחלתא דגאולה היא, כיון<sup data-n=\"427\">46</sup> דשם גאולה עלה. ועפ\"ז יש לבאר יותר הקשר של הגאולה דיו\"ד כסלו וי\"ט כסלו עם הפסוק פדה בשלום נפשי<sup data-n=\"428\">47</sup>, דלכאורה, הרי ידוע מהלך הענינים בגאולת אדמו\"ר הזקן, ועד\"ז בגאולת אדמו\"ר האמצעי, שהיו ענינים של אתכפיא, השתדלות וכיו\"ב, היינו ענינים של מלחמה, ומקשרים זה עם הפסוק פדה בשלום נפשי שקאי (כמו שמבאר אדמו\"ר האמצעי בדרוש הנ\"ל) על פדי' בשלום כמו שהיא בתכלית השלימות. ויש לומר הביאור בזה, דכל הדרגות שבפדי' קשורות עם הפדי' בשלום בתכלית השלימות שתהי' לע\"ל. ויובן זה ע\"פ מה שמבאר בעל הגאולה בהמאמר<sup data-n=\"429\">48</sup> דענין פדה בשלום נפשי בעבודת האדם [שהפדי' דנפש האלקית מהגלות דנפש הבהמית היא באופן דשלום, שנה\"ב אינה מנגדת כלל] הוא כשהעבודה היא במס\"נ, ובמס\"נ גופא – מס\"נ דיחידה. דע\"י המס\"נ שמצד חי', נעשה רק אתכפיא נה\"ב, וע\"י המס\"נ שמצד יחידה דוקא, היא מתבטלת לגמרי. ועפ\"ז יובן הקשר דפדי' שבדרך מלחמה [העבודה שמצד חי', ולמטה יותר העבודה שמצד נר\"נ] לפדה בשלום נפשי (יחידה), כי בכל עבודה ועבודה יש בה (בהעלם) המס\"נ שמצד יחידה. וכדאיתא בתניא<sup data-n=\"430\">49</sup> דעסק התורה והמצוות והתפלה הוא ענין מס\"נ ממש. דכיון <i>שאמיתית</i> הענין דמס\"נ (מס\"נ <i>ממש</i>) הוא המס\"נ שמצד יחידה, הרי נמצא, שבכל ענין דתורה ומצוות[אפילו הענינים הפשוטים דתומ\"צ שאלמלא ניתנה תורה (ח\"ו) היו למדים אותם מבהמת הארץ<sup data-n=\"431\">50</sup>] יש כח המס\"נ דיחידה. ויתירה מזו, שגם ההבנה והשגה דתורה היא ע\"י הענין דהקדמת נעשה לנשמע כמ\"ש<sup data-n=\"432\">51</sup> תומת ישרים תנחם<sup data-n=\"433\">52</sup>, דענין הקדמת נעשה לנשמע הוא הביטול לבעל הרצון (שלמעלה מהביטול להרצון)<sup data-n=\"434\">53</sup>, דביטול זה בא מעצם הנשמה (שלמעלה מהגילויים דהנשמה), בחינת יחידה.\n<b>והגם</b> דענין המס\"נ המבואר במאמר הנ\"ל דבעל הגאולה הוא שנתבטלו כל רצונותיו (ועד שכל הענינים הם בהשתוות)<sup data-n=\"435\">54</sup>, יש לומר, שכל הדרגות דמס\"נ הם ענין אחד. וע\"ד הידוע<sup data-n=\"436\">55</sup> בענין היראה, דכיון שיראה היא ביטול (שלילת המציאות), לכן כל הדרגות שביראה הן יראה אחת, עד\"ז י\"ל בענין הביטול דמס\"נ. ואדרבא, כיון שהביטול דמס\"נ הוא מצד כללות ועצם הנפש, ודלא כהביטול דיראה שהיא רק מדה אחת, הרי ענין זה [שכל הדרגות הם ענין אחד] במס\"נ הוא עוד יותר מאשר ביראה. ויובן זה ע\"פ משל ממלכותא דארעא<sup data-n=\"437\">56</sup>, שכשאדם נכנס לצבא (אף שעדיין לא שירת בהצבא, ועאכו\"כ שלא הי' במלחמה) הוא מוסר את עצמו לגמרי און ווערט אויס בעה\"ב אויף זיך. דכמו\"כ הוא בצבא הרוחני, שישראל הם צבאות הוי'<sup data-n=\"438\">57</sup>, דזה שכל אחד מישראל יש לו קבלת עול [כפתגם הידוע<sup data-n=\"439\">58</sup> אַ איד איז אַ קבלת-עול'ניק], שבזה הוא נכנס לצבאות השם, הרי עי\"ז הוא מוסר את עצמו לגמרי לאלקות, ומסירה זו היא קשורה ומאיר בה המס\"נ שמצד יחידה בדרגא הכי נעלית.\nט) <b>וע\"פ</b> הנ\"ל יש לבאר גם הא דאיתא בירושלמי<sup data-n=\"440\">59</sup> עה\"פ פדה בשלום נפשי גו' כי ברבים היו עמדי, דקאי על אנשי אבשלום שהתפללו לשלומו של דוד. דלכאורה, הרי מבואר לעיל דפדי' בשלום הוא בתורה דוקא משא\"כ תפלה היא בדרך מלחמה, <i>ותפלתם</i> של אנשי אבשלום היתה בנוגע למלחמת אבשלום. ועד\"ז צריך להבין בהקשר של הגאולה די\"ט כסלו עם הפסוק פדה בשלום, הרי הגאולה דאדמו\"ר הזקן היתה (כפי שכותב באגה\"ק שלו<sup data-n=\"441\">60</sup>) כשקריתי בספר תהלים, דענינה של אמירת תהלים (אע\"פ שספר תהלים הוא מכ\"ד ספרים דתנ\"ך, תורה) הוא תפלה, ובלשון הכתוב<sup data-n=\"442\">61</sup> נעים <i>זמירות</i> ישראל (דזמירות שייכים לתפלה<sup data-n=\"443\">62</sup>), ובפרט ע\"פ הידועמסיפורי רבותינו נשיאינו שגאולת אדמו\"ר הזקן באה ע\"י התפלות דתלמידיו וחסידיו וכל ההולכים בעקבותיו, וגאולה זו שבאה ע\"י תפלה, שעת צלותא שעת קרבא, באה באמירת הפסוק פדה בשלום. ויש לומר הביאור בזה, דכיון שעסק התורה ומצוות הו\"ע מס\"נ ממש (כמובא לעיל מתניא), לכן, גם תפלה<sup data-n=\"444\">63</sup> קשורה עם פדה בשלום. ויש לומר, שאדרבה, ענין המס\"נ הוא בתפלה יותר מבתורה. כי זה שעסק התורה הוא מס\"נ ממש, הרי הרגש זה דמס\"נ צריך להיות \"קודם שיתחיל ללמוד\" [וכשלומד הרבה שעות רצופות יש לו להתבונן בזה בכל שעה ושעה]<sup data-n=\"445\">64</sup>, אבל בעת הלימוד, כשהוא עוסק בהבנת והשגת הענין שלומד, אינו מרגיש הביטול דמס\"נ. ואדרבא מאן מלכא רבנן<sup data-n=\"446\">65</sup> ואורייתא הוא דקא מרתחא לי'<sup data-n=\"447\">66</sup>, משא\"כ בתפלה, צריך להיות כעבדא קמי מרי'<sup data-n=\"448\">67</sup>, תכלית הביטול<sup data-n=\"449\">68</sup> (ביטול דמס\"נ).\nיו\"ד) <b>וע\"פ</b> כל הנ\"ל יובן זה שדוקא ע\"י העבודה עתה בהזמן דעקבתא דמשיחא כאשר החושך יכסה ארץ<sup data-n=\"450\">69</sup> באים להגילויים של הגאולה העתידה. כי דוקא בזמן זה, כשצריך להתעסק עם ניצוצי קדושה שנפלו למקום בלתי טהור, וצריך להפך מרירו למיתקא וחשוכא לנהורא, ועד שמזמן לזמן יוצאים מן הד' אמות של תורה, או מן הד' אמות של תפלה, לצאת מבית הכנסת ומבית המדרש, ובלשון השו\"ע הנהג בהם מנהג דרך ארץ<sup data-n=\"451\">70</sup>, מ\"מ ע\"י העבודה עכשיו דוקא מביאים את הגאולה העתידה, דאז יקויים מ\"ש<sup data-n=\"452\">71</sup> ואתם תלוקטו לאחד אחד, כאו\"א מישראל וכל ישראל, וכספם וזהבם אתם<sup data-n=\"453\">72</sup>, עם כל ניצוצות הקדושה השייכים להם וגם הנמצאים בכספם וזהבם כפשוטם. לפי שבעבודה זו בזמן הגלות ישנו ענין המס\"נ בתכלית. וכידוע תורת רבינו הזקן (ובארוכה במאמרי נשיא דורנו כ\"ק מו\"ח אדמו\"ר<sup data-n=\"454\">73</sup>) עה\"פ<sup data-n=\"455\">74</sup> והאיש משה עניו מאד מכל האדם אשר על פני האדמה, שהענוה דמשה (משה אמת ותורתו אמת<sup data-n=\"456\">75</sup>) היתה במיוחד בקשר לדרא דעקבתא דמשיחא, בראותו את המס\"נ שלהם בקיום התומ\"צ בענין אל יתבייש מפני המלעיגים<sup data-n=\"457\">76</sup> וכו' וכיו\"ב.<b>וזה</b> מביא לקיום היעוד ויספו ענוים בה' שמחה<sup data-n=\"458\">77</sup>, שמחת עולם על ראשם<sup data-n=\"459\">78</sup>, שמחת הגאולה האמיתית והשלימה, הבאה במיוחד ע\"י הפצת המעינות חוצה<sup data-n=\"460\">79</sup>, ובאופן של נגאלין מיד<sup data-n=\"461\">80</sup> ובאופן דפדה בשלום, בלי שום טירחא, עד שיקויים היעוד<sup data-n=\"462\">81</sup> והיו מלכים אומניך ושרותיהם מניקותיך, והביאו<sup data-n=\"463\">82</sup> את כל אחיכם גו' מנחה לה' גו' בכלי טהור גו', בקרוב ממש, בימי הגלות האחרונים<sup data-n=\"464\">83</sup>, ואח\"כ ומיד ובשלימות בפועל בגאולה האמיתית והשלימה ע\"י משיח צדקנו, במהרה בימינו ממש.\n**********",[["381","*","יצא לאור ב<b>קונטרס ט'-יו\"ד כסלו – תשמ\"ח</b>, \"לקראת ט' כסלו, יום ההולדת דאדמו\"ר האמצעי (בשנת תקל\"ד) ויום ההילולא שלו (בשנת תקפ\"ח)*, ויו\"ד כסלו יום הגאולה דאדמו\"ר האמצעי (בשנת תקפ\"ז)** . . <i>ערב ט' כסלו</i>,<i> שנת הקהל</i>,<i> שנת תשמ\"ח</i>\"."],["382","1","תהלים נה, יט."],["383","2","ח\"א (שער התפלה) מט, א ואילך."],["384","3","פי\"א. וראה שם נה, ד. נו, א."],["385","4","כמ\"ש (דברי הימים-א כב, ט) שלמה יהי' שמו ושלום ושקט אתן על ישראל בימיו."],["386","5","כמפורש בהמשך תער\"ב ח\"ב פשע\"ד (ע' תשסט). וראה גם שערי תשובה שם (נו, א) \"<i>וכה\"ג</i> הי' בימי שלמה\", שהשלום שהי' בימי שלמה הי' רק דוגמת השלום דלע\"ל."],["387","6","זכרי' יג, ב."],["388","7","ישעי' ב, ב."],["389","8","שם יא, ט."],["390","9","שם, ז."],["391","10","שהרי ההכרעה היא (וגם בחסידות –) שפי' כתובים אלה כפשוטם. אף שבדוחק קצת י\"ל שבמאמר זה לא נחית לחילוקי דעות אלה, כ\"א רק להכתוב בכלל."],["392","11","<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151430\" data-slug=\"likkutei-sichot\" data-id=\"1300151430\">לקו\"ש חט\"ו ע' 417</a>. \"סיום הרמב\"ם\" יו\"ד שבט תשמ\"ז (תורת מנחם – הדרנים על הרמב\"ם וש\"ס ע' קל). וש\"נ."],["393","12","דהרמב\"ם והראב\"ד – הל' מלכים רפי\"ב."],["394","13","ישעי' שם, ו."],["395","14","ל' הרמב\"ם שם.\n*) <i>ע\"ד הסתלקותו – ראה הקדמה לתורת חיים בראשית</i>. \"<i>בית רבי</i>\"<i> ח\"ב פרק ו</i>.<i> קובץ </i>\"<i>יגדיל תורה</i>\"<i> חוברת סח (תשרי-כסלו ה'תשמ\"ו) סי' יד</i>.\n<i>ביאור שייכות הסתלקותו לט' כסלו ה'תקפ\"ח</i>,<i> ואופנה – ראה לקוטי לוי\"צ אגרות-קודש ע' שכז</i>.<i> שם ע' שלט ואילך</i>.\n**) <i>ע\"ד גאולתו – ראה בארוכה </i>\"<i>התמים</i>\"<i> חוברת ב' ע' עז [פו</i>,<i> א]</i>.<i> שם ע' פא [פח</i>, <i>א] ואילך</i>.<i> מבוא לקונטרס </i>\"<i>בד קודש</i>\". \"<i>בית רבי</i>\"<i> ח\"ב פרקים ד-ה (נעתקו גם – בקיצור לשון קצת – בהוספה לקונטרס הנ\"ל ע' 20 ואילך)</i>."],["396","15","שם נו, א."],["397","16","להעיר מזח\"א (קנא, א. וראה לקוטי לוי\"צ שם, שיחת ש\"פ ויצא שנה זו (סה\"ש תשמ\"ח ח\"א ע' 8-127)), דע\"י עסק התורה תמשיך ירושלים בקיומה – די\"ל הכוונה בזה שאין צורך בעוד מה שהוא ובפרט מלחמה."],["398","17","ראה בארוכה המשך פדה בשלום תרנ\"ט (סה\"מ תרנ\"ט ע' קסב ואילך) ותש\"ד (פי\"ט ואילך – סה\"מ תש\"ד ע' 106 ואילך)."],["399","18","זוהר הובא בלקו\"ת ר\"פ תצא. ובכ\"מ. וראה זוהר ח\"א רמ, ב. ח\"ג רמג, א."],["400","19","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370025\" data-slug=\"torah-or\" data-id=\"3901370025\">מלכים-א יו\"ד, א</a>-ב. וראה תו\"א בראשית ו, ד. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380324\" data-slug=\"likkutei-torah\" data-id=\"4001380324\">לקו\"ת במדבר ד, א</a>."],["401","20","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370136\" data-slug=\"torah-or\" data-id=\"3901370136\">תו\"א וישב כט, ב</a>. המשך תרס\"ו ס\"ע קלה ואילך. סה\"מ תש\"י ע' 56. ובכ\"מ."],["402","21","המשך תרס\"ו ע' שו-ז. המשך תער\"ב ח\"ב פשע\"ז. סה\"מ עטר\"ת ע' קלז. ובכ\"מ."],["403","22","שהם למטה גם מדברים האסורים – כמובן מ<a class=\"ft-cite\" href=\"#/read/tanya/3401310029\" data-slug=\"tanya\" data-id=\"3401310029\">תניא פכ\"ד (ל, ב</a>)."],["404","23","ראה קונטרס עץ החיים פי\"א (ע' 38)."],["405","24","בהמשך תער\"ב שם כותב בזה בירור \"בדרך מלחמה\". ובדוגמת הארון שהי' מהלך במדבר והי' <i>הורג</i> נחשים שרפים ועקרבים, \"כמו שהמלך יוצא ממקומו והולך למדינת האויב להלחם בו\". דכמו\"כ הוא גם בהבירור ע\"י גליא דתורה ע\"י שהיא מתלבשת בענינים הגשמיים וכו', דאף שהבירור הוא לכאורה בדרך ממילא, הרי ההתלבשות כו' (הילוך במקום האויב) הו\"ע של מלחמה.\nאבל בהמשך פדה בשלום תרנ\"ט (ע' קסג) ותש\"ד (פ\"כ – ע' 108) שהבירור שע\"י גליא דתורה הוא \"בדרך מנוחה\", וזה בא בהמשך לענין הבירור בדרך מנוחה שמבואר שם לפנ\"ז (סה\"מ תרנ\"ט ע' קסב. תש\"ד ע' 107) שהי' בימי שלמה ושיהי' לע\"ל. וראה ד\"ה פדה בשלום שבשערי תשובה (פי\"א – נו, א): ע\"י עסק התורה . . <i>כמו לע\"ל</i> . . <i>וכה\"ג הי' בימי שלמה</i>."],["406","25","ראה לקוטי לוי\"צ (אגרות-קודש ע' רסו) דהא דר' אשי בדותא היא וכיו\"ב תורה הוא. – ולהעיר מהמבואר במק\"א (<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201354\" data-slug=\"likkutei-sichot\" data-id=\"1300201354\">לקו\"ש ח\"כ ע' 341</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1301410209\" data-slug=\"likkutei-sichot\" data-id=\"1301410209\">ח\"ל ע' 145</a>. ועוד) בענין \"יעקב ועשו <i>האמורים בפרשה</i>\" (פרש\"י ר\"פ תולדות)."],["407","26","זו הלכה – שבת קלח, ב."],["408","27","ירמי' כג, כט."],["409","28","ברכות כב, א."],["410","29","להעיר מ<a class=\"ft-cite\" href=\"#/read/tanya/3401310009\" data-slug=\"tanya\" data-id=\"3401310009\">תניא פ\"ד (ח, ב</a>) \"נסעה וירדה גו' עד שנתלבשה בדברים גשמיים כו'\". ולהעיר מהמשך תער\"ב ח\"ב ס\"ע א'מט \"ועם היות דהבירור (דשם מ\"ה) נעשה בדרך ממילא, מ\"מ זהו <i>שנמשך</i> בכדי שיהי' הבירור כו'\"."],["411","30","אגה\"ק סכ\"ו."],["412","31","פסחים יא, א. וש\"נ. וראה לעיל הערה 25."],["413","32","דברי הימים-א כב, ח."],["414","33","זח\"ג קכד, ב (ברע\"מ), הובא ונתבאר באגה\"ק שם."],["415","34","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380144\" data-slug=\"likkutei-torah\" data-id=\"4001380144\">לקו\"ת צו יז, א</a>-ב. שער האמונה פ\"ס. סד\"ה וידבר אלקים (השני) תרצ\"ט. ועוד."],["416","35","אבל קודם שבאה – לא הי' בה הביטול. ועד אשר \"לא האמנתי לדברים עד אשר באתי\" (מלכים-א יו\"ד, ז)."],["417","36","גם בתקופה הראשונה – ראה בארוכה ד\"ה והי' עקב ה'תשכ\"ז (לקמן ח\"ד ע' קצג) סעיף ז, שי\"ל שהחידוש דתקופה השני' הוא שאז יהי' גילוי אור חדש שלא האיר קודם הצמצום, אבל הגילוי דאוא\"ס שהאיר קודם הצמצום יהי' גם בתקופה הראשונה."],["418","37","ראה המשך תרס\"ו ע' כג. ובכ\"מ."],["419","38","צפני' ג, ט. רמב\"ם הל' מלכים ספי\"א – ומדבר שם בתקופה הראשונה (ראה שם ה\"ג)."],["420","39","אבל באופן נעלה יותר. כי גם בתקופה הראשונה, כיון שיהי' אז גילוי אוא\"ס הבל\"ג – יהי' גם ראי' באלקות [ראה בארוכה ד\"ה ונחה גו' ה'תשכ\"ה (לקמן ח\"ד ע' קצב ואילך) דענין ההשגה הוא מצד אור הקו, וענין הראי' הוא מצד אוא\"ס הבל\"ג דקודם הצמצום], אלא שכיון דוראו כל בשר אז יהי' ע\"י הגילוי דאוא\"ס ולא מצד הבשר – ה\"ז <i>דוגמת</i> ענין ההשגה שהיא בדרך הוספה וחידוש."],["421","40","ראה לקו\"ש ח\"ג ע' 782. ועוד."],["422","41","המשך פדה בשלום תרנ\"ט (ע' קסב-קסג) ותש\"ד (פי\"ט – ע' 107). ובכ\"מ."],["423","42","להעיר מהמשך תער\"ב ח\"ב פשס\"א ואילך."],["424","43","פסחים נ, א. וש\"נ."],["425","44","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380172\" data-slug=\"likkutei-torah\" data-id=\"4001380172\">לקו\"ת (תזריע כג, א</a>. ובכ\"מ) בפירוש מחז\"ל הנ\"ל, שע\"י הלימוד בעוה\"ז \"זוכה ללמוד ג\"כ בג\"ע כו'\". וע\"פ מ\"ש בתניא פל\"ז ש\"תכלית השלימות הזה של ימות המשיח ותחיית המתים כו' תלוי במעשינו ועבודתינו כל זמן משך הגלות כו'\" – יש לומר, שעד\"ז הוא גם בנוגע לתורתו של משיח, שההכנה לזה והכלי הוא לימוד פנימיות התורה במשך זמן הגלות."],["426","45","מגילה יז, ב."],["427","46","פרש\"י שם ד\"ה אתחלתא."],["428","47","ראה אגרת הקודש דאדה\"ז (נדפסה באג\"ק שלו סי' לח. וש\"נ) (וראה רד\"ה פדה בשלום ה'תשל\"ח (לקמן ע' קמב) ובהערה 4 שם. וש\"נ) – בנוגע לי\"ט כסלו. \"בית רבי\" ח\"ב ספ\"ה בהערה א – בנוגע ליו\"ד כסלו (וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300251160\" data-slug=\"likkutei-sichot\" data-id=\"1300251160\">לקו\"ש חכ\"ה</a> שיחה ליו\"ד כסלו – ע' 160 ואילך)."],["429","48","ספ\"ו ואילך (נב, ג ואילך)."],["430","49","פמ\"א (נח, א)."],["431","50","איוב לה, יא. עירובין ק, ב."],["432","51","משלי יא, ג."],["433","52","שבת פח, א."],["434","53","סה\"מ ה'תש\"ט ע' 148 ואילך. ובכ\"מ."],["435","54","ראה בארוכה ד\"ה פדה בשלום בשערי תשובה שם פ\"ח (נג, ג ואילך)."],["436","55","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370512\" data-slug=\"torah-or\" data-id=\"3901370512\">תו\"א קיד, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380840\" data-slug=\"likkutei-torah\" data-id=\"4001380840\">לקו\"ת ראה לא, א</a>. ביאורי הזהר לאדהאמ\"צ פא, א-ב. ביאורי הזהר להצ\"צ ע' תכג. קונטרס העבודה פ\"ג (ע' 18)."],["437","56","שהיא כעין מלכותא דרקיעא – ברכות נח, א."],["438","57","כמו שנקראו מעת יציאתם ממצרים – בא יב, מא."],["439","58","ראה סה\"מ תש\"ד ע' 5."],["440","59","סוטה פ\"א ה\"ח. וראה ג\"כ פרש\"י עה\"פ. פרש\"י ד\"ה כי ברבים – ברכות ח, רע\"א."],["441","60","נסמן לעיל הערה 47."],["442","61","שמואל-ב כג, א."],["443","62","ולהעיר ממש\"נ זמירות היו לי חקיך. ובתניא קו\"א ד\"ה זמירות קרית להו כו'. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380380\" data-slug=\"likkutei-torah\" data-id=\"4001380380\">לקו\"ת במדבר יח, א</a> ואילך. ועוד."],["444","63","משא\"כ תפלה מצ\"ע."],["445","64","<a class=\"ft-cite\" href=\"#/read/tanya/3401310046\" data-slug=\"tanya\" data-id=\"3401310046\">תניא פמ\"א (נח, ב</a>)."],["446","65","ראה גיטין סב, סע\"א. זח\"ג רנג, ב."],["447","66","תענית ד, רע\"א."],["448","67","שבת יו\"ד, א."],["449","68","משא\"כ בתורה, הרי אדרבה – לימוד התורה צ\"ל באופן ד\"כל עצמותי <i>תאמרנה</i>\" (ראה עירובין נד, א. <a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא פל\"ז – מז, א</a>)."],["450","69","ישעי' ס, ב."],["451","70","ברכות לה, ב. וראה שו\"ע או\"ח רסקנ\"ה."],["452","71","ישעי' כז, יב."],["453","72","שם ס, ט."],["454","73","סה\"מ קונטרסים ח\"א נג, ב ואילך. וראה ג\"כ סה\"מ עטר\"ת ע' תסד. ובכ\"מ."],["455","74","בהעלותך יב, ג."],["456","75","תנחומא קרח יא. וראה ב\"ב עד, א. וש\"נ."],["457","76","ראה טור ורמ\"א או\"ח בתחלתו. שו\"ע אדה\"ז או\"ח מהדו\"ב ס\"א ס\"ג. מהדו\"ק שם ס\"א."],["458","77","ישעי' כט, יט. וראה ד\"ה ויהיו חיי שרה גו' שנה זו – תשמ\"א (לעיל ח\"א ע' רפ ואילך)."],["459","78","שם לה, י. נא, יא."],["460","79","אגרת הבעש\"ט הידועה – נדפסה בכתר שם טוב בתחלתו. ובכ\"מ."],["461","80","רמב\"ם הל' תשובה פ\"ז ה\"ה."],["462","81","ישעי' מט, כג."],["463","82","שם סו, כ."],["464","83","ראה זבחים יט, רע\"א. אלא שבפשטות יהי' לע\"ל. ובשלימות."]]],[1500370007,"<h3>בס\"ד. ש\"פ ויצא, ט' כסלו, ערב יו\"ד כסלו, ה'תשמ\"ב<sup data-n=\"465\">*</sup></h3>\n<b>אתה</b> אחד<sup data-n=\"466\">1</sup> ושמך אחד ומי כעמך כישראל<sup data-n=\"467\">2</sup> גוי אחד בארץ כו', ומבאר כ\"ק אדמו\"ר האמצעי בעל ההילולא דט' כסלו (ובעל הגאולה דיו\"ד כסלו<sup data-n=\"468\">3</sup>) במאמרו ד\"ה זה<sup data-n=\"469\">4</sup> [שכנראה הוא הדרוש אתה אחד שאמרו בש\"ק האחרון בשבתו במאסר (ש\"פ ויצא, ט' כסלו, תקפ\"ז<sup data-n=\"470\">5</sup>) קודם תפלת המנחה<sup data-n=\"471\">6</sup>], שבכללות נוסח זה נתבארו ג' הקוין חג\"ת ד' פעמים, בד' המדריגות הכוללים כל סדר ההשתלשלות, מתחיל מלפני הצמצום. אתה אחד ושמך אחד ומי כעמך כישראל גוי אחד בארץ הם ג' הקוין חג\"ת כמו שהם לפני הצמצום, דגם לפני הצמצום יש ההתחלקות דג' קוין, באופן ששייך ענין ההתחלקות לפני הצמצום. תפארת גדולה ועטרת ישועה יום מנוחה וקדושה לעמך נתת הו\"ע ג' הקוין כמו שהם לאחרי הצמצום, אבל בעולמות הא\"ס שלמעלה מאצילות ואינם בבחינת הגבלה ממש (כבאצילות, שיש שם כלים המגבילים), ולכן אומר על זה לעמך נתת, דנתינה הוא שניתן מיד ליד בלי שינוי (בין קודם הצמצום ללאחר הצמצום). ולאחרי זה (אברהם יגל כו' מנוחת אהבה ונדבה כו') מדבר בהג' קוין כמו שהם באצילות, דבאצילות הם בבחינת הגבלה, עשר ולא תשע עשר ולא אחד עשר<sup data-n=\"472\">7</sup>. ובזה גופא יש ב' מדריגות, אברהם יגל יצחק ירנן יעקב ובניו ינוחו בו קאי על חג\"ת דאצילות, מנוחת אהבה ונדבה מנוחת אמת ואמונה מנוחת שלום השקט ובטח קאי על נה\"י דאצילות. וכמבואר בארוכה בדרוש הנ\"ל.\nב) <b>והנה</b> ע\"פ הידוע הדיוק בדרושי רבותינו נשיאינו, שכל הענינים שבהם, כולל גם זמן אמירתם, הם בדיוק, יש לקשר ד' מדריגות הנ\"ל עם הפסוק (שבפרשת ויצא<sup data-n=\"473\">8</sup>, דיש לומר שזהו מהטעמים על זה שמאמר זה נאמר בש\"פ ויצא<sup data-n=\"474\">9</sup>)והנה סולם מוצב ארצה וראשו מגיע השמימה, שקאי על הסולם דתפלה, סולם דא צלותא<sup data-n=\"475\">10</sup>, שבהסולם דתפלה יש ד' שליבות<sup data-n=\"476\">11</sup>. דיש לומר, שד' השליבות דתפלה הרי נוסף על הביאור שהם כנגד ד' העולמות אבי\"ע (כמבואר בכ\"מ<sup data-n=\"476\">11</sup>), הם בכללות כנגד ד' דרגות הנ\"ל, כללות סדר ההשתלשלות, מתחיל מלפני הצמצום<sup data-n=\"477\">12</sup>.\nג) <b>וממשיך</b> בהמאמר<sup data-n=\"478\">13</sup>, דמ\"ש מנוחה שלימה שאתה רוצה בה (לאחרי שמפרט ג' הקוין חג\"ת בכל ד' מדריגות הנ\"ל) הוא בחי' שלימותא דכולא, אחדות הפשוטה, שלמעלה מג' הקוין, גם ממקור הג' קוין כמו שהם לפני הצמצום. ועל זה אומר יכירו בניך וידעו, דבניך (נשמות שבגופים דוקא) יכירו וידעו גם בחינה זו. והטעם לזה הוא, כי מאתך היא מנוחתם, שמנוחתם (דשבת) היא מאתך, מאתך ממש.\n<b>ויש</b> לקשר זה עם הידוע<sup data-n=\"479\">14</sup> בפירוש כי מאתך היא מנוחתם, (מאתך הוא אותיות) מאת ך' שהיא הכתר, משם מנוחתם. דכמו שבהשתלשלות ד' העולמות אבי\"ע, התחלת ההשתלשלות היא מאצילות והכתר הוא למעלה מהשתלשלות, עד\"ז הוא בההשתלשלות דד' מדריגות הנ\"ל (שהם בדוגמת אבי\"ע), שהתחלת ההשתלשלות היא מ(בחינת חג\"ת ש)לפני הצמצום (בחינת אצילות דכללות), ובחינת הכתר (שם) היא בחינת הא\"ס עצמו (שלמעלה גם מחג\"ת שבא\"ס), מאתך ממש.\nד) <b>וביאור</b> הענין (שהמנוחה דשבת היא מאתך ממש)<sup data-n=\"480\">15</sup>, הנה המנוחה דשבת היא מצד עצם הנפש, בחינת יחידה. וכמו שמבאר בהמאמר<sup data-n=\"481\">16</sup>, דזהו הטעם על זה שהמנוחה דשבת היא בכל ישראל בשוה, ואין בה חילוק בין גדולי עולם לקטני ההמון ממש (ודלא כהתפלה דשבת, וכן אכילת שבת, שבצדיקים גדולים הם באופן נעלה הרבה יותר מאשר באנשים פשוטים), כי בבחינת היחידה כל ישראל הם בשוה, והיא נמצאת בשלימותה בכל נפש מישראל אפילו בפחותים וקלים.<b>וזהו</b> מאתך היא מנוחתם, שהמנוחה דשבת היא מאתך ממש, כי הגילוי דבחינת שלימותא דכולא שלמעלה מקוין בכל ד' מדריגות הנ\"ל (גם מהקוין כמו שהם לפני הצמצום, מאתך ממש), היא בבחינת יחידה דוקא. דהנה ד' הבחינות נרנ\"ח הם בד' העולמות אבי\"ע, ולמעלה יותר – בד' המדריגות דכללות ההשתלשלות (מתחיל מלפני הצמצום) – משא\"כ בחינת יחידה היא למעלה מהשתלשלות (שבאדם), ועד שהיא למעלה גם מבחינת המקיף דבית [דבכ\"מ<sup data-n=\"482\">17</sup> מבואר שבחינת חי' היא דוגמת מקיף דלבוש ובחינת יחידה דוגמת מקיף דבית. אבל בד\"ה אתה אחד הנ\"ל (וכ\"ה בכ\"מ), שבחינת יחידה היא למעלה גם מהמקיף דבית. שלכן, גם בבית (שהוא מקיף יותר מהמקיף דלבושים) לא ישכון בו בחינת יחידה, כ\"א בד' אמות הרחוקים בתכלית, יותר מהריחוק דבית, שם דוקא תשכון הארת בחינת יחידה<sup data-n=\"483\">18</sup>]. ולכן, בבחינת היחידה דוקא הוא גילוי בחינת הא\"ס (שלמעלה גם מחג\"ת שלפני הצמצום). וזהו כי מאתך היא מנוחתם, דמכיון שמנוחתם (דשבת) היא מצד בחינת יחידה, לכן היא מאתך, מאתך ממש.\nה) <b>ומבאר</b> בהמאמר שם<sup data-n=\"484\">19</sup>, דמה שתיקנו אנשי כנסת הגדולה לומר אתה אחד כו', הוא, דכנסת הגדולה היא כנסת ישראל, וכללות כל ההשתלשלות (בד' מדריגות הנ\"ל שנכללו בנוסח זה) נמסר לכנסת הגדולה (כנסת ישראל), ומכנסת הגדולה (כנס\"י) נמסר זה לכללות נש\"י, נשמות שבגופים, שגם הם יכולים לומר ולהמשיך כל בחינות אלו, מתחיל מבחינת אתה אחד שקאי (כנ\"ל) על בחינת החסד שלפני הצמצום, בחינת טבע הטוב להטיב שמצד חפץ חסד<sup data-n=\"485\">20</sup>. וזהו ועשיתם אתם<sup data-n=\"486\">21</sup>, א\"ת אותם אלא אתם כאילו עשאוני<sup data-n=\"487\">22</sup> בכפי' (כי פי' עשאוני בלה\"ק הוא ענין כפי' כמו גט מעושה<sup data-n=\"488\">23</sup>), היינו שאתם כופים אותי כביכול להקרא בשם חג\"ת אף בבחינת א\"ס שלפני הצמצום<sup data-n=\"489\">24</sup>. והכח על זה בנש\"י הוא לפי דשרש הנשמות הוא בא\"ס עצמו (שלמעלה גם מחג\"ת שבא\"ס)<sup data-n=\"489\">24</sup>, וגם לאחרי שנתלבשו בגופים מאירה בהם בחינת זו בבחינת היחידה שבהם (כנ\"ל), ולכן יש בכחם לעשות (ובאופן דכפי') כל ד' מדריגות הנ\"ל.\nו) <b>וע\"פ</b> כל הנ\"ל יובן מה שאמירת הדרוש ד\"ה אתה אחד היתה בש\"ק (פ' ויצא) קודם תפלת המנחה [אף שבדרך כלל, אמירת דא\"ח בהזמן דרעוא דרעויןהיא, כנראה ברבותינו נשיאינו, לאחרי תפלת המנחה<sup data-n=\"490\">25</sup>], כי אמירת אתה אחד כו' הוא לפעול המשכת ד' מדריגות הנ\"ל. ומכיון שכל הענינים נמשכים ע\"י תורה<sup data-n=\"491\">26</sup>, לכן, לפני אמירת אתה אחד בתפלת מנחה הייתה המשכת ענין זה בתורה. ומכיון שהמשכת ד' המדריגות שבנוסח אתה אחד הוא מצד שרש הנשמות בא\"ס שמתגלה בבחינת יחידה כנ\"ל, לכן, בתורה גופא, הייתה המשכת ענין זה כמו שהוא בפנימיות התורה, וכמו שפנימיות התורה היא באופן דיתפרנסון<sup data-n=\"492\">27</sup> [חסידות חב\"ד<sup data-n=\"493\">28</sup>], בחינת יחידה דתורה<sup data-n=\"494\">29</sup>.\nז) <b>ויש</b> לומר דזהו גם הקשר דאמירת דרוש זה לש\"ק האחרון של המאסר, ערב יום הגאולה, דהנה ידוע שע\"י המאסר נעשה (איז אויפגעטאָן געוואָרן) עילוי גדול יותר כו'. וע\"ד מאמר רז\"ל<sup data-n=\"495\">30</sup> הזית כשכותשין אותו (דוקא) הוא נותן שמנו<sup data-n=\"496\">31</sup>. והגם שהענין דיפוצו מעינותיך חוצה הי' גם לפני המאסר (דאדמו\"ר האמצעי), מ\"מ, ע\"י המאסר ניתוסף בזה, וי\"ל שעד להוספה באין ערוך, וכדיוק לשון רז\"ל שע\"י הכתישה הוא <i>נותן</i> שמנו (נותן דוקא)<sup data-n=\"497\">32</sup>, דכל הנותן בעין יפה הוא נותן<sup data-n=\"498\">33</sup>. וגודל העילוי שנתחדש ע\"י המאסר דוקא מובן מהמבואר בשיחת כ\"ק מו\"ח אדמו\"ר<sup data-n=\"499\">34</sup> (בנוגע להמאסר דאדמו\"ר הזקן, דמזה מובן גם בנוגע להמאסר דאדמו\"ר האמצעי), שהמאסר הי' בהסכמתו, כי כל צדיק וצדיק הוא מושל ושולט על כל הענינים הגשמיים שלו, וכל מאורע עמו הוא בהסכמתו. ומזה שהסכים על המאסר אף שזה הי' קשור עם יסורים וכו' ועם מניעת הפצת תורת החסידות (בעת שבתו במאסר), מובן מזה גודל העילוי דהפצת המעינות שנתחדש לאחרי גאולתו דוקא, עד שבשביל זה הי'כדאי כל המאסר. וזהו הקשר דאמירת דרוש זה ל(ערב יום) הגאולה<sup data-n=\"500\">35</sup>, כי אז נתחדש עילוי גדול יותר בגילוי פנימיות התורה [בחינת יחידה דתורה], גילוי בהבנה והשגה, ועד שהגילוי הוא לא רק בחו\"ב אלא גם בבחינת הדעת, דשרש הדעת הוא בפנימיות הכתר [וכמבואר בארוכה בהמשך עת\"ר<sup data-n=\"501\">36</sup> מעלת ענין הדעת], בחינת יחידה. דזהו יכירו בניך וידעו כי מאתך היא מנוחתם, דגילוי בחינת יחידה (מאתך היא מנוחתם) הוא בענין הדעת דוקא, יכירו כו' וידעו.\nח) <b>וזהו</b> ג\"כ מה שמשיח ילמד דעת לכל העם בהשגת פנימיות התורה<sup data-n=\"502\">37</sup>, דעת דוקא, דעיקר הענין שיתחדש בימות המשיח הוא [כמ\"ש הרמב\"ם בסיום וחותם ספרו] כי מלאה הארץ דעה את הוי'<sup data-n=\"503\">38</sup>, דעה דוקא. וגילוי זה יהי' באופן דכמים לים מכסים, היינו שזה יהי' (נוסף על דעת והכרת השכל, גם) בראי' מוחשית, כמו מי הים שנראים בראי' מוחשית. דהנה מבואר בכ\"מ<sup data-n=\"504\">39</sup> בענין הנבראים שבעלמא דאתכסיא שהם בדוגמת דגים שבים שהם בטלים להמים, עד שמציאותם של הדגים אינה נראית כלל ומה שנראה הם רק מי הים שמכסים עליהם<sup data-n=\"505\">40</sup>. ומזה מובן שפירוש כמים לים מכסים הוא שהגילוי דאלקות יהי' אז בראי' מוחשית, כמו מי הים (שמכסים על הנבראים שבתוכם) שהם נראים בראי' מוחשית.\n<b>ויהי</b> רצון שמלימוד ענינים אלו בתורה יבואו בקרוב לקיום היעוד (דענינים אלה) בפועל, שמתוך מנוחה אמיתית ומתוך שמחה וטוב לבב נלך לקראת הגאולה האמיתית והשלימה ע\"י משיח צדקנו, שאז יהי' מלאה הארץ דעה את הוי' כמים לים מכסים.\n**********",[["465","*","יצא לאור ב<b>קונטרס ט'-יו\"ד כסלו – תשמ\"ז</b>, \"לקראת ט' כסלו – יום ההולדת דאדמו\"ר האמצעי (בשנת תקל\"ד) ויום ההילולא שלו (בשנת תקפ\"ח), ויו\"ד כסלו יום הגאולה דאדמו\"ר האמצעי (בשנת תקפ\"ז) . . <i>ג' כסלו ה' </i><b>ת</b><i>הא </i><b>ז</b><i>ו </i><b>ש</b><i>נת </i><b>מ</b><i>שיח</i>\"."],["466","1","תפלת מנחה דשבת. וראה שער הכולל פכ\"ט אות ה."],["467","2","כ\"ה (\"כישראל\" בכ\"ף) בשמואל ב ז, כג (משא\"כ בדברי הימים א יז, כא). וכצ\"ל במנחת שבת – ראה שער הכולל שם אות ו, מפע\"ח שער השבת פכ\"ג. וראה לקוטי לוי\"צ לזח\"ג ס\"ע שכב ואילך."],["468","3","ראה לקמן סעיף ז ובהערה 35."],["469","4","נדפס בקונטרס בפ\"ע (קה\"ת, תשכ\"ה). מאמרי אדמו\"ר האמצעי – קונטרסים ע' ג. וראה ב\"פתח דבר\" להמאמר ובהערה שם (מאמרי אדמו\"ר האמצעי שם ע' יד)."],["470","5","\"התמים\" חוברת ב ע' פד [פט, ד]. מבוא לקונטרס \"בד קודש\" ע' 9."],["471","6","\"התמים\" שם ע' עז [פו, א]."],["472","7","ספר יצירה פ\"א מ\"ד."],["473","8","כח, יב."],["474","9","וכמו שדובר כמ\"פ, שהדרושים דרבותינו נשיאינו, גם אלה המתחילים בפסוק שלא מהפרשה, (חלק חשוב מהם, עכ\"פ) יש להם שייכות להפרשה שבה נאמרו.\nהשייכות דאתה אחד וכו' לפרשת ויצא (וגם להגאולה דיו\"ד כסלו – ראה לקמן סעיף ז ובהערה 35) ראה גם ד\"ה אתה אחד ה'תשל\"ב (נדפס לקמן ע' תמא ואילך), אבל המבואר שם הוא רק בהשייכות <i>דענין</i> אתה אחד כו'. משא\"כ במאמר זה מבואר גם השייכות <i>דדרוש זה</i> לפרשת ויצא (ולהגאולה).ולהעיר מהמבואר ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051141\" data-slug=\"likkutei-sichot\" data-id=\"1300051141\">לקו\"ש ח\"ה ע' 129</a> ואילך, <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300021080\" data-slug=\"likkutei-sichot\" data-id=\"1300021080\">דע\"פ</a> הידוע (מאמר הצ\"צ, הובא בבית רבי ח\"ב פ\"ו הערה ב – קב, ב. וראה גם הקדמה לתו\"ח) שההסתלקות דאדמו\"ר האמצעי היתה דוגמת ההסתלקות דהרשב\"י – יש לקשר ההסתלקות (וההילולא) שלו עם הפסוק \"עד הגל הזה\", שבפרשת ויצא, שרומז לל\"ג בעומר (סידור עם דא\"ח שער הל\"ג בעומר דש, ג ואילך).\nוב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300251159\" data-slug=\"likkutei-sichot\" data-id=\"1300251159\">לקו\"ש חכ\"ה ע' 159</a> ואילך, שגם הגאולה שלו מרומזת בפרשה זו (וראה לקמן הערה 35 שהבשורה דהגאולה היתה בש\"פ ויצא), בפסוק \"ושבתי בשלום אל בית אבי\", שי\"ל שרומז על ענין \"פדה בשלום נפשי\"."],["475","10","זהר ח\"א רסו, ריש ע\"ב. ח\"ג שו, ריש ע\"ב. וראה גם תקו\"ז תי' מה (פג, א)."],["476","11","מג\"ע אופן קצו (הובא ביל\"ר עה\"פ). של\"ה חלק תושב\"כ ריש פרשתנו (רצא, סע\"ב ואילך). <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380047\" data-slug=\"likkutei-torah\" data-id=\"4001380047\">לקו\"ת בשלח ב, ב</a>. ד\"ה ויחלום ה'תש\"ח ס\"א-ב (סה\"מ ה'תש\"ח ע' 80 ואילך). ובכ\"מ."],["477","12","ראה המשך ר\"ה תרצ\"ה בתחילתו (סה\"מ קונטרסים ח\"ב שיט, א) בענין סולם מוצב ארצה וראשו מגיע השמימה, \"דשמים הוא כתר, ובתוס' ה' השמימה הוא עתיק פנימיות הכתר\". ועפ\"ז יש לקשר גם ענין \"מנוחה שלימה כו'\" (ראה לקמן בפנים) להסולם דתפלה."],["478","13","ע' 4. שם ע' 8 ואילך (מאמרי אדמו\"ר האמצעי שם ע' ד-ה. ע' י ואילך)."],["479","14","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381205\" data-slug=\"likkutei-torah\" data-id=\"4001381205\">לקו\"ת שה\"ש יט, א</a>, מפע\"ח שער השבת פכ\"ג. שער הכוונות ענין מנחת שבת."],["480","15","בהבא להלן ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151140\" data-slug=\"likkutei-sichot\" data-id=\"1300151140\">לקו\"ש חט\"ו</a> שיחה א' לפ' ויצא סעיפים ג-ה (ע' 227 ואילך)."],["481","16","ס\"ע 8 ואילך (מאמרי אדמו\"ר האמצעי שם ע' י ואילך)."],["482","17","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380867\" data-slug=\"likkutei-torah\" data-id=\"4001380867\">לקו\"ת תצא לז, ג</a>-ד. ובכ\"מ. וראה גם המשך תרס\"ו ריש ע' רסז דחי' ויחידה הם מקיף הקרוב ומקיף הרחוק, וזה בא שם בהמשך להמבואר שם לפנ\"ז (ע' רנז) דלבוש ובית הם מקיף הקרוב והרחוק."],["483","18","כ\"ה (שיחידה שורה בד' אמות) גם באמ\"ב שער הק\"ש פמ\"ב-מג. שער הציצית פכ\"א (יג, סע\"ב). <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550453\" data-slug=\"torat-chaim\" data-id=\"2300550453\">תו\"ח שמות רנה, א</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550698\" data-slug=\"torat-chaim\" data-id=\"2300550698\">שם, סע\"ב</a> ואילך [בהוצאה החדשה – בשלח ח\"א קעט, סע\"א ואילך]. אבל באמ\"ב שער הק\"ש שם וב<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540966\" data-slug=\"torat-chaim\" data-id=\"2300540966\">תו\"ח שם (רנד, סע\"ב</a> ואילך), שד' אמות הוא דוגמת מקיף דבית."],["484","19","ע' 4. וראה שם ס\"ע 3 (מאמרי אדמו\"ר האמצעי שם ע' ד)."],["485","20","שם ע' 4 (מאמרי אדמו\"ר האמצעי שם ע' ה). וראה בהערה שם."],["486","21","בהר כה, יח."],["487","22","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380493\" data-slug=\"likkutei-torah\" data-id=\"4001380493\">זח\"ג קיג, א</a>. וראה הגהות הרח\"ו לזהר שם. לקו\"ת שלח מה, ב. ובכ\"מ."],["488","23","גיטין פח, ב."],["489","24","ד\"ה הנ\"ל ע' 6 (מאמרי אדמו\"ר האמצעי שם ע' ח)."],["490","25","וגם בשבת כ\"ק אדמו\"ר האמצעי במאסר, הרי המאמר דש\"פ וירא* הי' אחר תפלת מנחה (\"התמים\" שם ע' פד [פט, ד]. מבוא לקונטרס \"בד קדש\" שם)."],["491","26","ע\"ד אסתכל באורייתא וברא עלמא (זח\"ב קסא, א-ב). וראה ג\"כ ב\"ר בתחילתו."],["492","27","לשון התקו\"ז ת\"ו בסופו. וראה מקדש מלך בהקדמה לזהר. כסא מלך לתקו\"ז שם."],["493","28","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300071217\" data-slug=\"likkutei-sichot\" data-id=\"1300071217\">לקו\"ש ח\"ז ע' 206</a>; <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151024\" data-slug=\"likkutei-sichot\" data-id=\"1300151024\">חט\"ו ע' 24</a>, ובהערות שם."],["494","29","ראה \"קונטרס ענינה של תורת החסידות\" סעיף ו."],["495","30","שמו\"ר רפל\"ו."],["496","31","וע\"ד מ\"ש כ\"ק אדמו\"ר (מהורש\"ב) נ\"ע בנוגע למאסרו של כ\"ק אדמו\"ר הזקן: מה הזית הזה כשכותשין אותו הוא מוציא שמנו כו' כן ע\"י הקיטרוגי' שהיו בפ\"ב נתגלה הפנימי' דוקא (ספר השיחות תורת שלום ע' 26. וראה שם ס\"ע 112 ואילך שעיקר הענין דיפוצו מעינותיך חוצה הותחל אחרי המאסר והגאולה דפ\"ב)."],["497","32","בתו\"ש שם: <i>מוציא</i> שמנו (והוא ע\"פ מנחות נג, ב: מה זית זה אינו מוציא שמנו אלא ע\"י כתיתה כו'). אבל בשמו\"ר שם: נותנין."],["498","33","ראה ב\"ב נג, א. וש\"נ. רמב\"ם הל' מכירה פכ\"ה ה\"ד. הל' זכי' ומתנה פי\"א הכ\"ב (מהשיעורים דר\"ח כסלו, דשבוע דט' ויו\"ד כסלו שנה זו (תשמ\"ז) – לפי החלוקה דג\"פ ליום)."],["499","34","שיחת ליל ב' כ' כסלו תרצ\"ג ס\"ז ואילך (לקו\"ד כרך א לז, סע\"ב ואילך).\n*) <i>ב</i>\"<i>התמים</i>\"<i> ובמבוא לקונטרס הנ\"ל שם</i>:<i> וכן הי' כל השלשה שבועות </i>. .<i> חיי</i>,<i> תולדות ויצא</i>.<i> אבל בנוגע להמאמר דש\"פ ויצא מפורש שם (</i>\"<i>התמים</i>\"<i> שם ע' עז (פו</i>,<i> א)) שהי' </i><b>קודם</b><i> תפלת מנחה</i>.<i> ועכצ\"ל שהכוונה ב</i>\"<i>וכן הי' כל השלשה שבועות</i>\"<i> היא </i><b>לכללות</b><i> השייכות למנחה</i>.<i> וצריך בירור בנוגע לש\"פ חיי וש\"פ תולדות</i>."],["500","35","ובפרט לפי הידוע* ש\"הבשורה מהגאולה באה בשבת ט' כסלו לעת המנחה בעת שאמר כ\"ק אדמו\"ר האמצעי דא\"ח ד\"ה אתה אחד\"."],["501","36","ס\"ע קיב ואילך."],["502","37","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380144\" data-slug=\"likkutei-torah\" data-id=\"4001380144\">לקו\"ת צו יז, א</a>. וראה גם מאמרי אדה\"ז פרשיות התורה ח\"א ע' רסא. שער האמונה פנ\"ו."],["503","38","ישעי' יא, ט."],["504","39","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370279\" data-slug=\"torah-or\" data-id=\"3901370279\">תו\"א בשלח סב, סע\"ב</a>. ד\"ה בוקע ים לפני משה לכ\"ק אדמו\"ר האמצעי (נדפס בקונטרס בפ\"ע – קה\"ת, ה'תשכ\"ז, ובמאמרי אדמו\"ר האמצעי ויקרא ח\"א ע' שסז ואילך. וראה בהנסמן שם ע' שסט)."],["505","40","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300271042\" data-slug=\"likkutei-sichot\" data-id=\"1300271042\">לקו\"ש חכ\"ז</a> \"הדרן על ספר משנה תורה להרמב\"ם\" תשמ\"ה ס\"ז (ע' 42-241. תורת מנחם – הדרנים על הרמב\"ם וש\"ס ס\"ע פז ואילך).\n*) \"<i>מסורת בבית הרב</i>\"<i> – הובא בהוספה לקונטרס </i>\"<i>בד קודש</i>\"<i> ע' 22 בהערה</i>."]]],[1500370008,"<h3>בס\"ד. ש\"פ ויצא, יו\"ד כסלו ה'תשמ\"ו<sup data-n=\"506\">*</sup></h3>\n<b>פדה</b> בשלום נפשי מקרב לי כי ברבים היו עמדי<sup data-n=\"507\">1</sup>, וידוע, דנוסף לפשטות הענין שפסוק זה אמר דוד בנוגע להפדי' שלו, שהקב\"ה פדה אותו מהמלחמות שבאו עליו<sup data-n=\"508\">2</sup>, מרומז בפסוק זה גם הפדי' של כמה צדיקים<sup data-n=\"509\">3</sup>, ומכ\"ש הפדי' של צדיקים שאמרו פסוק זה בעת שנפדו. ולהעיר<sup data-n=\"510\">4</sup>, שבכל ג' הגאולות דרבותינו נשיאינו – גאולת אדמו\"ר הזקן בי\"ט כסלו, גאולת אדמו\"ר האמצעי ביו\"ד כסלו, וגאולת כ\"ק מו\"ח אדמו\"ר בי\"ב תמוז – אמרו בעלי הגאולה פסוק זה ביום שנגאלו. בנוגע לגאולת אדמו\"ר הזקן בי\"ט כסלו ידוע מ\"ש אדמו\"ר הזקן באגרת הקודש שלו<sup data-n=\"511\">5</sup>, כשקריתי בס' תהלים בפסוק פדה בשלום נפשי כו' יצאתי בשלום מה' שלום. בנוגע לגאולת אדמו\"ר האמצעי ביו\"ד כסלו, ידוע<sup data-n=\"512\">6</sup> שרבותינו נשיאינו היו אומרים שיעור תהלים כמו שנחלק לימי החודש, וכיון שהפסוק פדה בשלום נפשי הוא בשיעור תהלים החדשי דיום העשירי לחודש, הרי שביום גאולתו (עשירי בכסלו) אמר פסוק זה. ובנוגע לגאולת כ\"ק מו\"ח אדמו\"ר בי\"ב תמוז, ידוע<sup data-n=\"512\">6</sup> מנהג רבותינו נשיאינו שבזמנים ובמצבים מיוחדים היו מוסיפים לומר השיעור תהלים כמו שנחלק לימי השבוע (נוסף על שיעור תהלים החדשי), וכיון שהקביעות די\"ב תמוז בשנת תרפ\"ז (שנת המאסר והגאולה) היתה ביום השלישי בשבוע והפסוק פדה בשלום נפשי הוא בשיעור תהלים השבועי דיום השלישי בשבוע, מובן, שבעל הגאולה די\"ב תמוז אמר פסוק זה ביום גאולתו.\n<b>ומבואר</b> במק\"א<sup data-n=\"513\">7</sup>, שהשייכות דגאולת יו\"ד כסלו לפסוק פדה בשלום נפשי היא (בענין אחד) עוד יותר מהשייכות דגאולת י\"ט כסלו וי\"ב תמוז לפסוק זה, דכיון שפסוק זה הוא בשיעור תהלים דיום העשירי לחודש, הרי השייכות דפסוק זה ל[הגאולה ד]יו\"ד כסלו היא מודגשת בכל שנה ושנה<sup data-n=\"514\">8</sup>.ב) <b>והנה</b> ידוע הביאור דבעל הגאולה במאמרו ד\"ה זה (שנדפס בספרו שערי תשובה<sup data-n=\"515\">9</sup>), שההדגשה בהכתוב פדה בשלום נפשי היא (נוסף על ענין הפדי', גם) באופן הפדי', שהפדי' היא בשלום בלא מלחמה כלל וכלל<sup data-n=\"516\">10</sup>. ומבאר שם<sup data-n=\"517\">11</sup>, שאמיתית ענין השלום הוא שאין לו מנגד כלל. וע\"ד שהי' בימי שלמה, שכל הגוים היו בטלים אליו. ולכאורה הכוונה, דכל זמן שיש לו מנגדים, גם כשבפועל אינם לוחמים עמו (מפני שנפל עליהם אימתו ופחדו<sup data-n=\"518\">12</sup> וכיו\"ב), אין זה אמיתית ענין השלום<sup data-n=\"519\">13</sup>. כי כשישנם מנגדים יש אפשרות ונתינת מקום למלחמה, ואמיתית ענין השלום הוא (לא רק שבפועל לא ישנה מלחמה, אלא) שאין (גם) אפשרות ונתינת מקום למלחמה.\n<b>וזהו</b> שענין השלום הי' בימי שלמה דוקא, שלכן נקרא בשם שלמה כי שלום הי' בימיו<sup data-n=\"520\">14</sup>, כי כל הגוים <i>נתבטלו</i> לגבי שלמה (מצד עוצם גדולתו), וכשהמנגד מתבטל (שאז אין נתינת מקום שילחום), אז הוא אמיתית ענין השלום. וזהו שאמר הקב\"ה לדוד המלך (כשרצה לבנות בית המקדש) לא תבנה בית לשמי כי איש מלחמות אתה<sup data-n=\"521\">15</sup>, הגם שאז (כשרצה דוד לבנות ביהמ\"ק) הי' במצב של מנוחה, וה' הניח לו מסביב מכל אויביו<sup data-n=\"522\">16</sup>, כי המנוחה דדוד באה ע\"י שנצח כל המלחמות, ולא שאויביו נתבטלו<sup data-n=\"523\">17</sup>. וכיון שבימיו נשארו עדיין מנגדים (ויש נתינת מקום שילחמו), אין זה אמיתית הענין דמנוחה ושלום. וזהו פדה בשלום נפשי, דענין הפדי' בשלום הוא שהמנגד מתבטל, כמו שהי' בימי שלמה.\n<b>וממשיך</b> בהמאמר<sup data-n=\"524\">18</sup>, שאמיתית הענין דפדה בשלום נפשי הוא, שאלו שהיו מקודם שונאים ומנגדים הם נעשים אוהבים. דענין זה הוא למעלה גם מהשלום שהי' בימי שלמה<sup data-n=\"525\">19</sup>, שהשלום שהי' בימי שלמה הוא שכולם נתבטלו מצד הגילויאור (אבל לא נהפכו לקדושה)<sup data-n=\"526\">20</sup>, ואמיתית ענין השלום (שגם המנגד נהפך לקדושה) יהי' לעתיד לבוא, כמ\"ש<sup data-n=\"527\">21</sup> אז אהפוך אל עמים שפה ברורה גו' לעבדו שכם אחד. ומה שאמר <i>דוד</i> פדה <i>בשלום</i> נפשי [הגם שבימיו לא נתבטלו המנגדים ומכ\"ש שלא נהפכו לקדושה, דענין זה לא הי' אפילו בימי שלמה ויהי' רק לע\"ל], מבואר בהמאמר דבעל הגאולה<sup data-n=\"528\">22</sup>, שזה קאי על נפש דוד כמו שיהי' לע\"ל.\n<b>וע\"פ</b> הידוע<sup data-n=\"529\">23</sup> בפירוש מאמר רז\"ל<sup data-n=\"530\">24</sup> נפרעין מן האדם מדעתו ושלא מדעתו (ועד\"ז בפירוש לשון המשנה<sup data-n=\"531\">25</sup> דין וחשבון), דכאשר אדם אומר פסק דינו של אדם אחר הוא פוסק בזה גם על עצמו, הרי פסק דינו של אדמו\"ר האמצעי במאמרו ד\"ה פדה בשלום נפשי, דפירוש פדה בשלום נפשי הוא שהמנגד מתבטל (כהשלום שהי' בימי שלמה), ויתירה מזו, שהמנגד נהפך לאוהב (כהשלום שיהי' לע\"ל), הוא פס\"ד גם בנוגע לענין פדה בשלום נפשי שבהגאולה שלו – גאולה דיו\"ד כסלו, [ומזה מובן גם בנוגע לענין פדה בשלום נפשי שבהגאולה די\"ט כסלו ובהגאולה די\"ב תמוז], דענין השלום שבגאולות אלו הוא שהמנגד מתבטל, ויתירה מזו, שהוא נהפך לאוהב.\nג) <b>והנה</b> פירוש הכתוב פדה בשלום נפשי בפשטות הוא, שדוד אמר זה על הפדי' שלו כמו שהוא בעולם הזה, שפדי' <i>זו</i> היא בשלום. וצריך להבין הקשר והשייכות דהפירוש שבהמאמר דזה שאמר דוד פדה בשלום נפשי קאי על נפש דוד כמו שיהי' לע\"ל, עם הפירוש הפשוט שפדיית דוד עכשיו היתה פדי' בשלום. ויש לומר הביאור בזה, ע\"פ מ\"ש הרמב\"ם<sup data-n=\"532\">26</sup> דבפרשת בלעם מדבר בשני המשיחים, במשיח הראשון שהוא דוד ובמשיח האחרון שעומד מבניו. ויש לומר, דהטעם על זה שדוד נקרא בשם משיח הראשון הוא, לפי שכל הענינים שיהיו ע\"י מלך המשיח (משיח האחרון), התחלתם היתה ע\"י דוד, משיח הראשון. אלא שהגמר והשלימות שלהם יהי' ע\"י משיח האחרון שעומד מבניו של דוד. ועפ\"ז יש לבאר הקשר דשני הפירושים בפסוק פדה בשלום נפשי, שבפנימיות, גם הפדי' דדוד עכשיו היתה פדי' בשלום. היינו <i>שנתבטלו</i> המנגדים (ולא רק שלא לחמו עמו) ויתירה מזו שנהפכו לאוהבים. אלא שבדוד הי' זה בפנימיות ובהעלם, ולע\"ל תתגלה הפנימיות דפדיית נפש של דוד, שהיא פדי' בשלום.\n<b>ועפ\"ז</b> יובן עוד יותר גודל העילוי דהגאולה דיו\"ד כסלו, דמזה שאומרים עלי' שהיא פדי' בשלום (בלי הוספת הסברה שהיא הכנה לפדה בשלום דלע\"ל, וכיו\"ב), מוכח, דענין השלום שבה [שהמנגד מתבטל, ויתירה מזו שנהפך לאוהב] הוא (גם) בגילוי.ד) <b>והנה</b> ידוע<sup data-n=\"533\">27</sup> דשבת ויום טוב צריכים הכנה ביום שלפניהם – ערב שבת וערב יום טוב. ובנוגע לעניננו, חג הגאולה יו\"ד כסלו – הערב דיו\"ד כסלו [שבו הוא ההכנה ליו\"ד כסלו] הוא יום התשיעי בכסלו, יום ההולדת ויום ההילולא דבעל הגאולה. והגם שהגאולה דיו\"ד כסלו היתה בשנת תקפ\"ז<sup data-n=\"534\">28</sup>, שנה לפני ההסתלקות, מ\"מ, כיון שמגלגלין זכות ליום זכאי<sup data-n=\"535\">29</sup>, יש לומר, דזה שיום התשיעי בכסלו זכה להיות יום ההילולא של אדמו\"ר האמצעי הוא לפי שגם לפני זה הי' שייך לזה<sup data-n=\"536\">30</sup>. ועפ\"ז יש לומר, שגודל העילוי דיום הגאולה [יו\"ד כסלו], שענין פדה בשלום נפשי שבו הוא ע\"ד הענין דפדה בשלום נפשי שיהי' לע\"ל, הוא לפי שה\"ערב\" שלו הוא יום ההילולא דבעל הגאולה.\nה) <b>ויובן</b> זה בהקדים מ\"ש בעל הגאולה במאמרו ד\"ה להבין ענין הילולא דרשב\"י<sup data-n=\"537\">31</sup>, דזה שיום הסתלקות הרשב\"י נקרא בשם הילולא, הוא, לפי שע\"י רשב\"י הי' הגילוי דפנימיות התורה. ומבאר זה בהקדים מארז\"ל<sup data-n=\"538\">32</sup> האי עלמא דאזלינן מיני' כבי הילולא דמיא, שע\"י ירידת הנשמות למטה בעוה\"ז, האי עלמא, נעשה בהם הענין דאזלינן, מהלכים. דהנשמות כמו שהן למעלה נק' עומדים כמ\"ש<sup data-n=\"539\">33</sup> חי הוי' אלקי ישראל אשר עמדתי לפניו, ובזהר איתא<sup data-n=\"540\">34</sup> כל נשמתא ונשמתא הוה<i> קיימא</i> בדיוקנאה קמי מלכא קדישא. דהגם שהנשמות כמו שהן למעלה הן תמיד ברצוא ושוב, דעי\"ז הם עולים בעילוי אחר עילוי, מ\"מ, כיון שכל העליות שלהם הם בהגבלה, דגם המדרגות הכי גבוהות (שבהם היא עליית הנשמות) הם ע\"פ מאמר קו המדה<sup data-n=\"541\">35</sup>, לכן נק' בשם עומדים. וע\"י ירידת הנשמות למטה הם נעשים מהלכים, שהעלי' דהנשמות בירידתם למטה היא בבחינת א\"ס ובל\"ג. וזהו האי עלמא דאזלינן מיני', דהנשמות כמו שהם מצד עצמם הם עומדים, וע\"י ירידתם בהאי עלמא, נעשים מהלכים, אזלינן.\n<b>והטעם</b> על זה שדוקא ע\"י האי עלמא נעשה הענין דאזלינן, הוא, כי האי עלמא כבי הילולא דמיא. והענין הוא<sup data-n=\"542\">36</sup>, דנשמה וגוף הם דוגמת איש ואשה<sup data-n=\"543\">37</sup>. וכמו שבאיש ואשה כפשוטם, בכדי שיהי' היחוד דדכר ונוקבא (שהם שני הפכים)הוא ע\"י שנמשך בהם כח הא\"ס שלמעלה משניהם<sup data-n=\"544\">38</sup>, וכח זה שנמשך בהם מתגלה בענין ההולדה [דענין להוליד דור אחר דור עד אין שיעור הוא לא מצד גדר הנבראים שהם בעלי גבול, אלא מצד כח הא\"ס<sup data-n=\"545\">39</sup> שלמעלה מגדר הנבראים<sup data-n=\"546\">40</sup> שנמשך ע\"י נישואין], עד\"ז הוא בנשמה וגוף שהם דוגמת איש ואשה, שבכדי שיוכל להיות החיבור והיחוד דנשמה וגוף שהם שני הפכים הוא ע\"י המשכת כח הא\"ס. והמשכת כח זה מתגלה בענין ההולדה, תולדותיהם של צדיקים מעשים טובים<sup data-n=\"547\">41</sup>, שהעלי' שע\"י התומ\"צ היא עלי' בבחי' א\"ס ובל\"ג. וזהו האי עלמא דאזלינן מיני' כבי הילולא דמיא, דהטעם על זה שדוקא מיני' (האי עלמא) נעשה אזלינן (מהלכים), הוא, כי האי עלמא כבי הילולא דמיא, שהחיבור והיחוד דנשמה הרוחנית עם הגוף הגשמי (האי עלמא) הוא בדוגמת יחוד חתן וכלה (הילולא, חתונה), שעי\"ז נמשך כח הא\"ס.\nו) <b>והנה</b> ידוע, דכמו שירידת הנשמה למטה היא ירידה לצורך עלי', עד\"ז הוא בתומ\"צ, שהכוונה בהירידה דתומ\"צ היא לצורך עלי'. כי ע\"י ירידתם למטה והתלבשותם בדברים גשמיים נמשך בהם עצמיות כח התומ\"צ<sup data-n=\"548\">42</sup>. ועפ\"ז יש לומר, דענין ההילולא שבקיום התומ\"צ בהאי עלמא דוקא, הוא גם בהתומ\"צ עצמם. דנוסף לענין ההילולא בהאדם העוסק בתומ\"צ, המשכת כח הא\"ס שע\"י החיבור והיחוד דנשמה וגוף (כנ\"ל סעיף ה), גם בהתומ\"צ עצמם הו\"ע ההילולא. כי תורה ומצוות הם חכמתו ורצונו של הקב\"ה שלמעלה מעולם<sup data-n=\"549\">43</sup>, והחיבור שלהם עם הענינים שבהאי עלמא (הדברים הגשמיים שבהם נתלבשו התומ\"צ) הוא חיבור דשני הפכים, וחיבור זה הוא ע\"י המשכת עצמות כח התומ\"צ – ע\"ד יחוד חתן וכלה, ע\"י המשכת כח הא\"ס שלמעלה משניהם ומחבר אותם.\nז) <b>וממשיך</b> בהמאמר<sup data-n=\"550\">44</sup> עוד פירוש בהאי עלמא דאזלינן מיני', שבשעת פטירתו של אדם, כשהנשמה נפטרת מהגוף ומעולם הזה, דאזלינן מיני', אזי נעשה בה הענין דאזלינן, שהיא נעשית בבחינת מהלך. דלהביאור דלעיל (סעיף ה), זה שהנשמה נעשית מהלך, הוא בהיותה למטה בהאי עלמא. ופירוש דאזלינן מיני' הוא מחמתו ובסיבתו<sup data-n=\"551\">45</sup>, דזה שהנשמה באה לבחינת אזלינן, שהיא נעשית מהלך, הוא מיני', מצד העילוי שבהאי עלמא שהוא כמו הילולא. ולפירוש השני, הענין דאזלינן שנעשה בהנשמה (שנעשית מהלך) הוא בעת דאזלינן מיני', כשהיא הולכת ונפטרת מהאי עלמא. ונקודת הביאור בזה (בהמאמר)<sup data-n=\"552\">46</sup>, דהמצוות כמו שהם למטה, הםבמדידה והגבלה<sup data-n=\"553\">47</sup>. וגם התורה שלמטה היא במדידה והגבלה, כמ\"ש<sup data-n=\"554\">48</sup> ארוכה מארץ מדה, היינו שיש מדה להתורה אלא שהמדה היא ארוכה מארץ<sup data-n=\"555\">49</sup>. ולכן, ההילוך (ענין הבל\"ג) שנעשה בהנשמה ע\"י עסק התומ\"צ שלה בעוה\"ז, הוא בהעלם. וגם ההילוך דהנשמה שע\"י מצות פרי' ורבי', אף שבענין ההולדה הוא גילוי כח הא\"ס, מ\"מ, כיון שגילוי כח הא\"ס שבזה הוא בנוגע לענין מוגבל (הולדת בנים, אלא שההולדה היא דור אחר דור עד אין שיעור), לכן, גם ע\"י קיום מצוה זו, ענין ההילוך הוא בהעלם. ולאחרי שהנשמה ממלאת את שליחותה בהאי עלמא ובא הזמן דאזלינן מיני', שהיא הולכת (ויוצאת) מההגבלות דהאי עלמא, אזי מתגלה לה הפנימיות דהתומ\"צ שעסקה בעוה\"ז, שהפנימיות דהתומ\"צ הם בלי גבול, ואז נעשה בה הענין דאזלינן (מהלך) גם בגילוי. וזהו שיום הסתלקות הצדיקים שעסקו בפנימיות התורה נק' בשם יום הילולא (כמו הילולא דרשב\"י, ועד\"ז הוא בנוגע ליום ההסתלקות דכל הצדיקים שעסקו בפנימיות התורה), כי ע\"י הלימוד והעסק בפנימיות התורה, מתגלית ביום ההסתלקות הפנימיות והבל\"ג, ענין ההילולא וההילוך.\nח) <b>ומבאר</b> בעל הגאולה במאמר הנ\"ל<sup data-n=\"556\">50</sup>, שבהילולא (יחוד דכר ונוקבא) ג' ענינים (בכללות). יחוד דכר ונוקבא למעלה. דענין דכר ונוקבא הוא גם בהנשמות כמו שהם למעלה קודם ירידתם למטה. דישנם נשמות שבבחינת דכר ונשמות שבבחינת נוקבא. והיחוד דהנשמות שבבחינת דכר עם הנשמות שבבחינת נוקבא נק' הילולא. ויחוד דכר ונוקבא למטה. ובזה עצמו שני ענינים. יחוד דכר ונוקבא כפשוטם ויחוד הנשמה עם הגוף [שהם דוגמת איש ואשה]. וענין הג' בהילולא הוא יחוד הנשמה (דכר) עם הגוף (נוקבא) שיהי' בתחיית המתים. דהילולא זו היא דרגא הכי נעלית, שאז יהי' גילוי העצמות.\n<b>והנה</b> הגילוי שיהי' בתחיית המתים הוא (כמבואר בכ\"מ<sup data-n=\"557\">51</sup>, וגם במאמר הנ\"ל), שאז תתגלה המשכת העצמות שע\"י קיום המצוות בעולם הזה. והוא ע\"ד שנתבאר לעיל (סעיף ז) בענין ההילולא שבהסתלקות הצדיקים שעסקו בפנימיות התורה, שהוא גילוי הפנימיות והבלי גבול דהתומ\"צ שעסקו בעוה\"ז. אלא שעכשיו, בכדי לקבל את הגילוי הוא ע\"י הסתלקות הנשמה מהגוף, ולע\"ל יהי' גילוי זה גם בגוף הגשמי (וגם הגילוי עצמו יהי' נעלה יותר, שאז יהי' גילוי העצמות, כנ\"ל).\n<b>ויש</b> לומר, דמהטעמים שהענין דהילולא הג' מבואר בהדרוש ד\"ה להבין ענין הילולא דרשב\"י, הוא, לרמז, שמעלת הצדיקים שעיקר עסקם הוא לגלות פנימיות התורה הוא בשני ענינים. שיום ההסתלקות שלהם נק' בשם יום הילולא, לפי שאז מתגלה הפנימיות והבל\"ג בהתומ\"צ, כנ\"ל בארוכה. וגם, שע\"י עבודתם לגלות פנימיותהתורה, מתגלה [אצלם, ועל ידם מתגלה קצת גם לכל השייכים אליהם] הבל\"ג דתומ\"צ גם בהנשמה כמו שהיא מלובשת בגוף הגשמי, וגם בגוף הגשמי עצמו, <i>ע\"ד</i> שיהי' בתחה\"מ. ויש להוסיף, שהגילוי דשני הענינים, גם ענין ההילולא דהסתלקות, הוא בהנשמה כמו שמלובשת בגוף. אלא שבתחלה, גילוי הבל\"ג להאדם הוא ע\"י שהוא בתנועה דביטול, שיוצא ממציאותו – ע\"ד ענין ההסתלקות, ועי\"ז, מתגלה אח\"כ הבל\"ג גם <i>בהמציאות</i> דהאדם – ע\"ד הגילוי שיהי' בתחה\"מ.\nט) <b>והנה</b> מהנ\"ל מובן, דבההילוך הנ\"ל (עלי' בבחינת א\"ס ובלי גבול) שנעשה על ידי קיום התומ\"צ בעולם הזה, ג' מדריגות. דבהנשמות שעוסקים רק בנגלה דתורה, ההילוך הוא בהעלם. כי מצד בחינת החיצוניות (נגלה דתורה), התומ\"צ הם במדידה והגבלה. וגילוי הבלי גבול שנמשך ע\"י קיום התומ\"צ בעוה\"ז יהי' בעיקר לע\"ל. ובהנשמות שעוסקים בפנימיות התורה, גילוי הבלי גבול דהתומ\"צ (ענין ההילוך) הוא גם בעת הסתלקותם, ועד\"ז בהיותם למטה ע\"י תנועת הביטול והיציאה ממציאותם. ועי\"ז באים אח\"כ למדריגה נעלית יותר, שגילוי הבלי גבול דהתומ\"צ הוא גם בהמציאות שלהם.\n<b>ויש</b> לומר, שעד\"ז הוא גם בהענין דפדה בשלום נפשי, שיש בו (דוגמת) ג' מדריגות אלה. והענין הוא, דאמיתית הענין דפדה בשלום נפשי, שהמנגד מתבטל לגמרי, כמבואר לעיל (סעיף ב) מהמאמר דבעל הגאולה, הוא ע\"י גילוי היחידה<sup data-n=\"558\">52</sup>. דבחינת חי', כיון שיש כנגדה לעו\"ז<sup data-n=\"559\">53</sup>, לכן הגילוי שלה אינו שולל ומבטל לגמרי הרצונות זרים דנפש הבהמית, והוא רק שהרצון לאלקות (דבחינת חי') מתגבר על הרצונות דנה\"ב. ובכדי שיהי' ביטול הרצונות דנה\"ב הוא ע\"י גילוי היחידה. דכיון שבחינת היחידה אין כנגדה לעו\"ז<sup data-n=\"559\">53</sup>, בבואה דבבואה לית להו<sup data-n=\"560\">54</sup>, לכן ע\"י גילוי היחידה מתבטל הלעו\"ז ממילא.\n<b>וזהו</b> שאמיתית הענין דפדה בשלום נפשי יהי' בביאת המשיח דוקא, כי כמו שבאדם, ביטול הלעו\"ז שבו הוא ע\"י גילוי היחידה דוקא, עד\"ז הוא בכללות העולם, שדוקא ע\"י משיח, שהוא היחידה דכללות ההשתלשלות<sup data-n=\"561\">55</sup>, יהי' ביטול הסט\"א לגמרי. אלא שמ\"מ, כיון שכל הגילויים דלע\"ל תלויים במעשינו ועבודתינו עכשיו<sup data-n=\"562\">56</sup>, גם הענין דביטול הסט\"א ע\"י גילוי יחידה הכללית שיהי' לע\"ל, הוא ע\"י שהאדם מגלה את היחידה שבו שעי\"ז מתבטלים הרצונות זרים דנפשו הבהמית. ובפרט, כשע\"י גילוי היחידה שלו הוא פועל גם (במדה) ביטול הסט\"א שבזולתו. וכמו דוד המלך, שע\"יעבודתו פעל שגם עמשי אמר לו שלום שלום לך ושלום לעוזריך<sup data-n=\"563\">57</sup>, ושגם אנשי אבשלום התפללו לנצחונו של דוד<sup data-n=\"564\">58</sup>.\n<b>והנה</b> כיון שעכשיו כל הענינים הם בהגבלה, לכן, גם ענין המס\"נ שמצד גילוי היחידה<sup data-n=\"565\">59</sup> הוא בנוגע לענין מוגבל. [וע\"ד שנתבאר לעיל (סעיף ז) בענין גילוי כח הא\"ס שבהולדה, שהגילוי דא\"ס הוא בענין מוגבל]. ומזה מובן, דהגם שגילוי היחידה הכללית דלע\"ל הוא ע\"י גילוי היחידה עכשיו, מ\"מ, גילוי היחידה עכשיו לגבי גילוי היחידה הכללית דלע\"ל הוא באין ערוך. ועד\"ז הוא בנוגע לפדה בשלום נפשי שהי' אצל דוד, דכיון שהפדי' בשלום שלו היתה רק בנוגע לכמה אנשים (עמשי, אנשי אבשלום וכו') ולא בכללות העולם (דבכללות העולם היו מנגדים), לכן, הוא באין ערוך כלל לגבי הפדי' בשלום דלע\"ל, שלא יהיו בה הגבלות. והמשכת הפדי' בשלום דלע\"ל (בלי גבול) ע\"י הפדי' דשלום דדוד (שהיא בנוגע לענינים מוגבלים) הוא ע\"ד המשכת ענין ההילוך והבלי גבול ע\"י קיום התומ\"צ בעוה\"ז באלו העוסקים רק בנגלה דתורה. והענין דפדה בשלום נפשי שבהגאולה דיו\"ד כסלו [ועד\"ז בהגאולה די\"ט כסלו ודי\"ב תמוז], כיון שהגאולה היא בנוגע לפנימיות התורה, היחידה דתורה<sup data-n=\"566\">60</sup>, לכן, הענין דפדה בשלום נפשי שבגאולה זו, אין בו מדידות והגבלות, והוא בנוגע לכל הענינים.\n<b>וזהו</b> שיום התשיעי בכסלו, יום ההילולא, הוא הערב דיום הגאולה<sup data-n=\"567\">61</sup>, כי ע\"י שהגילוי דפדה בשלום נפשי הי' לאחרי קדימת העבודה דהילולא של בעל הגאולה, ענין הביטול (שבדומה להסתלקות), המשיך גילוי זה (הגילוי דפדה בשלום נפשי שלמעלה ממדידה והגבלה) גם <i>בהמציאות</i> דכל השייכים אליו. שלכן, כדי לקבל גילוי זה, אין צריכה להיות הכנה דביטול ויציאה מהמציאות, ואין הדבר תלוי אלא ברצון, וביכלתו של כל אחד (גם לפני שיצא ממצבו) לפדות את עצמו באופן דפדה <i>בשלום</i> נפשי, שלום בתכלית השלימות, ועי\"ז לפדות גם את כל העולם, בגאולה האמיתית והשלימה ע\"י משיח צדקנו, במהרה בימינו ממש ובעגלא דידן ממש.\n**********",[["506","*","יצא לאור ב<b>קונטרס ט'-יו\"ד כסלו – תנש\"א</b>, \"לקראת ט' כסלו, יום ההולדת דאדמו\"ר האמצעי (בשנת תקל\"ד) ויום ההילולא שלו (בשנת תקפ\"ח), ויו\"ד כסלו, יום הגאולה דאדמו\"ר האמצעי (בשנת תקפ\"ז) . . <i>יום א' פ' וישלח</i>,<i> שנת ה'תנש\"א</i>\"."],["507","1","תהלים נה, יט."],["508","2","פרש\"י עה\"פ. וראה ירושלמי סוטה פ\"א ה\"ח."],["509","3","ראה ב\"ר פע\"ג, ג. מדרש תלים עה\"פ. – הובאו באוה\"ת (יהל אור) עה\"פ ס\"ח (ע' רז)."],["510","4","בהבא להלן ראה ד\"ה זה ה'תשל\"ח סעיף א (לקמן ע' קמב)."],["511","5","נדפסה באגרות קודש שלו סי' לח. וש\"נ."],["512","6","מכתב כ\"ק מו\"ח אדמו\"ר, נדפס בקובץ מכתבים אודות גודל ערך אמירת תהלים (תהלים אהל יוסף יצחק ע' 200); אגרות-קודש שלו ח\"ג ע' תעג ואילך."],["513","7","<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300251160\" data-slug=\"likkutei-sichot\" data-id=\"1300251160\">לקו\"ש חכ\"ה</a> שיחה ליו\"ד כסלו (ע' 160 ואילך)."],["514","8","משא\"כ הדגשת שייכות גאולת י\"ט כסלו להפסוק פדה בשלום היא בעיקר בשנת הגאולה שהיתה ביום שנכפל בו כי טוב (אגרת הקודש דאדה\"ז הנ\"ל). ועד\"ז בנוגע לגאולת י\"ב תמוז."],["515","9","ח\"א (שער התפלה) מט, א ואילך."],["516","10","כ\"ה הלשון בשערי תשובה שם פי\"א (נה, ד). וראה לקמן הערה 17."],["517","11","פי\"א – נה, ד ואילך."],["518","12","וראה סה\"מ ה'תש\"ד ס\"ע 106 ביאור ענין זה בהמלחמה דנה\"א ונה\"ב."],["519","13","אף שבכללות נק' גם זה בשם \"שלום\" – ראה סה\"מ ה'תש\"ד שם \"שלום הבא ע\"י אימת החרב\"."],["520","14","כמ\"ש (דברי הימים-א כב, ט) שלמה יהי' שמו ושלום ושקט אתן על ישראל בימיו."],["521","15","דברי הימים-א כח, ג. וממ\"ש \"איש מלחמות אתה\" [ולא \"עשית מלחמות\" וכיו\"ב כבדברי הימים שם כב, ח] משמע, שגם עכשיו הוא איש מלחמות."],["522","16","שמואל-ב ז, א."],["523","17","ראה סה\"מ ה'תש\"ד שם (ע' 106; 109), דגם כשלוחמים עם האויב ומנצחים אותו – שעי\"ז הוא מתבטל קצת (ולא רק שאינו לוחם מפני אימה ופחד) – מ\"מ, \"עדיין לא העבירו (את האויב) מכל וכל\", וע\"ד הבינוני בשעת התפלה שנה\"ב הוא כישן, שאח\"כ יכול להיות חוזר וניעור (<a class=\"ft-cite\" href=\"#/read/tanya/3401310018\" data-slug=\"tanya\" data-id=\"3401310018\">תניא פי\"ג – יט, רע\"א</a>). ועפ\"ז יומתק מה שנקרא דוד בשם \"איש מלחמות\" גם לאחרי שה' הניח לו מסביב מכל אויביו, כי גם כשהמנוחה באה ע\"י נצחון המלחמה יש מקום שהרע יהי' חוזר וניעור.\nואולי יש לומר דזהו שמדייק בהמאמר \"בלא מלחמה כלל וכלל\": הלשון \"בלא מלחמה <i>כלל</i>\" מדגיש דזה שהאויב אינו לוחם כנגדו הוא לא מפני שהוא ירא ומפחד ללחום אלא שנצחו אותו; והלשון \"בלא מלחמה <i>כלל וכלל</i>\" מדגיש שהאויב נתבטל לגמרי ולא רק שנצחו אותו, שלכן אין שייך כלל שתהי' מלחמה."],["524","18","שם – נו, א."],["525","19","כמפורש בהמשך תער\"ב שבהערה הבאה. ועפ\"ז יומתק הלשון דבעל הגאולה שם \"בדרך שלום . . כמו לע\"ל . . <i>וכה\"ג</i> הי' בימי שלמה\"."],["526","20","ד\"ה פדה בשלום תרע\"ה (המשך תער\"ב ח\"ב פ' שעד – ע' תשסט)."],["527","21","צפני' ג, ט. – הובא בשערי תשובה ובהמשך תער\"ב שם."],["528","22","שם – נה, ד."],["529","23","לקו\"ש ח\"ד ע' 1207 ואילך. וש\"נ."],["530","24","אבות פ\"ג מט\"ז."],["531","25","שם משנה א."],["532","26","הל' מלכים פי\"א ה\"א."],["533","27","ביצה ב, ב ובפרש\"י שם (ד\"ה והכינו וד\"ה ואין יו\"ט). שו\"ע אדה\"ז או\"ח הל' יו\"ט סתקי\"ג ס\"א."],["534","28","כ\"ה מסורת בית הרב (ראה רשימת כ\"ק מו\"ח אדמו\"ר במבוא לס' בד קודש)."],["535","29","תענית כט, א."],["536","30","ובפרט לפי מארז\"ל שהקב\"ה ממלא שנותיהם של צדיקים מיום ליום (ר\"ה יא, א)."],["537","31","נדפס במאמרי אדהאמ\"צ ויקרא ח\"ב (ע' תרסו ואילך), שיצא לאור לפני שבת זו (בשנת ה'תשמ\"ו – שנת אמירת מאמר זה)."],["538","32","ראה עירובין נד, א (ובגירסת העין יעקב שם)."],["539","33","מלכים-א יז, א. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300251147\" data-slug=\"likkutei-sichot\" data-id=\"1300251147\">לקו\"ש חכ\"ה ע' 147</a> הערה 53."],["540","34","הובא בכ\"מ בדא\"ח בשם הזהר. וראה זהר ח\"ג קד, ב. ח\"א צ, סע\"ב. שם רכז, ב. רלג, ב. ח\"ב צו, ב. ח\"א סא, ב."],["541","35","מאמרי אדהאמ\"צ שם סי\"ב (ע' תרפב). – ענין \"קו המדה\" ראה סה\"מ תקס\"ה ח\"א ע' ב. אוה\"ת שלח ס\"ע תצג ואילך. <i>ובכ\"מ</i>."],["542","36","בהבא להלן ראה מאמרי אדהאמ\"צ שם ס\"א (ע' תרסז). שם ס\"ד וס\"ה (ע' תרעא ואילך). ד\"ה להבין ענין הילולא דרשב\"י תרנ\"ד (סה\"מ תרנ\"ד ע' רסד ואילך)."],["543","37","ראה סה\"מ תרנ\"ג ע' רלה. וש\"נ."],["544","38","ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381318\" data-slug=\"likkutei-torah\" data-id=\"4001381318\">לקו\"ת שה\"ש מז, ג</a>."],["545","39","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381288\" data-slug=\"likkutei-torah\" data-id=\"4001381288\">לקו\"ת שה\"ש מ, א</a>."],["546","40","ראה בארוכה ד\"ה הנ\"ל תרנ\"ד (סה\"מ תרנ\"ד שם). עטר\"ת (סה\"מ עטר\"ת ע' תיד). סה\"מ תרפ\"ו ס\"ע רכו ואילך."],["547","41","פרש\"י ר\"פ נח."],["548","42","אוה\"ת שמות פו, סע\"ב. ובכ\"מ."],["549","43","ראה גם <a class=\"ft-cite\" href=\"#/read/tanya/3401310009\" data-slug=\"tanya\" data-id=\"3401310009\">תניא פ\"ד (ח, ב</a>)."],["550","44","סי\"ג (ע' תרפג)."],["551","45","שם סי\"ב (ס\"ע תרפב)."],["552","46","בהבא לקמן, ראה שם ס\"ט (ס\"ע תרעח) ואילך. ד\"ה הנ\"ל תרנ\"ד (סה\"מ שם ע' רעא)."],["553","47","ראה אגה\"ק ס\"ט."],["554","48","איוב יא, ט."],["555","49","סה\"מ ה'תש\"ה ע' 193. ובכ\"מ."],["556","50","ע' תרפד ואילך. וראה גם ד\"ה הנ\"ל עטר\"ת (סה\"מ שם ע' תיג). סה\"מ תרפ\"ו שם ע' רכג."],["557","51","ראה ג\"כ ד\"ה לה\"ע תחיית המתים שנה זו (ה'תשמ\"ו) – נדפס לקמן ח\"ג ע' רכא ואילך."],["558","52","שערי תשובה שם ספ\"ו (נב, ג) ואילך. וראה בארוכה ד\"ה פדה בשלום ה'תשל\"ט ס\"ד ואילך (לעיל ע' מא ואילך)."],["559","53","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380867\" data-slug=\"likkutei-torah\" data-id=\"4001380867\">לקו\"ת תצא לז, ג</a>. מאמרי אדהאמ\"צ דברים ח\"ב ס\"ע תקמב ואילך. ובכ\"מ."],["560","54","יבמות קכב, א. וש\"נ."],["561","55","רמ\"ז לזח\"ג רס, ב (נדפס במק\"מ קצ, ב). לקוטי תורה להאריז\"ל עה\"פ (בראשית ה, כב) ויתהלך חנוך. ועוד. וראה אוה\"ת נצבים ע' א'רעו. סה\"מ תרכ\"ז ע' טז. תרנ\"ה ס\"ע יט ואילך. תרצ\"ט ע' 207. ועוד."],["562","56","<a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא רפל\"ז</a>."],["563","57","דברי הימים-א יב, יח. – הובא בשערי תשובה שם פי\"א – נו, א (ושם, שזהו\"ע שהשונא נהפך לאוהב)."],["564","58","ירושלמי סוטה פ\"א ה\"ח."],["565","59","ראה ד\"ה ושבתי בשלום ה'תשל\"ח סי\"ב, ובהערה 97 שם (לעיל ריש ע' כו)."],["566","60","ראה בארוכה קונטרס ענינה של תורת החסידות סעיף ו."],["567","61","ולהעיר, שבשורת הגאולה דיו\"ד כסלו באה <i>בט'</i> כסלו (מסורת בבית הרב, הובאה בהוספה לס' בד קודש ע' 22 בהערה)."]]],[1500370009,"<h3>בס\"ד. אור לי\"ד כסלו ה'תשל\"ט<sup data-n=\"568\">*</sup></h3>\n<b>אשר</b> ברא ששון ושמחה חתן וכלה גילה רינה דיצה וחדוה אהבה ואחוה שלום וריעות<sup data-n=\"569\">1</sup>, ומביא כ\"ק מו\"ח אדמו\"ר במאמרו ד\"ה זה<sup data-n=\"570\">2</sup> (שבקונטרס דרושי חתונה תרפ\"ט<sup data-n=\"571\">3</sup>) את מאמר הזהר בפרשת תרומה<sup data-n=\"572\">4</sup> שמבאר שם כל השבע ברכות בפרטיות, ואומר שם בנוגע לברכה השביעית [שהיא כוללת את כל הברכות], שביעאה איהו מקיים כולא, ומהאי שביעאה מתברכאן כולא ודאי כללא דעשר אמירן, בגין דדא כליל עילא ותתא ועל דא כליל בהאי י' זיני דחדוה כו'. ומבאר בהמאמר, שכללא דעשר אמירן כולל עשרת הדברות (עילא) ועשרה מאמרות (תתא), ולהיות שברכה זו היא כללא דעשר אמירן לכן יש בה עשרה לשונות של שמחה (מלבד התיבות חתן וכלה) שהו\"ע השמחה בכל ספירה בפרט [שעי\"ז דוקא הספירות הן בשלימותן, כמובן מהמבואר בכ\"מ<sup data-n=\"573\">5</sup> עה\"פ<sup data-n=\"574\">6</sup> אם הבנים שמחה]. וממשיך בזהר שם (הובא בהמאמר שם) בענין ברכה השביעית, זכאין אינון ישראל דאינון זכו לתתא כגוונא דלעילא. והיינו<sup data-n=\"575\">7</sup> שברכה זו היא (גם) שבח והודאה להקב\"ה על זה שישראל ע\"י עבודתם מבררים ומזככים את המטה (לתתא) שיהי' כגוונא דלעילא, ועי\"ז ממשיכים גילוי אוא\"ס ב\"ה גם בעולמות העליונים (לעילא).\nב) <b>וביאור</b> הענין (וגם השייכות דענין זכו לתתא כגוונא דלעילא לענין חתן וכלה), הוא, דכל הענינים שלמטה משתלשלים מענינם למעלה, ובלשון התניא<sup data-n=\"576\">8</sup> שנשתלשלו מהן, וכן הוא בחתן וכלה (שלמטה), שהם משתלשלים מחתן וכלה שלמעלה<sup data-n=\"577\">9</sup>, הקב\"ה וכנסת ישראל. וכמבואר במדרשי חז\"ל שחתן וכלה האמוריםבשה\"ש קאי על הקב\"ה וכנסת ישראל. וכמרז\"ל<sup data-n=\"578\">10</sup> ביום חתונתו<sup data-n=\"579\">11</sup> זה מתן תורה, דמתן תורה הו\"ע הנישואין דהקב\"ה וכנסת ישראל. וי\"ל שזהו\"ע וטוב לב משתה תמיד<sup data-n=\"580\">12</sup>, כי בכל יום ויום יש הענין דמתן תורה, כמו שאומרים בברכת התורה (שמברכים בכל יום) נותן התורה לשון הוה<sup data-n=\"581\">13</sup>, ועד שבכל יום כל הקורא ושונה הקב\"ה קורא ושונה כנגדו<sup data-n=\"582\">14</sup>, ומבאר אדמו\"ר הזקן<sup data-n=\"583\">15</sup> דזה שהקב\"ה קורא ושונה כנגדו הוא ממש כמו שהי' בשעת מתן תורה בפעם הראשונה. שלכן אמרו<sup data-n=\"584\">16</sup> (בנוגע להלכה בפועל) מה להלן באימה וביראה וברתת ובזיע אף כאן באימה וביראה וברתת ובזיע. ובפרט לפי המבואר<sup data-n=\"585\">17</sup> שד' לשונות אלו (אימה יראה רתת וזיע) הם כנגד ד' האותיות דשם הוי', שבמתן תורה הי' הגילוי דשם הוי' לכ\"א מישראל<sup data-n=\"586\">18</sup>, וגילוי זה הוא גם בעסק התורה עכשיו.\n<b>והנה</b> ע\"י עסק התורה פועלים גם בהעולם שיהי' כלי לאלקות. דע\"י שהתורה נסעה וירדה כו' עד שנתלבשה בדברים גשמיים בכדי שיוכל האדם לתפוס אותה במחשבה דיבור ומעשה שלו<sup data-n=\"587\">19</sup>, הנה עי\"ז ממשיכים גם בהעולם. דהנה ידוע<sup data-n=\"588\">20</sup> שעשרה מאמרות שבהם נברא העולם<sup data-n=\"589\">21</sup> הם מכוונים כנגד עשרת הדברות, כדאיתא בזהר<sup data-n=\"590\">22</sup> עה\"פ<sup data-n=\"591\">23</sup> עשרה עשרה הכף בשקל הקודש, ולכן ע\"י עסק התורה (עשרת הדברות) פועלים בהעשרה מאמרות, שגם הם יהיו בשקל הקודש<sup data-n=\"592\">24</sup>.\n<b>ויש</b> לומר, דזה שעשרה מאמרות ועשרת הדברות שקולים זה כנגד זה, הכוונה בזה היא גם שכל אחד פועל בהשני. דכמו שעשרת הדברות פועלים (כנ\"ל) בהעשרה מאמרות, וכמאמר<sup data-n=\"593\">25</sup> אסתכל באורייתא וברא עלמא, שבריאת העולם היא ע\"י העשרהמאמרות כמו שהם בתורה<sup data-n=\"594\">26</sup>, שירדו אח\"כ בבחי' מילין דהדיוטא<sup data-n=\"595\">27</sup> להוות את העולם, עד\"ז הוא לאידך, שעבודת האדם בעניני העולם שנברא בהעשרה מאמרות מילין דהדיוטא פועלת בעשרת הדברות [שלכן יש פירוש<sup data-n=\"596\">28</sup> במאמר הזהר עה\"פ עשרה עשרה גו', שעשרה מאמרות הם גבוהים מעשרת הדברות]. וי\"ל שהוא ע\"פ המבואר באגה\"ק<sup data-n=\"597\">29</sup> שבירור הלכה בתורה הוא ע\"י נשמה בגוף דוקא, ולכן באים העליונים לשמוע חידושי תורה מהתחתונים (וכמרז\"ל<sup data-n=\"598\">30</sup> עה\"פ<sup data-n=\"599\">31</sup> חברים מקשיבים לקולך). ועד שהקב\"ה אומר למלאכי השרת לי מה אתם שואלים אני ואתם נלך אצל ב\"ד של מטה<sup data-n=\"600\">32</sup>.\n<b>ועד\"ז</b> הוא גם בחתן וכלה, דעם היות שהחתן וכלה שלמטה משתלשלים מבחי' חתן וכלה שלמעלה, שענינם בספירות הוא ז\"א ומלכות<sup data-n=\"601\">33</sup>, ולמעלה יותר קוב\"ה ושכינתי' (חתן וכלה) הו\"ע אוא\"ס שלפני הצמצום והקו כמבואר בארוכה בדרושי כ\"ק אדמו\"ר מהר\"ש<sup data-n=\"602\">34</sup>, ועד שהענין דקוב\"ה ושכינתי' הוא גם לפני הצמצום<sup data-n=\"603\">35</sup>, מ\"מ, ע\"י העבודה למטה דוקא (ובפרטיות ע\"י שמחת חתן וכלה שלמטה) ממשיכים תוספת אור בחתן וכלה שלמעלה גם כמו שהם בשרשם הראשון לפני הצמצום. וע\"ד שע\"י עסק התורה והמצוות שלמטה דוקא נעשה יחוד קוב\"ה ושכינתי'<sup data-n=\"604\">36</sup> כמבואר בתניא<sup data-n=\"605\">37</sup>, גם כמו שהם למעלה מעלה.\nג) <b>ומדייק</b> בהמאמר<sup data-n=\"606\">38</sup> למה מקדים ששון ושמחה לפני חתן וכלה, והרי השמחה (שבברכה זו) היא מה שמשמחים את החתן ואת הכלה וכמאמר<sup data-n=\"607\">39</sup> כיצד מרקדין לפני הכלה. גם אינו מובן<sup data-n=\"608\">40</sup> מ\"ש אשר ברא כו' חתן וכלה, דכיון שהתחלתהענין דחתן וכלה הוא חתן וכלה שלמעלה, איך שייך לומר על זה אשר ברא, לשון בריאה. והרי אפילו כלה (שלמעלה), ספירת המלכות, היא בכלל הספירות דאצילות [עשר ולא תשע<sup data-n=\"609\">41</sup>, כי המלכות משלימה הספירות, אנכי<sup data-n=\"610\">42</sup> שלומי אמוני ישראל<sup data-n=\"611\">43</sup>], ועאכו\"כ בחתן שלמעלה שהוא ז\"א, איך שייך לומר בו הלשון בריאה.\n<b>ומבאר</b><sup data-n=\"612\">44</sup> בהקדם מ\"ש<sup data-n=\"613\">45</sup> לפני לא נוצר א-ל, שאינו מובן<sup data-n=\"614\">46</sup> איך שייך לשון יצירה על שם א-ל שהוא משמותיו של הקב\"ה, מז' השמות שאינם נמחקים<sup data-n=\"615\">47</sup>. והדיוק בפסוק זה הוא עוד יותר מהדיוק בברכת אשר ברא, כיון שיצירה (\"נוצר\") היא למטה מבריאה (\"ברא\").\n<b>והענין</b> הוא, שמבאר בהמאמר<sup data-n=\"612\">44</sup>, דשם א-ל שייך לעולמות. דשם א-ל הוא בחסד<sup data-n=\"616\">48</sup>, ובענין החסד כתיב<sup data-n=\"617\">49</sup> כי אמרתי עולם חסד יבנה, שהכוונה בזה היא שבנין העולם הוא ע\"י ספירת החסד ושבנין ספירת החסד הוא בשביל התהוות העולמות<sup data-n=\"618\">50</sup>. ולכן שייך בשם א-ל לשון יצירה להיותו מקור לעולמות. ועד\"ז<sup data-n=\"619\">51</sup> הוא גם בנוגע לבחי' חתן (ששייך בו לשון בריאה), כי חתן הוא מלשון חות דרגא<sup data-n=\"620\">52</sup> [דהגם שהחילוק בין ז\"א (חתן) למלכות (כלה) הוא שהמלכות גם כמו שהיא באצילות היא השרש ומקור דבי\"ע משא\"כ ז\"א הוא סוף עולמות הא\"ס (כמבואר בתו\"א<sup data-n=\"621\">53</sup> ב\"כי\"ק אדמו\"ר נ\"ע\"), מ\"מ חתן הוא מלשון חות דרגא], ירידה, ולכן שייך בו לשון בריאה.\nד) <b>וביאור</b> הענין, הנה ידוע שהסיבה לבריאת העולם וכל סדר ההשתלשלות הוא החסד שבאוא\"ס, כמבואר בארוכה בד\"ה אתה אחד לאדמו\"ר האמצעי<sup data-n=\"622\">54</sup> ובכמה דרושים שלו. וענין החסד שבאוא\"ס הוא כללות ענין הגילוי, וכמו שמבאראדמו\"ר הצ\"צ ברשימותיו לתהלים<sup data-n=\"623\">55</sup> עה\"פ<sup data-n=\"624\">56</sup> א-ל אלקים הוי' דיבר ויקרא ארץ, ששמות אלה ישנם גם לפני הצמצום, א-ל (חסד) מורה על התחלת גילוי האור (מה שהי' ממלא מקום החלל<sup data-n=\"625\">57</sup>). ולכן שם א-ל קדם לשם אלקים, כי תחלה הו\"ע הגילוי והוא שרש וסיבת ההתהוות, ולאח\"ז (בכדי שיהי' אפשר להיות התהוותם בפועל) הי' הצמצום, אלקים.\n<b>וגם</b> בההתהוות עצמה שבה קדם הצמצום וכמרז\"ל<sup data-n=\"626\">58</sup> בתחלה עלה במחשבה לברוא את העולם במדת הדין, הנה נוסף לזה שהצמצום הוא בשביל הגילוי (כמבואר בהמשך תער\"ב<sup data-n=\"627\">59</sup> ובכ\"מ), הנה גם הצמצום גופא הוא מצד החסד, וכמו שמבאר הרב המגיד<sup data-n=\"628\">60</sup> שהצמצום שלמעלה הוא כמו אב המצמצם את שכלו כו' בשביל בנו הקטן כו' האהבה גרמה את הצמצום. היינו שהצמצום הוא בכדי שהאור יומשך ויתקבל בהתחתונים, ועד שיומשך בהם גילוי אור נעלה יותר מהאור שהאיר בגילוי קודם הצמצום<sup data-n=\"629\">61</sup>. ועד שיהי' דירה לו ית', לו לעצמותו [בדוגמת דירת האדם, שעצמות האדם דר בהדירה]<sup data-n=\"630\">62</sup>, ושהעצמות יהי' בהם בגילוי כמ\"ש<sup data-n=\"631\">63</sup> ולא יכנף עוד מוריך.\nה) <b>והנה</b> הסיבה לבנין החסד (בכדי שיהי' התהוות העולם) היא כי חפץ חסד הוא<sup data-n=\"632\">64</sup>. והענין דחפץ חסד הוא למעלה מחסד (לא רק מחסד כמו שהוא במדות אלא למעלה גם משרשו כמו שהוא במוחין וכו'), כי ענינו הוא חפץ, רצון ותענוג, אלא שהחפץ הוא שיהי' חסד<sup data-n=\"633\">65</sup>. וחפץ זה הוא הסיבה לבנין החסד שממנו נבנה העולם. ויש לומר, דחתן מלשון חות דרגא הוא בחי' חפץ (חסד) שלמעלה מחסד. דזה שנתעורר ברצון וחפץ שיהי' חסד הוא ירידה (חות דרגא) לגבי עצמות אוא\"ס. [ויש לומר דזהו מ\"ש בהמאמר<sup data-n=\"634\">66</sup> שחתן הוא התקשרות, והוא מה שאוא\"ס התקשר כביכול לברוא את העולם, דיש לומר, שזה שאוא\"ס התקשר כביכול לברוא את העולם הו\"ע הרצון והחפץ]. וכיון שהירידה להיות חפץ חסד היא ירידה באין ערוך, לכן שייך בזה לשון בריאה, אשר ברא כו' חתן. ועפ\"ז יובן גם מה שבחתן נאמר לשון בריאה, ובשם א-ל נאמר לשון יצירה (לפני לא נוצר א-ל), כי חפץ חסד (שאינו אלא חפץ ורצון שיהי' חסד) הוא למעלה מציור, ולכן שייך בו רק הלשוןבריאה, משא\"כ בחסד (שם א-ל בחסד), גם כמו שהוא לפני הצמצום, מכיון שהוא ציור (של חסד), שייך בזה לשון יצירה.\nו) <b>וזהו</b> אשר ברא ששון ושמחה חתן וכלה כו', שקאי (גם) על בריאת חתן וכלה שלמעלה (שמהם משתלשלים חתן וכלה שלמטה). וזה שנקראים בשם חתן וכלה (דשמו אשר יקראו לו בלה\"ק מורה על תוכנו של הדבר ועד שהוא המהוה ומחי' ומקיים את הדבר כתורת הבעש\"ט הידועה<sup data-n=\"635\">67</sup>), הוא, כי חתן הוא מלשון חות דרגא כמשנת\"ל (סעיף ג), וכלה היא מלשון כליון ומלשון כלתה נפשי<sup data-n=\"636\">68</sup> [שהם שתי בחי' בכלה, כמבואר בלקו\"ת<sup data-n=\"637\">69</sup>]. והכוונה בבריאת חתן וכלה שלמעלה היא בכדי שיומשכו מהם חתן וכלה שלמטה, וכמבואר לעיל (סעיף ג) בפירוש הכתוב כי אמרתי עולם חסד יבנה שבנין ספירת החסד הוא בכדי שיהי' התהוות העולם. ולכן ע\"י עבודת ישראל למטה ובפרט בזה שמשמחים את החתן וכלה (כפשוטם למטה), עי\"ז פועלים הן לעילא והן לתתא, ועד שנעשה שמח תשמח רעים האהובים כשמחך יצירך בגן עדן מקדם<sup data-n=\"638\">70</sup> (קודם החטא) שאז הי' העולם על מילואו<sup data-n=\"639\">71</sup>, אלה תולדות השמים והארץ בהבראם<sup data-n=\"640\">72</sup>, תולדות מלא<sup data-n=\"641\">73</sup>. ויתירה מזו, דכיון שהכוונה בהירידה (דעולם) שנעשה ע\"י חטא עה\"ד היא לצורך עלי', הרי מובן שהעלי' היא למקום גבוה יותר מכמו שהי' קודם הירידה, ולכן, ע\"י העבודה (שלאחרי החטא) יהי' עילוי נעלה יותר גם מכמו שהי' בתחלת הבריאה, אלה תולדות פרץ<sup data-n=\"642\">74</sup>, תולדות מלא<sup data-n=\"641\">73</sup>, דתולדות מלא שבפסוק זה הוא למעלה יותר מתולדות מלא שבתחלת הבריאה. וגילוי עילוי זה יהי' בביאת משיח צדקנו, כמו שמסיים שם (בתולדות פרץ<sup data-n=\"643\">75</sup>) וישי הוליד את דוד, דוד מלכא משיחא.\n<b>וגילוי</b> זה יהי' בקרוב ממש ובעגלא דידן, בחסד וברחמים ובטוב הנראה והנגלה, ע\"י מעשינו ועבודתנו במשך שיתא<sup data-n=\"644\">76</sup> אלפי שני דהוה עלמא<sup data-n=\"645\">77</sup> [שזה כולל ענין הזמן (שיתא אלפי שני) וענין המקום (עלמא) יחד], ובפרט ע\"י העבודה דיפוצו מעינותיך, המעיינות דתורת הבעש\"ט, ובפרט כמו שנתגלו ע\"י אדמו\"ר הזקן לאחרי י\"ט כסלו [וכידוע מאמר אדמו\"ר (מהורש\"ב) נ\"ע<sup data-n=\"646\">78</sup> שענין יפוצו מעינותיך חוצה הותחל בעיקר לאחרי פטרבורג], שעי\"ז אתי מר דא מלכא משיחא<sup data-n=\"647\">79</sup> שאז יהיוהנישואין של הקב\"ה וכנסת ישראל<sup data-n=\"648\">80</sup>, וגם הנישואין דהקב\"ה ודכל אחד מישראל, בתכלית השלימות, כמבואר בארוכה בכ\"מ<sup data-n=\"649\">81</sup> עה\"פ<sup data-n=\"650\">82</sup> כימי צאתך מארץ מצרים אראנו נפלאות שהענינים דלע\"ל יהיו נפלאות – נו\"ן פלאות – אפילו בערך הנסים והנפלאות דיציאת מצרים, שאז יהי' ענין הנישואין בשלימות, בקרוב ממש, במהרה בימינו.\n**********",[["568","*","יצא לאור ב<b>קונטרס י\"ד כסלו – תש\"נ</b>, \"לקראת יום הבהיר י\"ד כסלו, יום נישואי כ\"ק אדמו\"ר שליט\"א והרבנית הצדקנית מרת חי' מושקא נ\"ע זי\"ע (בשנת תרפ\"ט) . . <i>מוצש\"ק פ' ויצא שנת ה'תש\"נ</i>\". מאמר זה \"אמר כ\"ק אדמו\"ר שליט\"א בהתוועדות דאור לי\"ד כסלו ה'תשל\"ט – שנת היובל להחתונה. המאמר מיוסד על ד\"ה זה שנאמר ע\"י כ\"ק אדמו\"ר מהוריי\"צ נ\"ע בי\"ד כסלו תרפ\"ט בעת החתונה\"."],["569","1","נוסח ברכה ז' דברכות נישואין."],["570","2","שנאמר ב\"ג', י\"ד כסלו פ\"ט, חתונה למז\"ט\"."],["571","3","קונטרס ב – נדפס בסה\"מ קונטרסים ח\"א, והו\"ל עוה\"פ ז\"ע (בשנת תשל\"ט) בקונטרס בפ\"ע. – ראה סה\"מ שם כא, ב ואילך. סה\"מ תרפ\"ט ע' 86 ואילך."],["572","4","זהר ח\"ב קסט, ב."],["573","5","ד\"ה שמח תשמח תרנ\"ז בתחלתו (סה\"מ תרנ\"ז ע' קעג ואילך). המשך תרס\"ו ס\"ע תקפו ואילך."],["574","6","תהלים קיג, ט."],["575","7","ראה ד\"ה כל הנהנה תרפ\"ט (והוא המשך לד\"ה אשר ברא הנ\"ל) פי\"א-יב (סה\"מ קונטרסים שם כז, סע\"ב ואילך. סה\"מ תרפ\"ט ע' 94 ואילך)."],["576","8","ריש פ\"ג."],["577","9","ראה ד\"ה כל הנהנה הנ\"ל פי\"א (מאבודרהם ברכת נשואין ופירושן). וכ\"ה גם בד\"ה אשר ברא תרל\"ד (סה\"מ תרל\"ד ע' טז-יז). תרח\"צ פ\"ה (סה\"מ תרח\"צ ס\"ע קפו)."],["578","10","תענית כו, ב (במשנה). ועד\"ז בפרש\"י עה\"פ שה\"ש ג, יא. – הובא גם בד\"ה אשר ברא תרפ\"ט הנ\"ל פ\"ג (סה\"מ קונטרסים שם כג, א). ד\"ה זה תרל\"ד ותרח\"צ שם. וראה לקו\"ת שה\"ש בתחלתו. <i>ובכ\"מ</i>."],["579","11","שה\"ש שם."],["580","12","משלי טו, טו. ולהעיר מסנהדרין ק, סע\"ב."],["581","13","של\"ה כה, א. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380172\" data-slug=\"likkutei-torah\" data-id=\"4001380172\">לקו\"ת תזריע כג, א</a>. תו\"ח יתרו שבהערה 15. <i>ובכ\"מ</i>."],["582","14","ראה תדא\"ר פי\"ח. יל\"ש איכה רמז תתרלד."],["583","15","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370301\" data-slug=\"torah-or\" data-id=\"3901370301\">תו\"א יתרו סז, ב</a>. וראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370100\" data-slug=\"torah-or\" data-id=\"3901370100\">תו\"א ויצא כא, ב</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370104\" data-slug=\"torah-or\" data-id=\"3901370104\">שם כב, ב</a>. וראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550321\" data-slug=\"torat-chaim\" data-id=\"2300550321\">תו\"ח יתרו שע, ב</a> ואילך [בהוצאה החדשה – ח\"ב רנג, סע\"ב ואילך]. ויצא כד, סע\"ג ואילך. ובכ\"מ."],["584","16","ברכות כב, א."],["585","17","לקוטי הש\"ס להאריז\"ל מס' מו\"ק. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300081269\" data-slug=\"likkutei-sichot\" data-id=\"1300081269\">לקו\"ש ח\"ח ע' 258</a> הערה 2."],["586","18","ראה בארוכה לקו\"ת ר\"פ ראה. ובכ\"מ."],["587","19","<a class=\"ft-cite\" href=\"#/read/tanya/3401310009\" data-slug=\"tanya\" data-id=\"3401310009\">תניא פ\"ד (ח, ב</a>)."],["588","20","ד\"ה וכל בניך תרפ\"ט (בקונטרס דרושי חתונה הנ\"ל) פ\"ג (סה\"מ קונטרסים שם יז, ב ואילך). ד\"ה שלום רב ה'תש\"ד פ\"ו (סה\"מ ה'תש\"ד ע' 75 ואילך). ועוד. וראה גם מאמרי אדמו\"ר האמצעי שבהערה 28. וש\"נ."],["589","21","אבות פ\"ה מ\"א. זהר שבהערה הבאה."],["590","22","ח\"ג יא, ב ואילך."],["591","23","נשא ז, פו."],["592","24","ראה ד\"ה וכל בניך שם רפ\"ג: ושניהם בשקל הקודש."],["593","25","זח\"ב קסא, א-ב."],["594","26","ראה זהר שם, סע\"א, שהכוונה ב\"אסתכל באורייתא\" היא לעשרה מאמרות שבתורה. ולהעיר משער היחוד והאמונה ספ\"א, דזה שהעש\"מ \"יש בהם כח וחיות לברוא יש מאין כו'\" הוא מפני שהם עשרה מאמרות שבתורה, ואורייתא וקוב\"ה כולא חד."],["595","27","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380187\" data-slug=\"likkutei-torah\" data-id=\"4001380187\">זח\"ג קמט, ב</a>. וראה לקו\"ת אחרי כה, ד."],["596","28","הובא באוה\"ת תשא ע' א'תתנא. וראה גם מאמרי אדמו\"ר האמצעי דברים ח\"א ע' רפ. <i>וש\"נ</i>."],["597","29","סכ\"ו (קמד, ב ואילך)."],["598","30","שהש\"ר פ\"ח, יג."],["599","31","שה\"ש ח, יג."],["600","32","דב\"ר פ\"ב, יד."],["601","33","ראה גם ד\"ה שמח תשמח תרנ\"ז ע' 90. שם ע' 105 ואילך (סה\"מ תרנ\"ז ע' רסו. שם ע' רפב ואילך). ובכ\"מ."],["602","34","המשך וככה תרל\"ז פכ\"ז (ע' לג)."],["603","35","המשך תרס\"ו ע' תקיז."],["604","36","שלכן אומרים לפני כל מצוה לשם יחוד קוב\"ה ושכינתי'* – כ\"ה ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380941\" data-slug=\"likkutei-torah\" data-id=\"4001380941\">לקו\"ת ר\"ה נה, ג</a>. ובכ\"מ. והוא בפע\"ח שער ו (שער הזמירות) ספ\"ה. וראה עוד בהנסמן לקמן ח\"ד ע' רמה הערה 60."],["605","37","פמ\"א (נז, ב)."],["606","38","ד\"ה אשר ברא תרפ\"ט הנ\"ל בתחלתו (סה\"מ קונטרסים שם כב, רע\"א). שם פ\"ג (סה\"מ שם כג, רע\"א) וכ\"ה גם בד\"ה זה תרח\"צ פ\"א (סה\"מ תרח\"צ ע' קפד)."],["607","39","כתובות טז, סע\"ב."],["608","40","ד\"ה אשר ברא תרפ\"ט פ\"ג שם. ד\"ה זה תרל\"ד (סה\"מ תרל\"ד ע' טז). תרח\"צ פ\"ה (ס\"ע קפו ואילך).\n*) <i>ומה שאנו אומרים לשם יחוד רק פעם אחת קודם התפלה הוא לפי שאמירה זו היא פעולה נמשכת על כל היום – ד\"ה שמח תשמח תרנ\"ז ע' 25 (סה\"מ תרנ\"ז ע' קצח)</i>.<i> סה\"מ עטר\"ת ע' תקיח</i>.<i> ועוד</i>."],["609","41","ספר יצירה פ\"א מ\"ד. וראה זח\"ב קפז, ב. פרדס שער א (שער עשר ולא תשע) פ\"ו."],["610","42","לשון הכתוב – שמואל-ב כ, יט."],["611","43","ראה ביאורי הזהר להצ\"צ תשא ס\"ע רפ. המשך תער\"ב ח\"ב פש\"צ. סה\"מ תרפ\"ז ע' כה. ובכ\"מ. וראה ע\"ח שער ל (שער הפרצופים) דרוש ג. שער כז (שער עיבור יניקה מוחין) פ\"א. ועוד."],["612","44","בד\"ה הנ\"ל תרפ\"ט פ\"ג (סה\"מ קונטרסים שם כג, א). וכ\"ה גם בד\"ה זה תרל\"ד ותרח\"צ שבהערה 40."],["613","45","ישעי' מג, י."],["614","46","בד\"ה הנ\"ל תרפ\"ט שם: ואיתא בספרים. ובד\"ה זה תרל\"ד ותרח\"צ שם: והקשה בזהר. – ראה זח\"ג פו, א. ביאוה\"ז לשם קלח, סע\"ד ואילך. אוה\"ת משפטים ע' א'קצח ואילך. ובאוה\"ת שם: ונלאו בו כל המפרשים. – ועיין רד\"ק עה\"פ. ועוד."],["615","47","שבועות לה, סע\"א. רמב\"ם הל' יסוה\"ת פ\"ו ה\"ב."],["616","48","זח\"ג ל, ב. שם סה, א. ובכ\"מ."],["617","49","תהלים פט, ג. וראה ד\"ה אשר ברא תרפ\"ט שם."],["618","50","ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381176\" data-slug=\"likkutei-torah\" data-id=\"4001381176\">לקו\"ת שה\"ש יא, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381230\" data-slug=\"likkutei-torah\" data-id=\"4001381230\">שם כה, ב</a>. ובכ\"מ."],["619","51","ד\"ה כל הנהנה תרפ\"ט הנ\"ל פי\"א (סה\"מ קונטרסים שם כז, ב). ד\"ה הנ\"ל תרל\"ד ותרח\"צ שם."],["620","52","כ\"ה בד\"ה הנ\"ל תרפ\"ט ותרל\"ד שם. לקו\"ת שה\"ש בתחילתו. <i>ובכ\"מ</i>. וראה יבמות סג, א: נחית דרגא נסיב איתתא. ובד\"ה הנ\"ל תרח\"צ שם: נחות דרגא."],["621","53","ס\"פ תרומה."],["622","54","נדפס בקונטרס בפ\"ע – קה\"ת, ברוקלין תשכ\"ה [ולאח\"ז במאמרי אדמו\"ר האמצעי קונטרסים בתחלתו]."],["623","55","<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830035\" data-slug=\"or-hatorah-hb\" data-id=\"8158830035\">יהל אור ע' קצ</a> (ועד\"ז ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830022\" data-slug=\"or-hatorah-hb\" data-id=\"8158830022\">אוה\"ת קרח ע' תשכא</a>-ב). וראה גם שם ע' תשח – פקסימליא מגוף כתי\"ק של הצ\"צ. וראה ג\"כ ד\"ה זה תרל\"ד ותרח\"צ שם. סה\"מ עטר\"ת ע' קצז ואילך. ה'תש\"ג ע' 63 ואילך."],["624","56","תהלים נ, א."],["625","57","ע\"ח שער א (דרוש עגולים ויושר) ענף ב. אוצרות חיים ומבוא שערים בתחלתם."],["626","58","פרש\"י ר\"פ בראשית."],["627","59","ח\"ב ע' א'ג."],["628","60","לקו\"א ואו\"ת בתחלתם."],["629","61","ראה המשך תרס\"ו ע' ד."],["630","62","המשך תרס\"ו ס\"ע ג. שם ע' תמה. ובכ\"מ. – נסמנו לקמן ע' שח הע' 32."],["631","63","ישעי' ל, כ. וראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310041\" data-slug=\"tanya\" data-id=\"3401310041\">תניא פל\"ו (מו, א</a>)."],["632","64","מיכה ז, יח. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381176\" data-slug=\"likkutei-torah\" data-id=\"4001381176\">לקו\"ת שה\"ש יא, ד</a>."],["633","65","ראה בארוכה ד\"ה זה היום תחלת מעשיך דער\"ה ה'תשמ\"ב סעיף ד (לעיל ח\"א ס\"ע מג ואילך)."],["634","66","ד\"ה כל הנהנה תרפ\"ט הנ\"ל פי\"א (סה\"מ קונטרסים שם כז, ב)."],["635","67","שער היחוד והאמונה פ\"א."],["636","68","לשון הכתוב – תהלים פא, ג."],["637","69","שה\"ש בתחלתו."],["638","70","נוסח ברכה ו' דברכות נשואין."],["639","71","ראה ב\"ר פי\"ד, ז. פי\"ג, ג. וראה ד\"ה וכל בניך תרפ\"ט רפ\"ד (סה\"מ קונטרסים שם יח, ב)."],["640","72","בראשית ב, ד."],["641","73","ב\"ר פי\"ב, ו. שמו\"ר פ\"ל, ג."],["642","74","רות ד, יח."],["643","75","רות שם, כב."],["644","76","ראה ר\"ה לא, א."],["645","77","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא רפל\"ז</a>."],["646","78","ספר השיחות תורת שלום ס\"ע 112 ואילך."],["647","79","ראה אגה\"ק דהבעש\"ט, נדפסה גם בכתר שם טוב בתחלתו."],["648","80","ראה שמו\"ר ספט\"ו. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381320\" data-slug=\"likkutei-torah\" data-id=\"4001381320\">לקו\"ת שה\"ש מח, א</a> ואילך."],["649","81","<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316600487\" data-slug=\"or-hatorah-hb\" data-id=\"8316600487\">אוה\"ת נ\"ך</a> עה\"פ סק\"ז (ע' תפז), מזח\"א בהשמטות סי' כה (רסא, ב). וראה שם סק\"ח, מפע\"ח שער כא (שער חג המצות) פ\"ו (בד\"ה מהר\"י ז\"ל). וראה ד\"ה כימי צאתך מארץ מצרים דאחש\"פ ה'תשל\"ט (לקמן ח\"ג ע' רד ואילך). ד\"ה זה די\"א ניסן ה'תשמ\"ב (לקמן ח\"ג ע' קמז ואילך)."],["650","82","מיכה ז, טו."]]],[1500370010,"<h3>בס\"ד. י\"ט כסלו ה'תשל\"ט<sup data-n=\"651\">*</sup></h3>\n<b>אמר</b> ר' אושעיא מאי דכתיב<sup data-n=\"652\">1</sup> צדקת פרזונו בישראל גו' צדקה עשה הקב\"ה בישראל שפיזרן לבין האומות<sup data-n=\"653\">2</sup>, ומבאר כ\"ק מו\"ח אדמו\"ר במאמרו ד\"ה זה [שנאמר בי\"ט כסלו<sup data-n=\"654\">3</sup> תרפ\"ט בסעודה, ונדפס בקונטרס דרושי חתונה תרפ\"ט<sup data-n=\"655\">4</sup>], דע\"י שישראל מפוזרים בכמה מדינות, הנה גם כשבמדינה אחת דוחקים ולוחצים את בנ\"י ואין נותנים להם ללמוד תורה ולקיים מצוות, ועד שבכמה מצוות הם אנוסים ממש<sup data-n=\"656\">5</sup> שאין להם אפשרות כלל לקיים אותם אפילו ע\"י מס\"נ<sup data-n=\"657\">6</sup> [ולדוגמא, כשיש גזירת המלכות שלא להכניס להמדינה ד' מינים, שאז גם ע\"י מס\"נ א\"א לקיים המצוה], הנה ע\"י שישראל הנמצאים בשאר המדינות עוסקים בתומ\"צ, הם נותנים כח ועוז גם לאלו הנמצאים בהמקום שיש שם גזירות, שיוכלו ללמוד תורה ולקיים מצוות. ומן הקל אל הכבד, בתחלה שיוכלו לקיים את המצוות ע\"י מס\"נ עכ\"פ [וכידוע שיש דעה בפוסקים<sup data-n=\"658\">7</sup> שגם בהמצוות שעליהם אמרו יעבור ואל יהרג רשאי לקדש את השם ולמסור עצמו], ועד שאח\"כ לא יצטרכו למס\"נ כלל<sup data-n=\"659\">8</sup>, ועד שלא יהי' להם נסיונות ואפילו לא מניעות ועיכובים, כי יצאו לחירות ויוכלו לעסוק בתומ\"צ מתוך הרחבה, כמארז\"ל<sup data-n=\"660\">9</sup> כל המקיים את התורה מעוני סופו לקיימה מעושר.\nב) <b>והנה</b> כיון שהתורה היא נצחית בכל עת וזמן ובכל מקום (כמבואר בהמאמר<sup data-n=\"661\">10</sup>), מובן שצדקה זו היא גם בהמקומות שאין שם גזירות על תומ\"צ. ויובן זה ע\"פ מ\"ש כ\"ק מו\"ח אדמו\"ר (בדרושי חתונה הנ\"ל<sup data-n=\"662\">11</sup>) בענין מצות פדיון שבוייםשישנה גם ברוחניות. דכמו שהשבוי בגשמיות (היושב במאסר) אינו יכול לצאת משם, עד\"ז הוא גם ברוחניות, שלפעמים האדם שבוי רח\"ל בידי יצרו [וע\"ד בעלי עסקים הטרודים ומוטרדים ביותר בטרדות עסקיהם, שהם קשורים (שבויים) בהמחשבות המבלבלות ואינם יכולים לצאת מהם], ועד שלפעמים הוא כמו אנוס<sup data-n=\"663\">12</sup>, ובלשון הרמב\"ם<sup data-n=\"664\">13</sup> (בנוגע להלכה) יצרו הוא שתקפו. וזהו\"ע הצדקה ע\"י שפיזרן לבין האומות גם בנוגע למקומות הרווחה, דכאשר מי שהוא מישראל שבוי בידי יצרו רח\"ל (בנוגע לענין פרטי), יציאתו מהשבי' היא [לא בכח עצמו, כיון שאין חבוש מתיר עצמו<sup data-n=\"665\">14</sup>, כ\"א] ע\"י יהודי שאינו נתון בשבי' בנוגע לענין זה. והיינו, דגם כאשר גם הפודה אותו מהשבי' הוא שבוי בידי יצרו, ועד שהוא כמו אנוס (יצרו הוא שתקפו) בנוגע למצוה אחרת, מ\"מ, כיון שבנוגע לכו\"כ מצוות אינו שבוי בידי יצרו, כי התנגדות היצה\"ר אצל כ\"א היא (בעיקר) בענין אחר [דכמו<sup data-n=\"666\">15</sup> שבכל זמן יש עבודה מיוחדת השייכת ביותר לזמן זה, ועיקר הפיתויים וההתנגדות של היצה\"ר הם למנוע עבודה זו<sup data-n=\"667\">16</sup>, שלכן הנסיונות שבדור אחד שונים מהנסיונות בדורות אחרים [וכמו בזמנו של מנשה שאז הי' שולט היצר דע\"ז<sup data-n=\"668\">17</sup> משא\"כ בהדורות שלאחריו, עאכו\"כ לאחר שקטלוהו ליצרא דע\"ז<sup data-n=\"669\">18</sup>], עד\"ז הוא גם בזמן אחד גופא, שלכל אחד מישראל יש ענין מיוחד (מצוה או מנהג וכיו\"ב) שנוגע אליו ביותר, כידוע<sup data-n=\"670\">19</sup> בביאור מארז\"ל<sup data-n=\"671\">20</sup> אבוך במאי הוה זהיר טפי, ועיקר הפיתויים וההתנגדות של היצה\"ר שלו הם בנוגע לענין זה], וע\"י שמקיים את המצוות שאין יצרו לוחם כנגדם (כ\"כ), הוא פודה מהשבי' את זה שיצרו תקפו במצוות אלו. וזהו צדקה עשה הקב\"ה בישראל שפיזרן לבין האומות, דפדיון שבויים הוא צדקה הכי נעלית, וכמבואר במאמר הנ\"ל&lt;11&gt; שבמצות צדקה פדיון שבויים הוא קודם לכל דבר ואין מצוה גדולה כפדיון שבויים<sup data-n=\"672\">21</sup>, וע\"י <i>שפיזרן</i> לבין האומות, שיצרו של אחד שונה מיצרו של השני, עי\"ז מתקיימת הצדקה דפדיון שבויים, כנ\"ל.ג) <b>ומדייק</b> בהמאמר<sup data-n=\"673\">22</sup>, דלפי פירוש זה בצדקת פרזונו (צדקה כו' שפיזרן כו') הול\"ל צדקת פזרונו ולמה נאמר פרזונו. ומבאר<sup data-n=\"674\">23</sup>, שפרזונו הוא ע\"ד מ\"ש<sup data-n=\"675\">24</sup> פרזות תשב ירושלים. והיינו, שהצדקה שעשה הקב\"ה בישראל בזה שפיזרן לבין האומות הוא בכדי שעי\"ז יגיעו למדריגה נעלית יותר מכמו שהיו לפני הירידה דפיזרן, ועד לבחי' פרזות תשב ירושלים (פרזונו).\nד) <b>ויובן</b> זה ע\"פ מארז\"ל<sup data-n=\"676\">25</sup> שכל מה שיש בעולם יש באדם [שלכן נקרא האדם עולם קטן<sup data-n=\"677\">26</sup>, וכאו\"א חייב לומר בשבילי נברא העולם<sup data-n=\"678\">27</sup>]. ומזה מובן, שבאדם, אתם קרויין אדם<sup data-n=\"679\">28</sup>, יש בחי' ירושלים. והיינו, שגם בזמן הגלות כשמפני חטאינו גלינו מארצנו ונתרחקנו מעל <i>אדמתנו</i><sup data-n=\"680\">29</sup> [שענין זה (<i>גלינו</i> מארצנו <i>ונתרחקנו</i> מעל <i>אדמתנו</i>) הוא גם בבנ\"י הנמצאים בארץ הקודש תובב\"א<sup data-n=\"681\">30</sup>], מ\"מ, ענין ירושלים ברוחניות הוא נצחי גם עכשיו, בכאו\"א מישראל. והענין הוא, דהנה ידוע<sup data-n=\"682\">31</sup> שירושלים פירושו הוא יראה שלם [וענין זה הוא גם בנוגע לעיר ירושלים כפשוטה, כדאיתא בתוספות<sup data-n=\"683\">32</sup> בשם המדרש<sup data-n=\"684\">33</sup> ששם ירושלים הוא על שם שלם שקראה מלכי צדק מלך שלם ועל שם יראה שקראה אברהם], שהוא שלימות היראה. וזהו שירושלים הרוחנית היא נצחית גם עכשיו בזמן הגלות, כי בכאו\"א מישראל גם בזמן הגלות יש (בהעלם עכ\"פ) שלימות היראה, כדלקמן.\n<b>ויובן</b> זה בהקדים, דבענינה של ירושלים (שלימות היראה) בעבודת האדם, שני פירושים. דבכ\"מ<sup data-n=\"685\">34</sup> מבואר שירושלים היא היראה כמו שבאה בציור דיראה, וזהו\"ע ירושלים של מטה וירושלים של מעלה, כי ביראה יש בכללות שתי מדריגות, יראה תתאה – ירושלים של מטה, ויראה עילאה – ירושלים של מעלה. וזהו אמר הקב\"ה לא אבוא בירושלים של מעלה עד שאבוא לירושלים של מטה<sup data-n=\"686\">35</sup>, דהגם שמצדהגילויים יראה תתאה היא למטה מטה לגבי יראה עילאה, מ\"מ, כיון שיראה תתאה שרשה מיראה עילאה<sup data-n=\"687\">36</sup>, ועד ששניהם חד הוא<sup data-n=\"688\">37</sup>, לכן, ע\"י יראה תתאה (ירושלים של מטה) מגיעים ליראה עילאה (ירושלים של מעלה)<sup data-n=\"689\">38</sup>. ומהמשך הענינים שבמאמר זה מובן<sup data-n=\"690\">39</sup>, דירושלים הוא נקודת היראת שמים שלמעלה מהשכל, נקודה שלמעלה מציור, שישנה בכאו\"א מישראל, מצד עצם הנשמה שבו שלמעלה מגילויים<sup data-n=\"691\">40</sup>. ויש לומר, דמהטעמים על זה שנקודה זו נקראת בשם ירושלים, שלימות היראה, הוא, כי אמיתית ענין השלימות הוא <i>שאין שייך</i> שיהי' בו חסרון. ולכן, היראה כמו שבאה בגילוי (בציור דיראה), כיון שאפשר שיהי' בה חסרון, אין בה אמיתית השלימות, ואמיתית השלימות היא בנקודת היראת שמים שלמעלה מגילוי, דנקודה זו ישנה תמיד בכאו\"א מישראל.\nה) <b>והנה</b> אף שנקודת היראת שמים שלמעלה מהשכל היא למעלה מהגבלה, מ\"מ, יש בה (בהתגלותה) כו\"כ מדריגות, ואמיתית הבל\"ג שבה יהי' לעתיד לבוא. וזהו שלע\"ל (דוקא) יהי' פרזות תשב ירושלים, ופי' רש\"י<sup data-n=\"692\">41</sup> שלא יהא לה קצב ושיעור כו'. וגם אז יהיו בה עליות לאין קץ, כמ\"ש רש\"י<sup data-n=\"692\">41</sup> שתגדל מיום ליום. וזהו צדקת פרזונו בישראל כו' צדקה עשה הקב\"ה בישראל שפיזרן לבין האומות, דזה שנאמר בכתוב ענין זה (צדקה כו' שפיזרן כו') בלשון פרזונו הוא, כי הצדקה שעשה הקב\"ה בישראל ע\"י שפיזרן לבין האומות הוא שעי\"ז יגיעו לפרזונו שלמעלה ממדידה והגבלה. ושני ענינים בזה. שע\"י המניעות ועכובים שבזמן הגלות (פיזרן לבין האומות) מתעוררת ומתגלה נקודת היראת שמים שבכל אחד מישראל (כמבואר בארוכה בהמאמר<sup data-n=\"693\">42</sup>) שהיא למעלה ממדידה והגבלה. ויתירה מזו, דענין פרזונו רומז (כמובא לעיל סעיף ג מהמאמר) על פרזות תשב ירושלים, שע\"י התעוררות נקודת היראת שמים בזמן הגלות, תהי' אח\"כ הוספה ועלי' בנקודת היראת שמים, הבל\"ג שבה כמו שיהי' לע\"ל.\nו) <b>ויש</b> לומר, דבפרזות תשב ירושלים (נקודת היראת שמים) שני ענינים. שנקודת היראת שמים עצמה היא למעלה מהגבלה (כנ\"ל סעיף ה), וגם התפשטותה<sup data-n=\"694\">43</sup> היא בלי גבול. ובזה גופא שני ענינים. שנקודת היראת שמים פועלת בכל כחות הנפששיהיו בהתאם להנקודה, ושגם הנקודה עצמה מתפשטת בכל כחות הנפש<sup data-n=\"695\">44</sup>, עד בהלבושים דמחשבה דיבור ומעשה. ובדוגמת פרזות תשב ירושלים כפשוטה, דנוסף לזה שירושלים היא נקודה דאמצעו של העולם ומאבן שתי' שבבית המקדש הושתת כל העולם<sup data-n=\"696\">45</sup>, הנה גם ירושלים עצמה תתפשט בכל העולם, דעתידה ירושלים שתתפשט בכל ארץ ישראל ועתידה ארץ ישראל שתתפשט בכל הארצות<sup data-n=\"697\">46</sup>.\nז) <b>ולכאורה</b> יש להוסיף, דזה שנאמר פרזונו (ולא פזרונו), ענין פרזות תשב ירושלים, שייך גם להצדקה שפיזרן שמבאר בתחלת המאמר, שעסק התומ\"צ של ישראל הנמצאים במקומות הרווחה נותן כח ועוז לישראל הנמצאים במקום הגזירה שיוכלו ללמוד תורה ולקיים מצוות. כי זה שעסק התומ\"צ של אחד נותן כח ועוז לשני הוא לפי שכל ישראל הם מציאות אחת, בפרט מצד נקודת היראת שמים והביטול שבהם, שהיא נקודה המאחדת את כל ישראל. ולכן, בכדי שהעסק דתומ\"צ של אחד יתן כח ועוז לאחר (ענין הצדקה בזה שפיזרן) הוא כשעסק התומ\"צ שלו הוא בהנקודה דיראת שמים, פרזות תשב ירושלים, שהיראת שמים שלו (ירושלים) היא באופן דופרצת<sup data-n=\"698\">47</sup> ימה וקדמה וצפונה ונגבה, שמתפשטת וחודרת בכל כחות הנפש, עד במחשבה דיבור ומעשה שלו.\n<b>ויש</b> לומר שזהו גם הטעם על זה שהעסק בתומ\"צ של אחד נותן כח ועוז (לא רק לאלה הנמצאים במקום הגזירה, אלא) גם לאלו השבויים בידי יצרם, לפדות אותם מהשבי' (כנ\"ל סעיף ב), כי בכאו\"א מישראל, אפילו ברשעים, יש (בהעלם עכ\"פ) נקודת היראת שמים, ולכן כל הסוגים דישראל (צדיקים בינונים ורשעים) הם מציאות אחת. וכמרומז גם בתיבת צבור (שישראל הם צבור<sup data-n=\"699\">48</sup>), צבור ר\"ת <i>צ</i>דיקים <i>ב</i>ינונים <i>ור</i>שעים<sup data-n=\"700\">49</sup>, שכל ג' סוגים אלו הם מציאות אחת [והוא\"ו (שבתיבת צבור) הוא וא\"ו המחבר את הרשעים עם הבינונים והצדיקים, ועד שהראש של כל התיבה הוא אות צדי\"ק, ועמך<sup data-n=\"701\">50</sup> כולם צדיקים]. ולכן עסק התומ\"צ של הצדיקים והבינונים [ובפרט כשעסק התומ\"צ שלהם הוא באופן שהם כוללים עצמם עם כל ישראל<sup data-n=\"702\">51</sup>, ואהבת לרעך כמוך<sup data-n=\"703\">52</sup>] פועל גם על אלו השבויים בידי יצרם, שיצאו מהשבי' ויהיו צדיקים (גם בגלוי).ח) <b>והנה</b> ענין הנ\"ל (שהעסק דתומ\"צ של אחד נותן כח ועוז גם לשני) הוא לא רק כשהאונס (בנוגע לאיזו מצוה) הוא מפני גזירת המלכות או מפני שיצרו הוא שתקפו, אלא גם כשהאונס הוא מפני שע\"פ תורה א\"א לקיים מצוה זו, וכמו ישראל הנמצאים בחו\"ל שע\"פ תורה א\"א להם לקיים את המצוות התלויות בארץ, ועד\"ז בכללות זמן הגלות שא\"א (גם לבנ\"י הנמצאים בא\"י) לקיים מצוות התלויות בזמן שביהמ\"ק הי' קיים, הנה מצד זה שכל ישראל שבכל המקומות ושבכל הזמנים הם מציאות אחת, לכן עי\"ז שבנ\"י הנמצאים בא\"י מקיימים את המצוות התלויות בארץ, מועיל זה גם עבור בנ\"י הנמצאים בחו\"ל, ועד\"ז הוא בנוגע להמצוות התלויות בזמן הבית שקיימו ישראל אז, שזה מועיל גם לבנ\"י שבזמן הגלות, כיון שכל ישראל שבמשך כל הדורות הם צבור אחד דאין מיתה בצבור<sup data-n=\"704\">53</sup> [שלכן הקרבן שהקריבו בימי עזרא כיפר גם על ישראל שהיו בדורו של צדקיהו<sup data-n=\"705\">54</sup>].\nט) <b>וזהו</b> צדקת פרזונו בישראל צדקה כו' שפיזרן לבין האומות, דזה שנאמר פרזונו (ולא פזרונו) הוא, כי צדקה שעשה הקב\"ה בישראל שפיזרן לבין האומות הוא שעי\"ז יגיעו לע\"ל לפרזות תשב ירושלים (כנ\"ל בארוכה). ועוד טעם על זה שנאמר פרזונו הוא, כי בכדי לבוא לפרזות תשב ירושלים הוא ע\"י שגם העבודה בזמן הגלות (כשפיזרן לבין האומות) היא באופן דפרזות תשב ירושלים. דנוסף לזה שהכניסה לירושלים בגשמיות, בגאולה האמיתית ע\"י משיח צדקנו, היא ע\"י העבודה דירושלים, שלימות היראה [כי ביאת המשיח תהי' ע\"י בקולו תשמעו<sup data-n=\"706\">55</sup>, שזה (ענין בקולו תשמעו) הוא ע\"י היראה, שהיא ראשית העבודה ועיקרה ושרשה<sup data-n=\"707\">56</sup>, דהגם שבכדי שקיום התומ\"צ יהי' בשלימות צריך גם לאהבה<sup data-n=\"708\">57</sup>, הרי עיקר העבודה היא היראה<sup data-n=\"709\">58</sup>], הנה בכדי שיהי' פרזות תשב ירושלים, צריכה להיות העבודה גם עכשיו באופן של פרזות, למעלה ממדידה והגבלה, שבכללות היא העבודה דמסירת נפש, מסירת הרצון<sup data-n=\"710\">59</sup>, שעבודה זו היא הכנה קרובה שיהי' פרזות תשב ירושלים גם כפשוטו, עתידה ירושלים שתתפשט בכל ארץ ישראל ועתידה ארץ ישראל שתתפשט בכל הארצות. שזה נעשה (ככל הענינים דלעתיד<sup data-n=\"711\">60</sup>) ע\"י מעשינו ועבודתנו במשך זמן הגלות, שכללותם הם הג' קוין דתורה עבודה וגמ\"ח [וכמארז\"ל במסכת ברכות בתחלתה ובראשיתה<sup data-n=\"712\">61</sup> עה\"פ<sup data-n=\"713\">62</sup>פדה בשלום נפשי מקרב לי כי ברבים היו עמדי, כל העוסק בתורה ובגמ\"ח ומתפלל עם הצבור מעלה אני עליו כאילו פדאני לי ולבני מבין אומות העולם], ובפרט ע\"י העבודה דיפוצו מעינותיך חוצה שעי\"ז אתי מר דא מלכא משיחא [כמ\"ש באגה\"ק של הבעש\"ט<sup data-n=\"714\">63</sup> מה ששמע בהיכל המשיח, ממלכא משיחא].\n<b>וזהו</b> צדקה כו' שפיזרן לבין האומות, שע\"י מעשינו ועבודתנו בזמן הגלות (בג' הקוין דתורה עבודה וגמ\"ח ובפרט בהפצת המעינות חוצה) שבכל יום ויום, הנה נוסף על זה שבכל יום ויום (כשנמצאים עדיין בגלות) נעשה הפדי' ברוחניות (<i>כאילו</i> פדאני), הנה כל פעולה ופעולה בהנ\"ל מצטרפת לחשבון גדול של הצדקה<sup data-n=\"715\">64</sup> שמקרבת את הגאולה<sup data-n=\"716\">65</sup> כפשוטה בגשמיות, שאז יהי' פרזות תשב ירושלים גם בגשמיות, בביאת משיח צדקנו, בקרוב ממש.\n**********",[["651","*","יצא לאור ב<b>קונטרס י\"ט כסלו – תש\"נ</b>, \"לקראת חג הגאולה י\"ט כסלו הבעל\"ט, יום גאולת כ\"ק אדמו\"ר הזקן ממאסרו (בשנת תקנ\"ט) . . <i>טו כסלו שנת ה'תש\"נ</i>\". \"המאמר מיוסד על ד\"ה זה די\"ט כסלו שנדפס בקונטרס דרושי חתונה תרפ\"ט\"."],["652","1","ספר שופטים ה, יא."],["653","2","פסחים פז, ב."],["654","3","השייכות דפסוק זה (צדקת פרזונו גו') לי\"ט כסלו, וכן הטעם שמביא בהמאמר את בעל המאמר (ר' אושעיא) – נתבאר בד\"ה זה די\"ט כסלו ה'תשמ\"ח (תורת מנחם – דרושי חתונה ע' רס ואילך)."],["655","4","קונטרס ב – נדפס בסה\"מ קונטרסים ח\"א, והו\"ל עוה\"פ ז\"ע (בשנת תשל\"ט) בקונטרס בפ\"ע. – ראה סה\"מ שם לב, סע\"ב ואילך. סה\"מ תרפ\"ט ע' 113 ואילך."],["656","5","הלשון והגדר דאונס הוא גם כשיש לו אפשרות לקיים ע\"י מס\"נ – ראה רמב\"ם הל' יסוה\"ת פ\"ה. ובכ\"מ. אבל אונס <i>ממש</i> הוא כשאין אפשרות אפילו ע\"י מס\"נ, כבפנים."],["657","6","להעיר מר\"ן לשבת פ\"ד (מט, א) ד\"ה ומקשו (הובא בכס\"מ שם רפ\"ה) \"שהן יכולין לבטלה ממנו <i>על כרחו</i>\"."],["658","7","ראה נו\"כ הרמב\"ם שם ה\"ד. טור ושו\"ע יו\"ד ר\"ס קנז. ובנו\"כ שם."],["659","8","בד\"ה א\"ר אושעיא הנ\"ל, שהנתינת כח היא ש\"יתעוררו בהתעוררות גדולה כו' במס\"נ שלא לשמוע להמנגד כו'\". ויש לומר, שזהו רק בתחלה, ומזה נמשך שאח\"כ לא יצטרכו למס\"נ, כבפנים."],["660","9","אבות פ\"ד משנה ט."],["661","10","ד\"ה א\"ר אושעיא הנ\"ל (סה\"מ שם לג, א). וראה גם <a class=\"ft-cite\" href=\"#/read/tanya/3401310022\" data-slug=\"tanya\" data-id=\"3401310022\">תניא רפי\"ז</a>. מאמרי אדמו\"ר האמצעי בראשית ע' צג (וש\"נ). <i>ובכ\"מ</i>."],["662","11","בד\"ה כל הנהנה תרפ\"ט ס\"י (סה\"מ שם כז, א)."],["663","12","אבל לא אנוס ממש, אפילו לא הגדר דאונס שברוב המקומות שיש לו אפשרות לקיים ע\"י מס\"נ (ראה לעיל הערה 5), כי \"רשות לכל אדם נתונה . . ואין לו מי שיכפה\" (רמב\"ם הל' תשובה פ\"ה ה\"א-ב), וי\"ל שלכן מדייק הרמב\"ם (בהל' גירושין ספ\"ב) \"יצרו הוא <i>שתקפו</i>\" ולא \"שאנסו\".\nועפ\"ז מובן גם זה שנפרעין מאדם העובר עבירה – אף שאונס רחמנא פטרי' (ב\"ק כח, סע\"ב. וש\"נ) והעובר באונס (אפילו העובד ע\"ז באונס) אין מענישים אותו (רמב\"ם הל' יסוה\"ת פ\"ה ה\"ד) – כי \"תקפו\" אינו אונס."],["664","13","הל' גירושין שם."],["665","14","ברכות ה, ב. וש\"נ."],["666","15","בהבא לקמן ראה בארוכה לקו\"ש ח\"ג ס\"ע 747 ואילך."],["667","16","להעיר מלקו\"ד כרך א טו, א-ב."],["668","17","סנהדרין קב, ב ובפרש\"י שם ד\"ה הוית."],["669","18","יומא סט, ב. סנהדרין סד, א."],["670","19","ראה אגה\"ק סוף ס\"ז. ד\"ה זה היום תרפ\"ח (תש\"ח) ס\"ב-ג (סה\"מ תרפ\"ח ע' קנד ואילך. ה'תש\"ח ע' 240 ואילך), ובהערה שם. ובכ\"מ."],["671","20","שבת קיח, ב."],["672","21","רמב\"ם הל' מתנות עניים פ\"ח ה\"י. טושו\"ע יו\"ד ר\"ס רנב. – ע\"פ ב\"ב ח, ריש ע\"ב."],["673","22","ד\"ה א\"ר אושעיא הנ\"ל ספ\"ג (סה\"מ קונטרסים שם לד, ריש ע\"ב). וראה גם רד\"ה זה באוה\"ת בשלח (ע' תרע), תרכ\"ז (סה\"מ תרכ\"ו ע' שכח) ותרכ\"ט (סה\"מ תרכ\"ט ע' נב)."],["674","23","ד\"ה א\"ר אושעיא תרפ\"ט הנ\"ל בסופו (סה\"מ קונטרסים שם לח, א). וראה גם ד\"ה הנ\"ל ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316520337\" data-slug=\"or-hatorah-hb\" data-id=\"8316520337\">אוה\"ת שם (ע' תרפא</a>), תרכ\"ז (סה\"מ שם ע' של) ותרכ\"ט (סה\"מ שם ע' נד)."],["675","24","זכרי' ב, ח."],["676","25","אדר\"נ ס\"פ לא. וראה גם קה\"ר פ\"א, ד (קרוב לסופו). מדרש תהלים יט, א. תנחומא באָבער וארא יח."],["677","26","תנחומא פקודי ג. תקו\"ז תס\"ט (ק, ב. קא, א). וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380328\" data-slug=\"likkutei-torah\" data-id=\"4001380328\">לקו\"ת במדבר ה, סע\"א</a>. סה\"מ תרנ\"ט ע' נט. ד\"ה כי עמך הסליחה תרפ\"ג (תש\"ט) פ\"ה (סה\"מ תרפ\"ג ע' רמז. ה'תש\"ט ע' 218). ועוד."],["678","27","סנהדרין לז, סע\"א במשנה."],["679","28","יבמות סא, רע\"א."],["680","29","בתפלת מוסף דיו\"ט."],["681","30","כדמוכח גם מזה שלשון זה בתפלת מוסף דיו\"ט \"גלינו מארצנו ונתרחקנו מעל אדמתנו\" הוא גם באה\"ק תובב\"א."],["682","31","ראה בארוכה ד\"ה א\"ר אושעיא תרפ\"ט הנ\"ל פ\"ו (סה\"מ קונטרסים שם לו, א ואילך). וראה גם ד\"ה הנ\"ל תרכ\"ז (סה\"מ שם ע' של) ותרכ\"ט (סה\"מ שם ע' נז)."],["683","32","ד\"ה הר – תענית טז, א. הובא במקומות שבהערה הקודמת."],["684","33","ב\"ר פנ\"ו, י."],["685","34","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380840\" data-slug=\"likkutei-torah\" data-id=\"4001380840\">לקו\"ת בשלח ד, א</a>. ראה לא, א."],["686","35","תענית ה, א. וראה בהנסמן בשערי זהר (להר\"ר ראובן מרגליות) לתענית שם."],["687","36","ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370512\" data-slug=\"torah-or\" data-id=\"3901370512\">תו\"א קיד, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380835\" data-slug=\"likkutei-torah\" data-id=\"4001380835\">לקו\"ת ראה כט, ד</a>. ביאוה\"ז לאדמו\"ר האמצעי אמור פא, א-ב. דרך חיים שער התפלה נז, ג. מאמרי אדמו\"ר האמצעי דברים ח\"ב ריש ע' תרנט. ביאוה\"ז להצ\"צ שם כרך א ע' תכג. קונטרס העבודה פ\"ג (ע' 18)."],["688","37","ראה ביאוה\"ז ודרך חיים שם."],["689","38","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380840\" data-slug=\"likkutei-torah\" data-id=\"4001380840\">לקו\"ת ראה שם לא, א</a>."],["690","39","ראה שם פ\"ו (סה\"מ קונטרסים שם לו, א ואילך) השייכות דנצח (והנצח זו בנין ירושלים – ברכות נח, סע\"א) לאוצר, ובהמשך לזה בספ\"ז (סה\"מ שם לז, ב) שאוצר של יראת שמים (ראה שבת לא, ב. ברכות לג, ב) הוא נקודת היראת שמים."],["691","40","ראה ד\"ה ועתה ישראל גו' דכ\"ף מנחם-אב ה'תשל\"ז סעיף ד, ובהערה 29 שם (לקמן ח\"ד ע' רי)."],["692","41","הובא בסד\"ה א\"ר אושעיא תרפ\"ט הנ\"ל (סה\"מ קונטרסים שם לח, סע\"א)."],["693","42","פ\"ו ואילך (סה\"מ שם לו, א ואילך)."],["694","43","ראה <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540899\" data-slug=\"torat-chaim\" data-id=\"2300540899\">תו\"ח</a> בשלח ד\"ה צדקת פרזונו (שמ, סע\"ב ואילך [בהוצאה החדשה – בשלח ח\"א רלד, א]) ש\"פרזות תשב ירושלים\" הו\"ע עתידה ירושלים שתתפשט כו'."],["695","44","וע\"ד המבואר בכ\"מ (המשך תרס\"ו ע' תצד. ועוד) בענין האהבה דבכל נפשך, שהאהבה היא לא רק בלב אלא מתפשטת בכל הכחות והאיברים."],["696","45","ראה משנה יומא נג, ב ובגמרא שם נד, ב. וראה בהנסמן בשערי זהר ליומא שם נד, ב. ר\"ה כג, א. תנחומא קדושים י."],["697","46","ראה פס\"ר פ' שבת ור\"ח. יל\"ש ישעי' רמז תקג. וראה גם ספרי דברים בתחלתו. שהש\"ר פ\"ז, ד (ג). וראה גם בהנסמן ב\"מראי מקומות\" ל<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380681\" data-slug=\"likkutei-torah\" data-id=\"4001380681\">לקו\"ת מסעי פט, ב</a> (עג, א)."],["698","47","ויצא כח, יד."],["699","48","ראה נזיר סא, ריש ע\"ב ש\"קהל\" (צבור) הוא דוקא בישראל. ובצפע\"נ מהדו\"ת (יג, ב. צ, ב) שזהו לפי שישראל הם מציאות אחת משא\"כ ב\"נ."],["700","49","ככר לאדן (להחיד\"א) סי' ז בפירוש המשנה (אבות פ\"ב מ\"ד) אל תפרוש מן הצבור. דברים אחדים (להנ\"ל) דרוש כב (שבת הגדול) קטו, ג. [קהלת יעקב ערך שליח צבור (השני)]."],["701","50","ישעי' ס, כא."],["702","51","להעיר מ<a class=\"ft-cite\" href=\"#/read/tanya/3401310046\" data-slug=\"tanya\" data-id=\"3401310046\">תניא פמ\"א (נז, ב</a>)."],["703","52","קדושים יט, יח. וראה מאמרי אדה\"ז על פרשיות התורה כרך ב ע' תקצב, ובהנסמן במ\"מ לשם (תתקמא, ב)."],["704","53","הוריות ו, א. וראה מכתבי תורה (להרוגוצ'ובי) מכתב קמז. קמט."],["705","54","הוריות שם, ובפרש\"י שם ד\"ה ראוי' כפרה זו."],["706","55","סנהדרין צח, סע\"א."],["707","56","<a class=\"ft-cite\" href=\"#/read/tanya/3401310046\" data-slug=\"tanya\" data-id=\"3401310046\">תניא רפמ\"א</a>."],["708","57","<a class=\"ft-cite\" href=\"#/read/tanya/3401310009\" data-slug=\"tanya\" data-id=\"3401310009\">תניא פ\"ד</a>. וראה קונטרס העבודה פ\"ב (ע' 15). וראה גם <a class=\"ft-cite\" href=\"#/read/tanya/3401310044\" data-slug=\"tanya\" data-id=\"3401310044\">תניא פל\"ט (נג, ב</a>)."],["709","58","וי\"ל דהאהבה היא בכדי שתהי' לו חיות בעבודתו וכיו\"ב. משא\"כ בלי יראה, חסר בעצם העבודה – ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310046\" data-slug=\"tanya\" data-id=\"3401310046\">תניא פמ\"א (נו, סע\"ב</a> ואילך). וראה לקמן ח\"ד ע' רכד הערה 13."],["710","59","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370166\" data-slug=\"torah-or\" data-id=\"3901370166\">תו\"א מקץ לו, ב</a>. <i>ובכ\"מ</i>."],["711","60","<a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא רפל\"ז</a>."],["712","61","ח, א."],["713","62","תהלים נה, יט. וראה אוה\"ת (יהל אור) להצ\"צ עה\"פ.\nשייכות פסוק זה לגאולת אדה\"ז בי\"ט כסלו – ראה אגרות-קודש אדה\"ז (ח\"א) סי' לח. וש\"נ. וראה ד\"ה פדה בשלום ה'תשל\"ח בתחלתו (לקמן ע' קמב)."],["714","63","נדפסה גם בכתר שם טוב (הוצאת קה\"ת) בתחלתו."],["715","64","ע\"פ מחז\"ל (ב\"ב ט, ב) בנוגע לצדקה: כל פרוטה ופרוטה מצטרפת לחשבון גדול."],["716","65","ב\"ב שם י, א."]]],[1500370011,"<h3>בס\"ד. ש\"פ וישלח, י\"ד כסלו ה'תשמ\"א<sup data-n=\"717\">*</sup></h3>\n<b>וכל</b> בניך לימודי הוי' ורב שלום בניך<sup data-n=\"718\">1</sup>, ומביא כ\"ק מו\"ח אדמו\"ר במאמרו ד\"ה זה<sup data-n=\"719\">2</sup> (שבקונטרס דרושי חתונה תרפ\"ט<sup data-n=\"720\">3</sup>), דבורב שלום בניך שני פירושים. הא', דפירוש ורב שלום בניך הוא שיהי' רוב שלום לבניך, כפירוש המצודת דוד והתרגום. והב', דפירוש ורב שלום בניך הוא שע\"י בניך נעשה ריבוי שלום בעולם, כמאמר רז\"ל<sup data-n=\"721\">4</sup> תלמידי חכמים מרבים שלום בעולם שנאמר וכל בניך לימודי הוי' ורב שלום בניך אל תקרי בניך אלא בוניך. ומבאר בהמאמר, דזה מה שתלמידי חכמים נק' בוניך הוא כמארז\"ל<sup data-n=\"722\">5</sup> מאי בנאין אלו תלמידי חכמים שעוסקין בבנינו של עולם. ומזה מובן, דזה שתלמידי חכמים מרבים שלום בעולם הוא לא מצד המעלה דתלמידי חכמים (לימוד התורה) כמו שהיא מצד עצמה, אלא עי\"ז שהם עוסקים בבנינו של עולם, שע\"י עסקם בתורה נעשה הבירור דעולם. וזהו וכל בניך לימודי הוי' ורב שלום בניך, שמבאר כאן שני ענינים. וכל בניך לימודי הוי', דפירוש לימודי הוי' הוא דאלפין באורייתא דהוי'<sup data-n=\"723\">6</sup> – המעלה דתלמידי חכמים מצד עצמם, ואח\"כ מוסיף ורב שלום בניך א\"ת בניך אלא בוניך, הבירור דעולם (בוניך) וריבוי השלום בעולם, שנעשה ע\"י עסק התורה. ובסיום המאמר<sup data-n=\"724\">7</sup>, דע\"י הענין דורב שלום בניך א\"ת בניך אלא בוניך, בנאים העוסקים בבנינו של עולם, עי\"ז יקויים גם בהם ורב שלום בניך, כמ\"ש<sup data-n=\"725\">8</sup> וראה בנים לבניך שלום על ישראל, היינו, דע\"י הבירור דעולם שנעשה ע\"י עסק התורה דהתלמידי חכמים, נמשך ריבוי שלום גם להתלמידי חכמים עצמם (כפירוש המצודות והתרגום בורב שלום בניך).\nב) <b>ויש</b> לקשר זה עם מ\"ש בריש פרשתנו<sup data-n=\"726\">9</sup> וישלח יעקב מלאכים לפניו אל עשו אחיו גו' כה תאמרון גו' עם לבן גרתי ואחר עד עתה, דמשמעות הכתוב הוא שיעקב צריך לבוא תחלה אל עשו, ולכן נתן טעם על זה שנתאחר לבוא אליו,עם לבן גרתי (ולכן<sup data-n=\"727\">10</sup>) ואחר עד עתה. וצריך להבין<sup data-n=\"728\">11</sup> למה צריך למהר לבוא אל עשו ועד שצריך לטעם על זה שנתאחר. וגם צריך להבין<sup data-n=\"729\">12</sup> מה שפירש רש\"י גרתי בגימטריא תרי\"ג, עם לבן גרתי ותרי\"ג מצוות שמרתי, הרי יעקב ידע שעשו אינו מייקר ענין קיום המצוות, ומה מודיע לו ששמר תרי\"ג מצוות. והנה ידוע הביאור בזה<sup data-n=\"730\">13</sup>, דהברכות שברך יצחק את יעקב הן בכדי לברר את עשו, אלא בכדי שיוכל לברר את עשו הי' צ\"ל תחלה עבודתו בבית לבן. וזהו מה שאמר יעקב עם לבן גרתי ואחר עד עתה, דהטעם על שנתאחר ללכת לעשו לבררו עד עתה (אף שלכאורה הוצרך לבררו תיכף לאחרי שקיבל הברכות) הוא כי (עד עכשיו) עם לבן גרתי ותרי\"ג מצוות שמרתי, ולאחרי שגמר עבודתו בבית לבן, שלח מיד אל עשו לבררו.\nג) <b>והנה</b> הטעם על זה שבכדי לברר את עשו צריך להיות תחלה עבודתו בבית לבן, מבואר בכמה דרושים<sup data-n=\"731\">14</sup> ובארוכה בד\"ה וישלח שבהמשך תער\"ב<sup data-n=\"732\">15</sup>, דשני ענינים בזה. הא', שבכדי לברר את עשו הוצרך לאור נעלה ביותר, ולכן צריך להיות תחלה עבודתו בבית לבן, בחינת לובן העליון שלמעלה מהשתלשלות<sup data-n=\"733\">16</sup>. ולאחרי שע\"י עבודתו בבית לבן במשך עשרים שנה המשיך כל האורות דבחי' לובן העליון, ועד לענין דוישכם לבן בבוקר וינשק לבניו ולבנותיו גו'<sup data-n=\"734\">17</sup>, ההמשכה דלובן העליון בבחי' נשיקין ואתדבקות רוחא ברוחא לכל עניני יעקב (להמשפיעים ולהמקבלים, בניו ובנותיו)<sup data-n=\"735\">18</sup>, הי' ביכלתו לברר את עשו<sup data-n=\"736\">19</sup>. והב', שהצורך בהקדמת העבודה בבית לבן כדי לברר את עשו הוא (לא רק מצד השרש דלבן, לובן העליון, אלא גם) מצד לבן שלמטה, לבן דקליפה. דעשו הוא למטה מלבן, דלבן הוא כח\"ב דק\"נ ועשו הוא ז\"מ דק\"נ<sup data-n=\"737\">20</sup>, ולכן צריך תחלה לברר את לבן, ואח\"כ הלך לברר את עשו<sup data-n=\"738\">21</sup>.\nד) <b>והענין</b> הוא, דהבירורים דיעקב היו בכלל בדרך מלמעלה למטה, ע\"י גילוי אור עליון. כי יעקב הוא תורה [כידוע<sup data-n=\"739\">22</sup> שג' האבות הם ג' הקוין תורהעבודה וגמ\"ח, אברהם – גמ\"ח, יצחק – עבודה, ויעקב – תורה], והבירור שע\"י התורה הוא בדרך מלמעלה למטה, כמשנת\"ל בד\"ה פדה בשלום<sup data-n=\"740\">23</sup> בענין החילוק שבין הבירור דתפלה להבירור דתורה, שהבירור דתפלה הוא בדרך מלמטה למעלה (שמתעסק עם המתברר), והבירור דתורה הוא בדרך מלמעלה למטה. דהחילוק שבין שני ענינים אלו אינו רק באופן הבירור, אלא גם בסדר הבירור<sup data-n=\"741\">24</sup>. דבהבירור שבאופן דמלמטה למעלה (שמתעסק עם המתברר) גם סדר הבירור הוא מלמטה למעלה, שבתחלה מברר התחתון ואח\"כ העליון, והבירור באופן דמלמעלה למטה (ע\"י גילוי אור מלמעלה) הוא בסדר דמלמעלה למטה. ולכן, בהבירורים עכשיו, שהם (בעיקר) באופן דמלמטה למעלה, הסדר הוא שהבירור דז' תחתונות הוא לפני הבירור דג' ראשונות, וזהו מה שבתחלה הי' הכיבוש דארץ ז' עממין ואח\"כ (לע\"ל) יהי' הכיבוש דקיני קניזי וקדמוני, וידוע הביאור דבעל הגאולה דיו\"ד כסלו<sup data-n=\"742\">25</sup> [שהעלי' דיו\"ד כסלו היא ביום השבת שלאחריו<sup data-n=\"743\">26</sup>] דבכיבוש יהושע נתבררו רק ז' המדות (והמוחין השייכים למדות), וג\"ר יתבררו לעת\"ל, משא\"כ בהבירורים דיעקב, שהיו בדרך מלמעלה למטה, הי' הסדר שבתחילה בירר כח\"ב (לבן) ואח\"כ ז\"מ (עשו)<sup data-n=\"744\">27</sup>.\nה) <b>והנה</b> ידוע, דהגם שבכלל הבירור בדרך מלמעלה למטה הוא נעלה יותר מהבירור בדרך מלמטה למעלה, יש יתרון בהבירור בדרך מלמטה למעלה על הבירור בדרך מלמעלה למטה<sup data-n=\"745\">28</sup>, דהבירור בדרך מלמעלה למטה, כיון שהבירור הוא מצד הגילוי אור (ולא מצד התחתון גופא), אין זה שייך כ\"כ להתחתון עצמו, משא\"כ בהבירור בדרך מלמטה למעלה, התחתון עצמו נעשה כלי לאלקות<sup data-n=\"746\">29</sup>. וזהו מה שגם לאחרי שיעקב פעל הבירור דעשו, ועד אשר וירץ עשו לקראתו ויחבקהו גו' וישקהו<sup data-n=\"747\">30</sup>, אמר לו<sup data-n=\"748\">31</sup> ואני אתנהלה לאטי גו' עד אשר אבוא אל אדוני שעירה, ואימתי ילך בימי המשיח, שנאמר<sup data-n=\"749\">32</sup> ועלו מושיעים בהר ציון לשפוט את הר עשו<sup data-n=\"750\">33</sup>, כי הבירור דעשו שנעשה ע\"י יעקב הי' ע\"י גילוי אור מלמעלה (כנ\"ל), ולכן לא הי' הבירור בשלימות<sup data-n=\"751\">34</sup>, ושלימות הבירור שלו בימי המשיח הוא ע\"י מעשינו ועבודתינו במשך זמן הגלות<sup data-n=\"752\">35</sup>, בירור בדרך מלמטה למעלה. ויש לומר, דזה שהי' תחלה הבירור שלוע\"י יעקב בדרך מלמעלה למטה הוא נתינת כח שיוכל להיות אח\"כ הבירור בדרך מלמטה למעלה.\nו) <b>וצריך</b> להבין, הרי התורה היא נצחית<sup data-n=\"753\">36</sup>, וכל הסיפורים וההוראות שבתורה הם הוראות נצחיות, ומכיון שהעבודה עכשיו היא בדרך מלמטה למעלה, למה נכתב בתורה, ובאריכות, הסיפור דוישלח יעקב גו' אל עשו, שתוכנו הוא בירור מלמעלה למטה. וביותר צריך ביאור מה שמסופר בתורה (שהיא נצחית) גם סדר הבירור דיעקב, הבירור דג\"ר (לבן) לפני הבירור דז\"ת (עשו). ויש לומר הביאור, דזה שאצל יעקב אבינו הי' הבירור בדרך מלמעלמ\"ט הוא (ככל מעשה אבות<sup data-n=\"754\">37</sup> שהם) סימן ונתינת כח לבנים<sup data-n=\"755\">38</sup> על עבודה זו גופא. והיינו, דנוסף על זה שהבירור דיעקב בדרך מלמעלה למטה הוא נתינת כח על הבירור בדרך מלמטה למעלה (עיקר הבירור דעכשיו), הוא נתינת כח גם על ענין הבירור בדרך מלמעלה למטה דבנים, הבירור שע\"י תורה. ובתורה גופא – הבירור שע\"י פנימיות התורה, דעיקר ענין הבירור בדרך מלמעלה למטה הוא בפנימיות התורה. וכמשנת\"ל (בד\"ה פדה בשלום<sup data-n=\"756\">39</sup>) בארוכה, דהבירור שע\"י נגלה דתורה, מכיון שנתלבשה בעה\"ד טו\"ר בכדי לברר בירורים, הוא דוגמת הבירור בדרך מלמטה למעלה, בהתלבשות (בדרך מלחמה), משא\"כ הבירור שע\"י פנימיות התורה, אילנא דחיי (שאינה מלובשת בטו\"ר)<sup data-n=\"757\">40</sup>, הוא שלא בדרך התלבשות, מלמעלה למטה.\nז) <b>והנה</b> חילוק הנ\"ל שבין נגלה דתורה לפנימיות התורה הוא בכללות, אבל בפרטיות, יש בכל א' מהם שני הענינים (כי תורה כללות ופרטות נאמרה<sup data-n=\"758\">41</sup>). והענין הוא, כמ\"ש אדה\"ז, בעל הגאולה די\"ט כסלו [דשבת זה מיני' מתברכין כולהו יומין שלאחריו<sup data-n=\"759\">42</sup>, כולל יום הגאולה י\"ט כסלו] בתניא<sup data-n=\"760\">43</sup> דלימוד פנימיות התורה היא \"מצוה רמה<sup data-n=\"761\">44</sup> ונשאה כו' ומביאה ללב שלם\", היינו, דבלימוד פנימיות התורה שני ענינים. הא', שמביאה ללב שלם, דענין זה שבפנימיות התורה שייך לבירור המדות, והב', שהלימוד והידיעה דפנימיות התורה (מצד עצמו) הוא \"מצוה רמה ונשאה\" – ענין פנימיות התורה שלמעלה מבירורים<sup data-n=\"762\">45</sup>. ועד\"ז לאידך גיסא, שגם בנגלה דתורה ישנם ענינים שלמעלה מענין הבירורים. וכמו הלימוד באופן ד\"דרוש וקבל שכר\"<sup data-n=\"763\">46</sup> שאינו נוגע למעשה, שהוא (בנגלה דתורה גופא) למעלה מענין הבירורים. וענין זה(שגם בנגלה דתורה יש ענין שלמעלה מבירורים) מודגש יותר בתורה שבכתב. דלימוד התושב\"כ בהבנה והשגה, ובפרט לימוד ההוראות שבה (הן בההלכות דתושב\"כ והן בהסיפורים שבה) בנוגע למעשה, שייך לענין הבירורים, משא\"כ לימוד הסיפורים דתושב\"כ כמו שהם מצד עצמם<sup data-n=\"764\">47</sup>, ומכ\"ש הקריאה בתושב\"כ שלמעלה מהשגה לגמרי (שגם זה שאינו מבין אפילו פירוש המלות מקיים מצות ת\"ת<sup data-n=\"765\">48</sup>), הוא כמו פנימיות התורה שלמעלה מבירורים. וכמבואר בלקו\"ת<sup data-n=\"766\">49</sup> דפנימיות התורה היא בכלל שליש<sup data-n=\"767\">50</sup> במקרא. ועד\"ז הוא גם לאידך גיסא, שגם בספר התניא, התושב\"כ דחסידות<sup data-n=\"768\">51</sup> (פנימיות התורה), יש גם ענין ששייך לבירורים, כמ\"ש אדה\"ז בההקדמה וגם בהשער (של התניא) שהוא מיוסד על פסוק<sup data-n=\"769\">52</sup> כי קרוב אליך הדבר מאד בפיך ובלבבך לעשותו לבאר היטב איך הוא קרוב מאד כו', היינו שהכוונה והתכלית דספר התניא הוא לבאר איך לעשותו<sup data-n=\"770\">53</sup>. אלא שענין זה [שהן בנגלה דתורה והן בפנימיות התורה ישנם שני הענינים] הוא בפרטיות, אבל בכללות, נגלה דתורה שייכת לבירורים (ובאופן דהתלבשות), ופנימיות התורה היא אילנא דחיי שלמעלה מענין הבירורים, והבירור שנעשה ע\"י לימוד התורה הוא שלא בדרך התלבשות.\nח) <b>ויש</b> לומר, דכמו שהבירור דיעקב, להיותו באופן דמלמעלמ\"ט (ע\"י גילוי אור עליון), הי' גם בהסדר דמלמעלה למטה, שבירר הג\"ר לפני שבירר המדות, עד\"ז הוא גם בפנימיות התורה, דע\"י לימוד החסידות בהבנה והשגה, נעשה בירור המוחין וגם דנפש הבהמית, כולל גם המוחין שלמעלה משייכות למדות. דהבירור שע\"י נגלה דתורה הוא (בעיקר) בהמדות ובהמוחין השייכים למדות, משא\"כ ע\"י לימוד פנימיות התורה, מכיון שהיא \"מצוה רמה ונשאה\" מצד עצמה (למעלה מזה ש\"מביאה ללב שלם\"), נעשה הבירור גם בעצם המוחין. והגם שהכיבוש דקיני קניזי וקדמוני (עצם המוחין שלמעלה ממדות) יהי' רק לעת\"ל (לאחרי השלימות דבירור המדות והמוחין השייכים למדות), מ\"מ, <i>מעין זה</i> הוא גם עכשיו ע\"י לימוד פנימיות התורה. וזהו מה שמסופר בתורה אופן הבירור דיעקב (ע\"י גילוי אור עליון) וגם סדר הבירור (שהתחיל בהבירור דג\"ר), דשני ענינים אלו הם (ככל הענינים שבתורה) הוראות נצחיות גם עכשיו, כנ\"ל.\nט) <b>ויש</b> להוסיף, דההוראה מסדר הבירורים דיעקב (ג\"ר לפני ז\"ת) היא גם בנוגע להסדר דנגלה ופנימיות התורה. דהגם שהתחלת הלימוד הוא בנגלה דתורה, ובאופן דיגיעה, ואח\"כ הוא הלימוד בפנימיות התורה, וכמ\"ש הרח\"ו<sup data-n=\"771\">54</sup> שעסקההלכה דהאריז\"ל הי' ביגיעה עד שהי' מזיע זיעה גדולה כדי לשבר הקליפה, ומרוב גודל חריפותו הי' מעיין ו' דרכים בהלכה, ורק לאח\"ז הי' מעיין ע\"ד הסוד, אעפ\"כ, ידיעת הענינים היסודיים דפנימיות התורה באופן של הנחה פשוטה שלמעלה מהבנה צ\"ל עוד לפני הלימוד בנגלה דתורה, שעי\"ז, גם לימוד הנגלה (והבירור שעל ידו) הוא באופן נעלה יותר. והענין הוא, דנגלה דתורה הוא בכלל בהגבלה<sup data-n=\"772\">55</sup>, ופנימיות התורה הוא בל\"ג, וע\"י ידיעת הענינים דפנימיות התורה באופן של הנחה פשוטה כנ\"ל, ועאכו\"כ ע\"י הלימוד דפנימיות התורה בהבנה והשגה, ובפרט כשהלימוד גופא הוא באופן דכי ירחיב<sup data-n=\"773\">56</sup>, למעלה ממדידה והגבלה [ובפשטות, שאינו מתחשב עם הזמן, אם הוא עדיין באמצע זמן הסדר או שזה כבר לאחרי הסדר], הנה עי\"ז גם לימוד הנגלה הוא באופן שלמעלה ממדידה והגבלה, וגם הבירור שע\"י לימוד הנגלה, עם היותו בירור בדרך התלבשות, הוא באופן נעלה יותר.\nיו\"ד) <b>והנה</b> הגם דזה מה שע\"י לימוד פנימיות התורה נעשה יתרון בלימוד הנגלה ובהבירור שעי\"ז הוא לכאורה ענין של ירידה לגבי הלימוד דפנימיות התורה כמו שהוא מצד עצמו, אעפ\"כ, מכיון שהשלימות דדירה בתחתונים הוא שהתחתון מצד עצמו יהי' כלי לאלקות, דענין זה הוא דוקא ע\"י הבירור שבדרך התלבשות (כנ\"ל סעיף ה), יש לומר, דע\"י ההמשכה דפנימיות התורה לנגלה דתורה, שעל ידה נעשה יתרון בלימוד הנגלה ובהבירור שע\"י לימוד הנגלה, היא מתעלית למעלה יותר מכמו שהיתה מצד עצמה.\nיא) <b>וזהו</b> וכל בניך לימודי הוי' ורב שלום בניך, דכל בניך לימודי הוי', דאלפין באורייתא דהוי', הוא מעלת לימוד התורה, ובפרט פנימיות התורה (אורייתא דהוי'), כמו שהיא מצד עצמה, ורב שלום בניך א\"ת בניך אלא בוניך הו\"ע הבירור בעולם שע\"י עסק התורה. וכיון שעי\"ז (הבירור שע\"י עסק התורה) נעשה עליית התורה מכמו שהיא מצד עצמה, לכן מבאר ומסיים בהמאמר, שע\"י הענין דבוניך, בנאים העוסקים בבנינו של עולם, יקויים גם בהם (בהתלמידי חכמים עצמם) ורב שלום בניך.\n**********",[["717","*","יצא לאור ב<b>קונטרס י\"ד כסלו – תשמ\"ח</b>, \"לקראת י\"ד כסלו הבעל\"ט, התחלת שנת הששים לחתונת כ\"ק אדמו\"ר שליט\"א עם הרבנית שתליט\"א (תרפ\"ט – תשמ\"ח) . . <i>עש\"ק וישלח</i>,<i> י\"ד כסלו</i>,<i> שנת הקהל</i>,<i> שנת תשמ\"ח</i>\"."],["718","1","ישעי' נד, יג."],["719","2","שנאמר ב\"ש\"פ ויצא, קריאת החתן שי' לתורה, וביום ב' וישלח לילה על החתן-מאָל בישיבת \"תומכי תמימים\" בוואַרשא\"."],["720","3","קונטרס ב – נדפס בסה\"מ קונטרסים ח\"א וגם בקונטרס בפ\"ע. – ראה שם טז, ב ואילך."],["721","4","סוף מס' ברכות."],["722","5","שבת קיד, א."],["723","6","ל' התיב\"ע בישעי' שם."],["724","7","סה\"מ קונטרסים שם יט, סע\"ב."],["725","8","תהלים קכח, ו."],["726","9","לב, ד-ה."],["727","10","ראה גם חזקוני עה\"פ."],["728","11","ראה רד\"ה וישלח תרס\"ו (המשך תרס\"ו ע' קא)."],["729","12","ראה רד\"ה הנ\"ל שם. רד\"ה וישלח תרע\"ג (המשך תער\"ב ח\"א ע' רח)."],["730","13","ד\"ה וישלח תרס\"ו בסופו (המשך תרס\"ו ע' קט)."],["731","14","ראה אוה\"ת וישלח רל, ב ואילך. המשך תרס\"ו שם."],["732","15","המשך תער\"ב שם ע' ריז."],["733","16","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370114\" data-slug=\"torah-or\" data-id=\"3901370114\">תו\"א ס\"פ ויצא (כד, ב</a>). המשך תער\"ב שם פק\"ז (ע' רו) ואילך."],["734","17","ויצא לב, א."],["735","18","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370114\" data-slug=\"torah-or\" data-id=\"3901370114\">תו\"א</a> ויצא סד\"ה וישכם לבן בבוקר (כד, ב). ד\"ה זה דש\"פ ויצא תשמ\"ח."],["736","19","בהמשך תער\"ב שם משמע, דבזה גופא [שבשביל הבירור דעשו הוצרך להמשיך מבחי' לובן העליון] שני ענינים: (א) שבכדי שיוכל להיות הבירור דק\"נ [איזה בירור שיהי', הן הבירור שבדרך מלמעלה למטה והן הבירור שבדרך מלמטה למעלה] צריכה להיות תחלה המשכת אור עליון, כמבואר שם פק\"ח (ע' רט). (ב) לפי שהבירורים דיעקב היו בדרך מלמעלה למטה ע\"י גילוי אור עליון – כ\"מ שם ס\"ע ריז."],["737","20","כ\"ה גם באוה\"ת וישלח רלא, א <i>בסוף הפרק</i>. וראה שם לפנ\"ז ובהמשך תרס\"ו ע' קט עוד ענינים בהחילוק שבין לבן לעשו."],["738","21","אוה\"ת שם רלא, א. המשך תער\"ב שם ס\"ע ריז."],["739","22","מגלה עמוקות אופן רנ (בסופו). וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1301410201\" data-slug=\"likkutei-sichot\" data-id=\"1301410201\">לקו\"ש ח\"ל ע' 137</a>. וש\"נ."],["740","23","דיו\"ד כסלו שנה זו – ה'תשמ\"א (לעיל ע' מו) סעיף ב. וראה בהנסמן שם."],["741","24","ראה המשך תער\"ב ח\"ב ע' א'מח ואילך. סה\"מ ה'ש\"ת ע' 114 ואילך. ובכ\"מ."],["742","25","במאמרו ד\"ה אל תצר את מואב – נדפס בקונטרס בפ\"ע (קה\"ת, תשל\"ו) ובס' מאמרי אדמו\"ר האמצעי דברים ח\"א בתחלתו. – ראה מאמרי אדמו\"ר האמצעי שם ע' ג ואילך."],["743","26","כידוע בענין \"ויכולו\" – אוה\"ת בראשית מב, ב ואילך."],["744","27","ראה המשך תער\"ב שם (ס\"ע ריז) \"גבי יעקב שהי' הבירור בדרך מלמעלמ\"ט, תחילה הבירור דכח\"ב כו'\"."],["745","28","ראה גם המשך תרס\"ו ע' שמט, שבהבירור דמלמעלמ\"ט \"אינו נשלם עדיין אמיתית הכוונה\"."],["746","29","ראה בארוכה המשך תער\"ב ח\"ג ע' א'ש ואילך."],["747","30","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370121\" data-slug=\"torah-or\" data-id=\"3901370121\">פרשתנו לג, ד</a>. וראה תו\"א פרשתנו כו, א."],["748","31","פרשתנו שם, יד."],["749","32","עובדי' א, כא."],["750","33","פרש\"י עה\"פ וישלח שם, מב\"ר פרשתנו פע\"ח, יד (בסופו). יל\"ש עה\"פ (רמז קלג)."],["751","34","ועד שאמר יעקב \"אם דעתו לעשות לי רעה\" (פרש\"י שם)."],["752","35","<a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא רפל\"ז</a>."],["753","36","<a class=\"ft-cite\" href=\"#/read/tanya/3401310022\" data-slug=\"tanya\" data-id=\"3401310022\">תניא רפי\"ז</a>."],["754","37","ובפרט הענינים דיעקב – ראה ד\"ה ושבתי בשלום ה'תשל\"ח (לעיל ע' כב) סעיף ז. וש\"נ."],["755","38","ראה רמב\"ן עה\"פ לך לך יב, ו. ד\"ה הנ\"ל סעיף ב, ובהנסמן שם בהערות 12; 14."],["756","39","הנ\"ל הערה 23 – סעיף ג."],["757","40","אגה\"ק סכ\"ו."],["758","41","חגיגה ו, ב."],["759","42","זח\"ב סג, ב. פח, א."],["760","43","בקו\"א קנו, ב."],["761","44","כצ\"ל – ראה לוח התיקון לתניא שם."],["762","45","ובתניא שם הוא בסדר דמלמעלה למטה."],["763","46","סנהדרין עא, א."],["764","47","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380095\" data-slug=\"likkutei-torah\" data-id=\"4001380095\">לקו\"ת ויקרא ה, ב</a>."],["765","48","ראה הל' ת\"ת לאדה\"ז ספ\"ב. וש\"נ."],["766","49","שם ה, ד."],["767","50","קידושין ל, א. הל' ת\"ת לאדה\"ז פ\"ב ס\"א. וש\"נ."],["768","51","ראה בארוכה מכתב כ\"ק מו\"ח אדמו\"ר שבסוף ספר קיצורים והערות לתניא (ע' קכג ואילך)."],["769","52","נצבים ל, יד."],["770","53","להעיר מהמבואר לקמן סעיף יו\"ד."],["771","54","בטעהמ\"צ פ' ואתחנן."],["772","55","ועד שאפשרי (וצ\"ל) לימוד כל התורה כולה (מנחות צט, ב. הל' ת\"ת לאדה\"ז פ\"א ס\"ה)."],["773","56","לשון הכתוב – ראה יב, כ. שופטים יט, ח. ובספרי ראה שם; פרש\"י שופטים שם: ארץ קני קניזי וקדמוני."]]],[1500370012,"<h3>בס\"ד. ש\"פ וישלח, ח\"י כסלו ה'תש\"מ<sup data-n=\"774\">*</sup></h3>\n<b>מרגלא</b> בפומי' דרבא תכלית חכמה תשובה ומעשים טובים כו' שנאמר<sup data-n=\"775\">1</sup> ראשית חכמה יראת הוי' שכל טוב לכל עושיהם, ללומדיהם לא נאמר אלא לעושיהם<sup data-n=\"776\">2</sup>. ומביא כ\"ק מו\"ח אדמו\"ר במאמרו ד\"ה זה שאמר בש\"פ וישלח תרפ\"ט<sup data-n=\"777\">3</sup> (נדפס בקונטרס דרושי חתונה תרפ\"ט<sup data-n=\"778\">4</sup>) פירוש רש\"י, דחכמה היא תורה, ותכלית חכמה, עיקרה של תורה, הוא שיהא עמה תשובה ומעשים טובים. ומדייק בהמאמר, דעיקרה של תורה הוא הבנה והשגה, שיבין וישיג מה שלומד [ובפרט בתורה שבע\"פ, דכשאינו מבין מה שלומד אין זה נחשב לימוד כלל<sup data-n=\"779\">5</sup>], ובמאמר רז\"ל זה אומר שעיקרה של תורה הוא תשובה ומעשים טובים. ויש לומר, דהטעם שמביא בהמאמר פירוש רש\"י בתכלית חכמה, הוא, כי הפירוש דתכלית ברוב המקומות הוא תכלית הכוונה, וכיו\"ב. ועפ\"ז, פירוש תכלית חכמה תשובה ומעשים טובים הוא, שתכלית הכוונה בלימוד התורה (חכמה) הוא שתביא לתשובה ומעשים טובים<sup data-n=\"780\">6</sup>. ולכן מביא בהמאמר פירוש רש\"י דתכלית חכמה הוא <i>עיקרה</i> של תורה<sup data-n=\"781\">7</sup>. דנוסף לזה <i>שהכוונה</i> דלימוד התורה היא שתביא לתשובה ומעשים טובים, גם ענין התורה עצמה [ואדרבה <i>עיקר</i> ענינה] הוא תשובה ומעשים טובים. ולכן מדייק, דחכמה (תורה) ותשובה ומעשים טובים הם לכאורה שני ענינים שונים.\nב) <b>ואולי</b> יש להוסיף, דחכמה (תורה) ותשובה ומעשים טובים, נוסף לזה שהם ענינים שונים, הם גם כמו הפכים. דבלימוד התורה מודגשת מציאותושל האדם העוסק בתורה, דמצות לימוד התורה היא שיבין וישיג (הענין שלומד) בהשכל שלו. ועד שגם בנוגע לפסק דין צריך לפסוק כפי הבנתו דוקא. וכמו שארז\"ל<sup data-n=\"782\">8</sup> קא מיפלגי במתיבתא דרקיעא כו' הקב\"ה אומר כו' וכולהו מתיבתא דרקיעא אמרי כו', דהטעם על זה שמתיבתא דרקיעא פסקו הדין באופן אחר מהקב\"ה, הוא, כי ע\"פ כללי התורה צריכים הם לפסוק הדין כפי הבנתם. דענין זה הוא אפילו בלימוד התורה שבמתיבתא דרקיעא. ומכש\"כ בלימוד התורה דהאדם למטה, דתורה לא בשמים היא<sup data-n=\"783\">9</sup> וקוב\"ה קא חייך ואמר נצחוני בני נצחוני<sup data-n=\"783\">9</sup>. ובתשובה ומעשים טובים מודגש הביטול דהאדם. דענין התשובה הוא שהאדם יוצא ומתבטל ממציאותו, אסורה מכאן<sup data-n=\"784\">10</sup>, וכ\"ה בנוגע למצוות (מעשים טובים), דנוסף לזה שקיום המצוות צ\"ל (לא מצד השכל, אלא) בדרך עבודת עבד<sup data-n=\"785\">11</sup>, הנה גם הפעולה <i>שנעשית</i> ע\"י קיום המצוות הוא שאברי גוף האדם המקיים את המצוה נעשים מרכבה לרצון העליון<sup data-n=\"786\">12</sup>, דמרכבה הו\"ע הביטול. ואעפ\"כ, עיקרה של תורה (תכלית חכמה) (מציאות) הוא תשובה ומעשים טובים (ביטול).\nג) <b>ונקודת</b> הביאור בזה (בהמאמר<sup data-n=\"787\">13</sup>) ע\"פ מה דאיתא בזהר<sup data-n=\"788\">14</sup> לית מחשבה תפיסא בך כלל, אבל נתפס איהו ברעותא דלבא. דמחשבה [השגה דבינה וגם החכמה שלמעלה מהשגה דבינה, כולל גם ראי' דחכמה<sup data-n=\"789\">15</sup>] תופסת רק בגילויים ולא בעצמות, וע\"י רעו\"ד תופסים בהעצמות. והענין הוא, דבאהבה ב' מדריגות בכללות. אהבה שע\"פ טעם ודעת, ואהבה עצמית שמצד עצם הנשמה שמקושרת עם העצמות. ע\"ד אהבת בן לאביו שהיא אהבה עצמית שמעצם הבן לעצם האב. ואהבה זו נקראת בשם רעותא דלבא. וזהו נתפס איהו ברעותא דלבא, דכמו שהבן מעורר את עצמות האב, דכשהבן צועק אבא ניזוז האב בכל מהותו, כמו\"כ הוא בהנמשל, שהאהבה עצמית שמצד עצם הנשמה תופסת בהעצמות. וזהו שתכלית ועיקר החכמה הוא תשובה ומעשים טובים<sup data-n=\"790\">16</sup>, כי החכמה תופסת רק בגילויים (כנ\"ל), ובכדי לתפוס בהעצמות הוא ע\"י תשובה ומעשים טובים.<b>וצריך</b> להבין, דענין זה (דחכמה תופסת בגילויים, ובכדי לתפוס בהעצמות הוא ע\"י תשובה ומעשים טובים) מבאר רק המעלה שבתשובה ומעשים טובים לגבי חכמה. דהגם שבדרגת הכחות דנפש האדם לימוד התורה הוא נעלה יותר מתשובה ומעשים טובים, דלימוד התורה הוא בהשכל שבו, ותשובה ומעשים טובים הם במדות שבלב ובכח המעשה [תשובה במדות שבלב<sup data-n=\"791\">17</sup>, ומעשים טובים בכח המעשה], מ\"מ, מעלה בתשובה ומעשים טובים שעל ידם דוקא תופסים בהעצמות. אבל ביאור זה הוא לכאורה רק להפירוש שתכלית חכמה הוא תכלית העילוי דחכמה. דכיון שע\"י התשובה ומעשים טובים תופסים בהעצמות, לכן, ע\"י שהחכמה מביאה לתשובה ומעשים טובים, נעשה עילוי גם בחכמה [וע\"ד גדול תלמוד שמביא לידי מעשה<sup data-n=\"792\">18</sup>, דע\"י שהלימוד מביא לידי מעשה הוא גדול יותר מכמו שהוא מצד עצמו]. ומהמשך הענינים שבהמאמר משמע, דענין זה (שחכמה תופסת בגילויים, ובכדי לתפוס בהעצמות הוא ע\"י תשובה ומעשים טובים) הוא גם ביאור על זה <i>שעיקרה</i> של תורה הוא תשובה ומעשים טובים.\nד) <b>ויובן</b> בהקדים, דמ\"ש בהמאמר בהמשך להענין דנתפס איהו <i>ברעותא דלבא</i> שע\"י <i>תשובה ומעשים טובים</i> תופסים בהעצמות, יש לומר ע\"פ המבואר בכ\"מ<sup data-n=\"793\">19</sup>, <i>שקיום התומ\"צ</i> שלאחרי רעו\"ד הוא במדריגה נעלית יותר (כדלקמן). ועפ\"ז יש לומר, דמ\"ש בזהר שנתפס איהו ברעותא דלבא, שני ענינים בזה. שנתפס בהרעותא דלבא עצמה, וזה שהרעותא דלבא היא הקדמה לקיום התומ\"צ שבהם נתפס העצמות ממש. והיינו, שבכדי לתפוס בהעצמות ממש הוא (בעיקר) ע\"י קיום התומ\"צ<sup data-n=\"794\">20</sup>, אלא שזה שע\"י מעשה המצוות תופסים בהעצמות הוא כשהעשי' היא בביטול, והביטול שבעשיית המצוות הוא כשהאהבה המביאה לקיום המצוות היא אהבה עצמית שלמעלה מטעם ודעת, רעותא דלבא. דכשהאהבה<sup data-n=\"795\">21</sup> [שבעת התפלה] היא ע\"פ טעם ודעת, קיום המצוות [שבמשך כל היום] הוא בכדי להמשיך גילוי אלקות. וגם כשהאהבה היא ע\"י ההתבוננות בההפלאה דאוא\"ס, שעי\"ז בא לאהבה רבה דמי<sup data-n=\"796\">22</sup> לי בשמים, שאינו רוצה בכל הגילויים ורק בהעצמות<sup data-n=\"797\">23</sup>, יש מבוקש בקיום המצוות שלו (שבמשך כל היום), להמשיך גילוי עצמות אוא\"ס. וקיום המצוות שלאחרי התעוררות האהבה עצמית (רעותא דלבא) הוא בלי שום מבוקש [גם לא המבוקש דהמשכת גילוי עצמות אוא\"ס] ורק לקיים רצונו ית', בדרך קבלת עול. דהביטול שבקיום המצוותבאופן זה הוא עוד יותר מהביטול שברעו\"ד<sup data-n=\"798\">24</sup>, וע\"י קיום המצוות באופן זה הוא המשכת העצמות.\n<b>ויש</b> לומר, דהטעם לזה שגם ע\"י רעותא דלבא אין תופסים בהעצמות ממש [ובכדי לתפוס בהעצמות הוא דוקא ע\"י קיום המצוות שלאחרי הרעו\"ד], הוא, דכיון שהעצמות הוא מובדל מכל ענין, אי אפשר לתפוס אותו ע\"י שום ענין, אלא ע\"י הרצון <i>שלו</i> (דהעצמות). וכיון שגם האהבה העצמית שמצד עצם הנשמה (רעותא דלבא) היא אהבה ורצון דהאדם, אין נתפס בזה העצמות ממש. וזהו היתרון שבהעבודה דקבלת עול לגבי רעותא דלבא, דרעותא דלבא הוא רצון האדם, וגם כשהרצון שלו הוא בביטול, שאינו רוצה לעצמו כלל וכל רצונו הוא (שיושלם) רצון הקב\"ה<sup data-n=\"799\">25</sup>, מ\"מ, גם רצון זה הוא הרצון של האדם<sup data-n=\"800\">26</sup>, מציאות<sup data-n=\"801\">27</sup>. והעבודה דקבלת עול, שמקבל עליו לקיים ציווי השם גם כשהציווי הוא <i>כנגד</i> רצונו בדוגמת עבד, שעבד הוא <i>מוכרח</i> לקיים רצון האדון, הוא לא מצד המציאות (רצון) שלו אלא מצד <i>עול מלכות שמים</i> המוטל עליו<sup data-n=\"802\">28</sup>. אלא שאעפ\"כ, גם הביטול דקבלת עול אינו תופס בהעצמות ממש, ובכדי לתפוס בהעצמות הוא דוקא ע\"י קיום התומ\"צ<sup data-n=\"803\">29</sup>, דכיון שכל הענינים הם באין ערוך וכלא חשיב לגבי' ית', הרי אין שייך שיהי' איזה ענין שעל ידו יכולים לתפוס בי' ית'. ובכדי לתפוס את העצמות הוא דוקא ע\"י שהעצמות רוצה בזה. וזהו שע\"י קיום התומ\"צ תופסים בהעצמות, כי המצוות הם רצון העצמות. היינו, דזה שע\"י התומ\"צ תופסים בהעצמות הוא לא מצד מעלת התומ\"צ עצמם, אלא לפי שהוא רצון העצמות. וזה שקיום המצוות צ\"ל בביטול [אף שלגבי העצמות ביטול ומציאות הם בשוה ממש], הוא, בכדי שהמשכת העצמות שע\"י קיום המצוות תהי' בגילוי. דכשעשיית המצוה של האדם היא באופן שנרגשת המציאות שלו, <i>שהוא</i> המקיים את המצוה, הרגש המציאות הוא כמו סותר לגילוי העצמות. וכיון שכשהאדם מקיים את המצוות מצד הרצון שלו, גם כשהרצון שלו הוא להשלים רצון הקב\"ה, נרגשת מציאותו, לכן, בכדי שהמשכת העצמות שע\"י קיום המצוות תהי' בגילוי, הואע\"י שקיום המצוות הוא בדרך קבלת עול, לא מצד הרצון שלו אלא מצד עול מלכות שמים המוטל עליו.\nה) <b>והנה</b> ידוע<sup data-n=\"804\">30</sup>, דשני הענינים דבן ועבד הם בדרך כלל בלימוד התורה ובקיום המצוות. ואולי יש לומר ביאור בזה, דהחילוק בין בן לעבד הוא, דהעבד הוא <i>בטל</i> להאדון, וענין בן הוא <i>שמציאותו</i> הוא האב. וכמבואר בהמשך תרס\"ו<sup data-n=\"805\">31</sup> דמה שהוא רצון האב הוא גם רצון הבן, וכמו שמחייב שכל האב כן מחייב שכל הבן. וענינים אלה (בן ועבד) שבכל אחד מישראל מתגלים ע\"י לימוד התורה וקיום המצוות. דבקיום המצוות, שקיום המצוות הוא לקיים ציווי השם בדרך קבלת עול, מתגלה העבד שבו, ובלימוד התורה שצריכה להיות בהבנה והשגה דוקא, שהשכל של האדם העוסק בתורה יהי' בהתאם לחכמתו של הקב\"ה, מתגלה הבן שבו. ויש להוסיף, דגם זה שהפס\"ד דהאדם העוסק בתורה צריך להיות כפי הבנתו דהאדם, דתורה לא בשמים היא, הוא מצד ענין הבן שבישראל, וכמאמר רז\"ל קוב\"ה קא חייך ואמר נצחוני <i>בני</i> נצחוני, דהטעם על זה שנצחוני הוא לפי שהם <i>בני</i>. והיינו<sup data-n=\"806\">32</sup>, כי שרש הבן הוא בעצמות האב שלמעלה מכחות הגלויים שלו, ועד\"ז בישראל, בניו של הקב\"ה, ששרשם הוא בעצמותו ית' למעלה מכמו שצמצם את עצמו בתואר קוב\"ה, ולכן הם יודעים ומשיגים<sup data-n=\"807\">33</sup> אמיתית התורה כמו שהיא מושרשת בהעצמות שלמעלה מדרגת התורה כמו שנמשכה בידיעת קוב\"ה.\nו) <b>והנה</b> נוסף לשני הענינים דבן ועבד, יש עוד ענין בעבודת האדם, קיום המצוות. וכמו שנת\"ל (סעיף ד), דבקיום המצוות שני ענינים. הביטול דקב\"ע שבקיום המצוה, וקיום המצוה עצמה. ועיקר הענין דהמשכת העצמות הוא ע\"י קיום המצוה עצמה – רצון העצמות, אלא שבכדי שהמשכת העצמות שבקיום המצוה תהי' בגילוי הוא כשקיום המצוה היא בדרך קבלת עול, עבד. והשלימות דענין זה (שקיום המצוות הוא בלי שום מבוקש ורק לקיים רצונו ית' בדרך קבלת עול) הוא ע\"י קדימת התעוררות האהבה עצמית (רעותא דלבא), בן.\n<b>ויש</b> לומר, דג' ענינים אלה הם ג' הענינים דחכמה תשובה ומעשים טובים. חכמה (תורה) הו\"ע בן (כנ\"ל סעיף ה), תשובה שענינה הוא שהאדם יוצא ומתבטל ממציאותו (כנ\"ל סעיף ב), הוא ע\"ד הענין דקבלת עול, עבד, ומעשים טובים הם המצוות עצמם, רצון העצמות.\n<b>ויש</b> לקשר זה עם פירוש הידוע<sup data-n=\"808\">34</sup> בהלשון תשובה ומעשים טובים, שעל ידי התשובה נעשים המעשים (מעשה המצוות) מעשים טובים ומאירים<sup data-n=\"809\">35</sup>, דהמשכתהעצמות היא (בעיקר) בקיום המצוות (מעשים), ולא בהביטול דתשובה (ודקבלת עול). אלא שבכדי שהמעשים יהיו מעשים טובים ומאירים, שהמשכת העצמות שבהם תהי' בגילוי, הוא ע\"י הביטול דתשובה וקבלת עול.\nז) <b>והנה</b> הגם שענין עסק התורה הוא <i>שמציאותו</i> של האדם (ההבנה וההשגה שלו) תהי' בהתאם להתורה, מ\"מ, גם בלימוד התורה צ\"ל הביטול דעבד, <i>עולה</i> של תורה<sup data-n=\"810\">36</sup>. וזהו שארז\"ל<sup data-n=\"811\">37</sup> שאינו דומה שונה פרקו מאה פעמים לשונה פרקו מאה פעמים ואחד, לפי שבפעם זו היתירה משנה טבעו ורגילותו<sup data-n=\"812\">38</sup>, שגם בתורה צ\"ל הביטול דעבד<sup data-n=\"813\">39</sup>.\n<b>ונקודת</b> הביאור בזה, דזה שבן ועבד הם שני ענינים, הוא בהנשמה כמו שבאה בהמשכה, אבל בשרש הנשמה כמו שהיא מושרשת בהעצמות ממש, שני הענינים שבה הם חד. ועד\"ז הוא בתורה ומצוות, דכמו שהם בהעצמות, שניהם הם ענין אחד. ולכן, גם בלימוד התורה צריך להיות גם הביטול דעבד. דע\"י לימוד התורה בבחינת בן בלבד, ההתקשרות דישראל באורייתא<sup data-n=\"814\">40</sup> היא בהדרגא דתורה כמו שבאה בהמשכה [שהתורה והמצוות נעשו שני ענינים], ובכדי שתהי' ההתקשרות בעצם התורה כמו שמושרשת בהעצמות [ששם התורה והמצוות הם חד], הוא ע\"י שבלימוד התורה שלו מודגשים שני הענינים. דתורה לא בשמים היא אלא ניתנה לרשותו, שלכן הפסקי דינים שלו הם כפי הבנתו דוקא ואין משגיחין בבת קול&lt;9&gt; – מציאות דבן, וביחד עם זה הוא מקבל עליו <i>עול</i> תורה, שהתורה היא ה\"אדון\" שלו והוא בטל להתורה כעבד שמוטל עליו עול האדון.\nח) <b>וזהו</b> תכלית חכמה תשובה ומעשים טובים, דעיקרה של תורה הוא שיהא <i>עמה</i> תשובה ומעשים טובים. דנוסף לזה שהתורה <i>מביאה</i> לתשובה ומעשים טובים, התשובה ומעשים טובים צריכים להיות עמה, עם התורה עצמה, שבלימוד התורה יהי' גם הביטול דתשובה ומעשים טובים. [ויש לומר, דזה שאומר שיהא עמה תשובה ומעשים טובים, הוא, כי הביטול דתשובה (מה שהאדם יוצא ממציאותו, אסורה מכאן), הוא מצד ההרגש שלו, ולכן גם בהביטול מעורב (בדקות) המציאות שלו, ואמיתית הביטול הוא הביטול דמעשים טובים, דזה שקיום המצוות הוא בדרך קבלת עול הוא לא מצד הרצון שלו אלא מצד עול מלכות שמים המוטל עליו (כנ\"ל סוף סעיף ד). ובפרט להביאור דלעיל (סעיף ו) שהכוונה במעשים טובים היא להמצוות (מעשים) עצמם, דלפי ביאור זה, הביטול דמעשים טובים הוא שאין נרגש בו גם זה שהוא בטל להאדון, ומה שנרגש הוא רק רצון העליון. ותכלית חכמה הוא שיהא עמה תשובה ומעשים טובים, שבלימוד התורה שלו יהי' הביטול דתשובה וגםהביטול דמעשים טובים]. וענין זה הוא עיקרה של תורה, כי עי\"ז תופסים בעיקר ושרש התורה כמו שהיא מושרשת בהעצמות.\n<b>ויש</b> להוסיף, דהטעם על זה שמאמר זה (תכלית חכמה תשובה ומעשים טובים) הי' מרגלא בפומי' דרבא דוקא, כי בלימוד התורה שני אופנים בכללות, אופן הלימוד דאביי ואופן הלימוד דרבא [שלכן, בהויות דאביי ורבא נכללים כל הענינים דתושבע\"פ<sup data-n=\"815\">41</sup>]. והחילוק שבין שני האופנים הוא כדאיתא בגמרא<sup data-n=\"816\">42</sup> אדמגרמיתו גרמי בי אביי תו אכלי בשרא שמינא בי רבא. וכיון שלימוד התורה דרבא הי' באופן של בישרא שמינא (הלכות צהובות מרווחות<sup data-n=\"817\">43</sup>), שבהלימוד באופן זה מודגשת המציאות של האדם הלומד, ובפרט שהנהגתו היתה שמקמי דפתח להו לרבנן אמר מילתא דבדיחותא<sup data-n=\"818\">44</sup>, לכן הי' מרגלא בפומי' המאמר תכלית חכמה תשובה ומעשים טובים, שבלימוד התורה צ\"ל גם הביטול דתשובה ודמעשים טובים.\nט) <b>והנה</b> ידוע שכל הענינים שבדרושי רבותינו נשיאינו, כולל גם זמן אמירתם, הם בתכלית הדיוק. ועפ\"ז יש לומר, דמהטעמים שדרוש זה אמרו כ\"ק מו\"ח אדמו\"ר בש\"פ וישלח, השבת שלפני י\"ט כסלו, הוא, כי ענין הנ\"ל מרומז בהפסוק<sup data-n=\"819\">45</sup> פדה בשלום נפשי גו' השייך לי\"ט כסלו<sup data-n=\"820\">46</sup>, ובהפסוק קטונתי מכל החסדים ומכל האמת גו' שבפרשת וישלח<sup data-n=\"821\">47</sup> וגם שייך להגאולה די\"ט כסלו<sup data-n=\"822\">48</sup>. והענין הוא, דג' הענינים שבמארז\"ל הנ\"ל [חכמה, תשובה ומעשים טובים] שייכים לג' העמודים<sup data-n=\"823\">49</sup> דתורה עבודה וגמ\"ח. חכמה – תורה, תשובה – עבודה, כי תפלה (עבודה<sup data-n=\"824\">50</sup>) הו\"ע הביטול, שהאדם המתפלל הוא כעבד בפני רבו<sup data-n=\"825\">51</sup>, ומעשים טובים – גמילות חסדים, דגמ\"ח הוא כללות כל המצוות<sup data-n=\"826\">52</sup>.\n<b>והנה</b> דרז\"ל<sup data-n=\"827\">53</sup> פדה בשלום נפשי גו', כל העוסק בתורה ובגמ\"ח ומתפלל עם הצבור כו' כאילו פדאני לי ולבני מבין האומות, שהפדי' היא ע\"י ג' הענינים דתורהגמ\"ח ותפלה (בצבור). ועד\"ז הוא בהפסוק קטונתי מכל החסדים ומכל האמת, דחסדים לשון רבים הם ב' הקוין דגמ\"ח ותפלה. וכידוע<sup data-n=\"828\">54</sup> שתפלה היא בכלל גמ\"ח. [ונאמר החסדים לשון רבים, כי החסד דגמ\"ח (מצוות) והחסד דתפלה, הם שני חסדים. ובפרט לפי הידוע<sup data-n=\"829\">55</sup> שתפלה היא בקו הגבורה, העלאה מלמטה למעלה. דמזה מובן, שהחסד שבתפלה אינו כהחסד שבגמ\"ח]. ואמת הוא תורה, אין אמת אלא תורה<sup data-n=\"830\">56</sup>. ואומר קטונתי מכל החסדים ומכל האמת, דענין הביטול (קטונתי) הוא לא רק מכל החסדים, הקוין דתפלה וגמ\"ח (תשובה ומעשים טובים), אלא גם מכל האמת, תורה (חכמה). ועד\"ז הוא במארז\"ל עה\"פ פדה בשלום נפשי, שהדיוק הוא כל <i>העוסק</i> בתורה (ולא הלומד תורה). דענין עוסק בתורה הוא (כמו שמבאר כ\"ק מו\"ח אדמו\"ר<sup data-n=\"831\">57</sup>), שנוסף על זה שהוא לומד לעצמו, הוא משתדל בכל מיני השתדלות להביא את הרבים לידי לימוד התורה. דזה שאינו מסתפק בזה שהוא עצמו לומד ומשתדל להביא את הרבים ללימוד התורה, ובפרט כשנותן על זה מזמנו שהי' יכול ללמוד לעצמו, הוא מצד <i>הביטול</i> שלו לתורה.\nי) <b>והנה</b> נתבאר לעיל (סעיף ז), שהחיבור דשני הענינים דבן ועבד הוא ע\"י גילוי עצם הנשמה כמו שמושרשת בהעצמות, דבעצם הנשמה שני הענינים דבן ועבד הם כולא חד. ועפ\"ז יש לבאר הסדר דמרז\"ל הנ\"ל (כל העוסק בתורה ובגמ\"ח ומתפלל עם הצבור), שמקדים תורה לגמ\"ח ותפלה, הגם שבסדר עבודת האדם בכלל לימוד התורה הוא (בעיקר) לאחרי התפלה<sup data-n=\"832\">58</sup> [שבאה לאחרי קדימת גמ\"ח, כמרז\"ל<sup data-n=\"833\">59</sup> יהיב פרוטה לעני והדר מצלי], כי אמיתית הענין דפדה בשלום נפשי הוא ע\"י גילוי היחידה<sup data-n=\"834\">60</sup>. ועד\"ז הוא בנוגע להענין דפדאני לי ולבני מבין האומות, דזה שענין זה יהי' בביאת המשיח דוקא הוא לפי שמשיח הוא היחידה דכללות ההשתלשלות<sup data-n=\"835\">61</sup>. ויש לומר, דהכוונה כאן ביחידה היא (לא רק לדרגא הפרטית דיחידה, אלא גם) לעצם הנשמה. ולכן מקדים תורה לגמ\"ח ותפלה, כי הגילוי דעצם הנשמה הוא ע\"י העוסק בתורה [דזה שתורה (בן) היא באופן דעוסק (עבד) הוא מצד עצם הנשמה], ולכן, ענין זה הוא ההכנה העיקרית לביאת המשיח, היחידה דכללות ההשתלשלות.<b>ולהוסיף</b><b>,</b> שע\"י גילוי היחידה דכללות ההשתלשלות שיהי' לעתיד לבוא, יתוסף עילוי בכל ג' הענינים (חכמה, תשובה ומעשים טובים), ועד לעילוי שבאין ערוך. דבנוגע לתורה (חכמה) ארז\"ל<sup data-n=\"836\">62</sup> שהתורה דעכשיו היא הבל לגבי תורתו של משיח, ובנוגע לתשובה ידוע<sup data-n=\"837\">63</sup> שמשיח אתא לאתבא <i>צדיקייא</i> בתיובתא, שהתשובה דצדיקים נעלית יותר מתשובה כפשוטה, ובנוגע למעשים טובים ידוע<sup data-n=\"838\">64</sup> שבביאת המשיח יהי' קיום המצוות בתכלית השלימות. ויש לומר, שבהשלימות דמעשים טובים ומאירים שיהי' אז נכלל גם שכל הענינים דעולם העשי' יהיו מאירים, ועד שגם לילה כיום יאיר<sup data-n=\"839\">65</sup>, בגאולה האמיתית והשלימה ע\"י משיח צדקנו, ובאופן דמיד הן נגאלין<sup data-n=\"840\">66</sup>.\n**********",[["774","*","יצא לאור ב<b>קונטרס י\"ד כסלו – תנש\"א</b>, \"בקשר עם יום הבהיר י\"ד כסלו, יום נישואי כ\"ק אדמו\"ר שליט\"א עם הרבנית הצדקנית מרת חי' מושקא נ\"ע זי\"ע (בשנת תרפ\"ט) . . <i>טו כסלו</i>,<i> שנת ה'תנש\"א</i>\". \"המאמר מיוסד על ד\"ה זה שאמר כ\"ק אדמו\"ר מהוריי\"צ נ\"ע בש\"פ וישלח תרפ\"ט בסעודת שבע ברכות, שנדפס בקונטרס דרושי חתונה תרפ\"ט\"."],["775","1","תהלים קיא, י."],["776","2","ברכות יז, א."],["777","3","\"בסעודת שבע ברכות\"."],["778","4","קונטרס ב – נדפס בסה\"מ קונטרסים ח\"א כח, סע\"ב ואילך. סה\"מ תרפ\"ט ע' 104 ואילך."],["779","5","מג\"א או\"ח ס\"נ סק\"ב. שו\"ע אדה\"ז שם ס\"ב. הל' ת\"ת לאדה\"ז פ\"ב סי\"ג."],["780","6","להעיר מחדא\"ג מהרש\"א לברכות שם. הל' ת\"ת לאדה\"ז פ\"ד ס\"ג-ד."],["781","7","ואולי יש לומר, דמקורו של רש\"י שפירוש \"תכלית\" כאן הוא <i>עיקר</i>, הוא, כי ענין זה למידין בברכות שם מהכתוב (תהלים קיא, י) \"<i>ראשית</i> חכמה יראת ה'\", דיראת ה' היא <i>ראשית</i> החכמה. ולהפירוש שהתכלית דלימוד התורה הוא <i>שתביא</i> לתשובה ומעשים טובים – היראה היא <i>לאחרי</i> החכמה. ולכן מפרש ש\"תכלית חכמה\" הוא <i>עיקרה</i> של תורה, עיקרה וראשיתה*. ויומתק יותר ע\"פ המבואר לקמן ס\"ח דעיקרה של תורה הוא עיקר ושרש התורה כמו שהיא בהעצמות.\n*) <i>להעיר מפירוש הראב\"ע עה\"פ לכל תכלה ראיתי קץ (תהלים קיט</i>,<i> צו) </i>\"<i>קץ בלשוננו פעם ראש ופעם סוף</i>\".<i> ובהמשך תרס\"ו ע' כ</i>,<i> דלפירוש הראב\"ע פירוש תכלה (בתהלים שם) הוא </i><b>תחילה</b>.<i> ומזה מובן</i>,<i> שעד\"ז הוא בנוגע ל</i>\"<i>תכלית</i>\"<i> (מלשון תכלה)</i>,<i> שלפעמים פירושו הוא </i><b>תחלה וראש</b>."],["782","8","ב\"מ פו, א."],["783","9","שם נט, ב."],["784","10","ל' רש\"י עה\"פ שמות ג, ג. וראה סה\"ש ה'תש\"ב (ע' 47) דקאי על עבודת התשובה."],["785","11","<a class=\"ft-cite\" href=\"#/read/tanya/3401310046\" data-slug=\"tanya\" data-id=\"3401310046\">תניא רפמ\"א</a>. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380472\" data-slug=\"likkutei-torah\" data-id=\"4001380472\">לקו\"ת שלח מ, א</a>. ובארוכה – עטרת ראש דרוש לעשי\"ת נז, א. שם נט, ב. וראה לקמן ס\"ד."],["786","12","<a class=\"ft-cite\" href=\"#/read/tanya/3401310028\" data-slug=\"tanya\" data-id=\"3401310028\">תניא פכ\"ג (כח, ב</a>)."],["787","13","ס\"ב ואילך (סה\"מ קונטרסים שם כט, סע\"א ואילך. תרפ\"ט ע' 105 ואילך). וראה בהבא לקמן גם המשך תרס\"ו ס\"ע נז ואילך. סה\"מ תרפ\"ז ע' קעה."],["788","14","כן הובא בשם הזהר בהמצויין בהערה שלפנ\"ז <i>ובכ\"מ</i> בדא\"ח. וראה זח\"ג רפט, ב (באד\"ז): דלא אתידע ולא אשתמודע כו' אלא ברעותא דלבא. ובתקו\"ז בהקדמה (\"פתח אליהו\") יז, א: לית מחשבה תפיסא בך כלל."],["789","15","ראה בהמאמר שם ריש ס\"ד (סה\"מ קונטרסים שם ל, ב. תרפ\"ט ע' 108), דמחשבה הוא אותיות חש\"ב מ\"ה. חש\"ב הוא ההנחה שכלית, ומ\"ה הוא ראי' דחכמה, ולית מחשבה תפיסא בי', שגם המ\"ה אינו תופס בהעצמות."],["790","16","הביאור בהמשך הענינים שבהמאמר – שהמעלה <i>דתשובה ומעשים טובים</i> בא בהמשך לזה שנתפס איהו <i>ברעותא דלבא</i> – ראה לקמן ס\"ד."],["791","17","להעיר מ<a class=\"ft-cite\" href=\"#/read/tanya/3401310034\" data-slug=\"tanya\" data-id=\"3401310034\">תניא פכ\"ט (לו, ב</a>) \"עיקר התשובה בלב\"."],["792","18","קידושין מ, ב. וש\"נ."],["793","19","המשך תרס\"ו ע' סא. סה\"מ תרפ\"ז ע' קפא. וראה גם המשך תער\"ב ח\"א פקצ\"ה (ע' שצו)."],["794","20","להעיר מ<a class=\"ft-cite\" href=\"#/read/tanya/3401310009\" data-slug=\"tanya\" data-id=\"3401310009\">תניא ספ\"ד (ט, א</a>) \"הקב\"ה בכבודו ובעצמו לית מחשבה תפיסא בי' כלל כי אם כאשר תפיסא ומתלבשת בתורה ומצוותי'\", דמפשטות הלשון \"<i>כי אם</i> כו' בתורה ומצוותי'\" משמע שכל שאר הענינים [גם רעו\"ד, וגם הביטול דקב\"ע – ראה לקמן בפנים] אינם תופסים בהעצמות."],["795","21","בהבא לקמן ראה המשך תרס\"ו וסה\"מ תרפ\"ז שם."],["796","22","לשון הכתוב – תהלים עג, כה."],["797","23","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380160\" data-slug=\"likkutei-torah\" data-id=\"4001380160\">לקו\"ת תזריע כ, סע\"א</a> ואילך. שורש מצות התפלה להצ\"צ פ\"מ (דרמ\"צ קלח, סע\"א). לקמן ח\"ג ע' קלד ואילך."],["798","24","כ\"ה בהמשך תרס\"ו וסה\"מ תרפ\"ז שם. ובסה\"מ תרפ\"ז שם ס\"ע קפב, דמעלתן של ישראל כמו שהם בעצמותו ית' הוא (לא זה שהם בנים, רעו\"ד, אלא) זה \"שהם עבדים בהעבודה דקבעומ\"ש דוקא\". וראה לקמן בפנים."],["799","25","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310046\" data-slug=\"tanya\" data-id=\"3401310046\">תניא פמ\"א (נז, ב</a> ואילך) ובארוכה בסה\"מ תר\"פ ע' קמט ואילך, שגם באהבה העצמית שמצד עצם הנשמה, שתי דרגות. הרצון \"לדבקה בה' ולא ליפרד כו' בשום אופן אפילו במסירת נפש ממש\", דרצון זה הוא בחינת מציאות; וענין הביטול הוא שכל רצונו הוא רצון ה' – שיהי' גילוי אלקות בעולם."],["800","26","וראה המשך תרס\"ו ע' שסא, דעבודתו של העבד (הפשוט) נקראת על שם אדונו, משא\"כ זה שהבן עובד עבור אביו [וכן זה שעבד נאמן עובד עבור אדונו] אינה נחשבת כעבודת האב עצמו, ולכן אין בזה תענוג כ\"כ."],["801","27","דהביטול שברצון זה הוא בה\"צורה\" שלו שאינו רוצה לעצמו ורק שיושלם רצון הקב\"ה, אבל עצם הרצון (ה\"חומר\") הוא מציאות."],["802","28","ויש לומר, דענין זה שייך גם בצדיק שאין לו יצה\"ר. כי המעלה דעבד המבוארת כאן היא [לא זה שיש לו רצון אחר והוא כופה את עצמו, המעלה דאתכפיא, כי אם] <i>הביטול</i> שלו, שהוא <i>מוכרח</i> לקיים ציווי האדון גם <i>באם</i> הי' הציווי נגד רצונו. וזה שבפועל הוא רוצה לקיים הציווי – אין זה גורע בהביטול, מכיון שגם באם הציווי הי' כנגד רצונו, הוא מוכרח בזה."],["803","29","ראה לעיל הערה 20."],["804","30","המשך תרס\"ו ע' שסד ואילך. ובכ\"מ."],["805","31","ס\"ע שח ואילך."],["806","32","בהבא לקמן ראה בפרטיות יותר לעיל ח\"א ס\"ע לא ואילך."],["807","33","ראה <i>עד\"ז</i> המשך תער\"ב ח\"ב ע' תתק."],["808","34","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381199\" data-slug=\"likkutei-torah\" data-id=\"4001381199\">לקו\"ת</a> דרושים לשמע\"צ פה, א. שה\"ש יז, ג. וראה לקו\"ש ח\"ד ע' 1053 ואילך."],["809","35","דפירוש \"טובים\" הוא מאירים, כמ\"ש (בראשית א, ד) \"את האור כי טוב\" (לקו\"ת שה\"ש שם)."],["810","36","ראה במדב\"ר פי\"ח, כא. תדא\"ר רפ\"ב. מדרש שמואל פכ\"ט. וראה לקו\"ת פ' ראה ד\"ה וכל בניך ס\"ב (כט, ג ואילך)."],["811","37","חגיגה ט, ב."],["812","38","תניא פט\"ו."],["813","39","לקו\"ת שם."],["814","40","ראה זח\"ג עג, א."],["815","41","ראה סוכה כח, א."],["816","42","ב\"ב כב, א."],["817","43","פרש\"י ב\"ב שם ד\"ה דאמר להו וד\"ה תו."],["818","44","<a class=\"ft-cite\" href=\"#/read/tanya/3401310012\" data-slug=\"tanya\" data-id=\"3401310012\">פסחים קיז, א</a>.\nבש\"ס ועין יעקב פסחים שם: <i>רבה</i>. אבל בתניא פ\"ז (יא, ב) הביא גירסת רבינו חננאל שם (וכ\"ה ביל\"ש מלכים-ב רמז רכז): <i>רבא</i>. וראה שיחת יו\"ד שבט ה'תשכ\"ד (נעתק בלקוטי ביאורים (להר\"י שי' קאָרף) לתניא שם)."],["819","45","תהלים נה, יט."],["820","46","כמ\"ש אדה\"ז בנוגע לגאולתו בי\"ט כסלו (אגרות-קודש שלו סי' לח. וש\"נ) \"כשקריתי בס' תהלים בפסוק פדה בשלום נפשי כו' יצאתי בשלום כו'\"."],["821","47","לב, יא."],["822","48","כמובן מאגה\"ק (ס\"ב) ד\"ה קטונתי שכתבה בעל הגאולה \"אחר ביאתו מפ\"ב\"."],["823","49","אבות פ\"א מ\"ב."],["824","50","תענית ב, א. רמב\"ם הל' תפלה בתחלתו. סהמ\"צ להרמב\"ם מ\"ע ה. רבינו יונה לאבות שם."],["825","51","שבת יו\"ד, א."],["826","52","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא פל\"ז (מח, ב</a>). לעיל ח\"א ע' רנח, ובהנסמן שם הערה 33."],["827","53","ברכות ח, א."],["828","54","כמארז\"ל עה\"פ (משלי יא, יז) גומל נפשו איש חסד – ראה פרש\"י ד\"ה ה\"ג – שבת קכז, ריש ע\"ב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380094\" data-slug=\"likkutei-torah\" data-id=\"4001380094\">לקו\"ת ויקרא ה, א</a>. אוה\"ת משפטים ע' א'קנו. ובכ\"מ."],["829","55","דג' הענינים שעליהם העולם עומד הם בג' הקוין חג\"ת – אוה\"ת (יהל אור) לתהלים עה\"פ ס\"ב (ע' רד). ד\"ה פדה בשלום תרע\"ח (תש\"ז) פ\"א ואילך (סה\"מ תרע\"ח ע' צג ואילך. ה'תש\"ז ע' 202 ואילך). <i>ובכ\"מ</i>."],["830","56","ירושלמי ר\"ה פ\"ג ה\"ח. ועוד."],["831","57","ד\"ה הסכת ושמע ישראל תרצ\"ג ס\"ב ואילך (סה\"מ קונטרסים ח\"א רנט, א). וראה גם סד\"ה אריב\"ל דבר זה כתוב כו' וסד\"ה אריב\"ל בכל יום כו' – תרפ\"ח (סה\"מ תרפ\"ח ע' קיב. שם ע' קכז)."],["832","58","ראה סוף מס' ברכות. טושו\"ע (ודאדה\"ז) או\"ח ר\"ס קנה. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381112\" data-slug=\"likkutei-torah\" data-id=\"4001381112\">לקו\"ת ברכה צו, ב</a>. ועוד. וראה גם לקמן ע' קנב ואילך."],["833","59","ב\"ב יו\"ד, א. רמב\"ם הל' מתנות עניים פ\"י הט\"ו. טושו\"ע (ודאדה\"ז) או\"ח סו\"ס צב. טושו\"ע יו\"ד סרמ\"ט סי\"ד."],["834","60","ד\"ה פדה בשלום בשערי תשובה ח\"א (שער התפלה) ספ\"ו (נב, ג) ואילך. וראה בארוכה ד\"ה זה ה'תשל\"ט ס\"ד ואילך (לעיל ע' מא ואילך)."],["835","61","נסמן לעיל ע' סד הערה 55."],["836","62","קה\"ר פי\"א, ח. ועיין ג\"כ שם פ\"ב, א."],["837","63","הובא ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381329\" data-slug=\"likkutei-torah\" data-id=\"4001381329\">לקו\"ת</a> דרושים לשמע\"צ צב, ב. שה\"ש נ, סע\"ב. ובהנסמן במאמרי אדמו\"ר האמצעי דברים ח\"ג ע' א'קכט. וראה זח\"ג קנג, ב."],["838","64","ראה בהנסמן בד\"ה ויהיו חיי שרה תנש\"א הערה 49 (לעיל ח\"א ע' רצט)."],["839","65","תהלים קלט, יב."],["840","66","רמב\"ם הל' תשובה פ\"ז ה\"ה."]]]]});
